window.GAME_DATA = {"title":"潮約之歌","builtAt":"2026-10-20T08:42:05.458Z","source":"script","protagonist":"孫承完","sideRoute":"人魚篇","stats":["心動","信任","採息"],"chars":{"孫承完":{"exprs":["普通","笑","害羞","驚訝","難過","認真"],"face":true},"裴柱現":{"exprs":["普通","笑","得意","害羞","生氣","驚慌","難過","恍惚","魅惑","哭"],"face":false},"阿英":{"exprs":["普通","笑","擔心","認真"],"face":false},"康":{"exprs":["普通","大笑","慌張"],"face":false},"珊婆":{"exprs":["普通","吐槽"],"face":false},"澪":{"exprs":["普通","冷笑","怒"],"face":false},"潮后":{"exprs":["普通"],"face":false}},"files":[{"key":"01_第一章_生日營火","name":"01_第一章_生日營火.md","route":"main","num":1,"title":"第一章　生日營火","ops":[{"t":"title","text":"開場","card":false,"ln":1},{"t":"bg","name":"全黑","ln":3},{"t":"se","names":["海浪"],"ln":4},{"t":"say","k":"n","text":"……","id":"4pb3bq","ln":6},{"t":"say","k":"i","text":"（一個不知道是誰聲音，貼著海面，很輕很輕。）","id":"y8zx7y","ln":8},{"t":"say","k":"d","who":"？？？","text":"「……找到了。」","ln":10,"id":"oxx3x4"},{"t":"title","text":"第一章　生日營火","card":true,"ln":14},{"t":"label","id":"1-1","title":"營火","ln":16},{"t":"bg","name":"白鹽灣沙灘・黃昏","ln":18},{"t":"bgm","name":"白鹽灣日常","ln":19},{"t":"say","k":"n","text":"我叫孫承完。白鹽灣的人都叫我「孫奶奶」。","id":"a2o6nw","ln":21},{"t":"say","k":"n","text":"不是因為我的年紀。","id":"1d9nt2x","ln":23},{"t":"say","k":"n","text":"是因為十二歲那年，爸爸出海救人沒有回來，之後我就開始像個老太太一樣，每天叮嚀媽媽吃飯、叮嚀鄰居小孩別在退潮的時候跑太遠、叮嚀全鎮的人颱風天不要靠近堤防。","id":"j2yejg","ln":25},{"t":"say","k":"n","text":"叮嚀久了，這個綽號就跟了我二十年。","id":"1h2yhep","ln":27},{"t":"say","k":"n","text":"二十年後，我成了白鹽灣的救生員。叮嚀的對象從鄰居變成了觀光客，內容倒是沒什麼變。","id":"1xc1twb","ln":29},{"t":"say","k":"d","who":"康","text":"「壽星！壽星發什麼呆！」","ln":31,"id":"11cqeq4"},{"t":"show","list":[{"c":"康","e":"大笑"}],"ln":33},{"t":"say","k":"n","text":"康捧著一個蛋糕從沙灘另頭跑過來，丸子頭跟著一跳一跳。","id":"1623gt2","ln":35},{"t":"say","k":"n","text":"蛋糕做成救生圈的形狀，紅白相間，上面用奶油歪歪扭扭地寫著：","id":"1qgf05q","ln":37},{"t":"say","k":"n","text":"「完<3生日快樂 人生不只有救生衣」。","id":"ze0dht","ln":39},{"t":"say","k":"n","text":"蛋糕的右下角少了一塊。邊緣很整齊，是一口咬下去的形狀。","id":"g6f260","ln":41},{"t":"say","k":"d","who":"孫承完","text":"「……最後一句是誰加的？」","ln":43,"id":"mxqxqe"},{"t":"say","k":"d","who":"康","text":"「民意。」","ln":45,"id":"1t7l2aw"},{"t":"say","k":"d","who":"阿英","text":"「民意個頭，是她自己擠的。擠到一半奶油被她吃掉了，『衣』那個字還少了一撇。」","ln":47,"id":"fsca7a"},{"t":"show","list":[{"c":"阿英","e":"普通"}],"ln":49},{"t":"say","k":"n","text":"阿英提著一桶冰鎮啤酒走過來，在我旁邊坐下。她開的酒吧就在堤防邊，今晚特地提早打烊。","id":"6hy7cj","ln":51},{"t":"say","k":"d","who":"康","text":"「我只是試吃！壽星的蛋糕要先確認有沒有毒！」","ln":53,"expr":"慌張","id":"1u36ax3"},{"t":"say","k":"d","who":"阿英","text":"「那右下角那一口呢？」","ln":55,"id":"vm8b3h"},{"t":"say","k":"d","who":"康","text":"「……double check」","ln":57,"expr":"普通","id":"ug12t7"},{"t":"say","k":"d","who":"阿英","text":"「三十二歲了，有什麼感想？」","ln":59,"expr":"笑","id":"a9b3lf"},{"t":"say","k":"d","who":"孫承完","text":"「感想是……妳們能不能別在漲潮線以下生火。」","ln":61,"id":"ix3qmg"},{"t":"say","k":"d","who":"康","text":"「看吧！我就說她第一句一定講這個！」","ln":63,"expr":"大笑","id":"1hixdc5"},{"t":"say","k":"n","text":"大家笑成一團。","id":"bhov90","ln":65},{"t":"say","k":"n","text":"營火劈啪作響，海風帶著烤魷魚的味道。康已經默默拿走了兩串。二月的白鹽灣還是暖的，暖得像這個小鎮從來不知道冬天是什麼。","id":"1knznqg","ln":67},{"t":"say","k":"n","text":"我一口氣吹熄了三十二根蠟燭，阿英驚呼一聲，讚嘆了我的肺活量。","id":"2nxhno","ln":69},{"t":"say","k":"n","text":"是康堅持每一根蠟燭都要插上，蛋糕像長了一片小樹林。","id":"1f9xmu6","ln":71},{"t":"say","k":"n","text":"許願的時候，我閉上眼睛。","id":"18rrkup","ln":73},{"t":"say","k":"i","text":"（希望今年，海也不要帶走任何人。）","id":"1ig58ir","ln":75},{"t":"say","k":"n","text":"每年都是這個願望。我想不到別的。","id":"3ev6e8","ln":77},{"t":"label","id":"1-2","title":"漁歌","ln":79},{"t":"bg","name":"白鹽灣沙灘・夜","ln":81},{"t":"bgm","stop":"stop","ln":82},{"t":"se","names":["營火","海浪"],"ln":83},{"t":"say","k":"d","who":"阿英","text":"「好了，壽星唱歌。」","ln":85,"id":"153bl59"},{"t":"say","k":"d","who":"孫承完","text":"「為什麼是壽星唱？不是應該妳們唱給我聽嗎？」","ln":87,"id":"1f0cujr"},{"t":"say","k":"d","who":"康","text":"「因為我嘴巴裡有東西。」","ln":89,"expr":"普通","id":"ijqaml"},{"t":"say","k":"d","who":"阿英","text":"「妳嘴巴裡永遠有東西。」","ln":91,"id":"11hm526"},{"t":"say","k":"d","who":"康","text":"「而且我們一唱，海鷗會集體跳海。」","ln":93,"id":"fkvlt2"},{"t":"say","k":"n","text":"這倒是真的。","id":"13rf2q9","ln":95},{"t":"se","names":["刷和弦"],"ln":97},{"t":"say","k":"n","text":"我接過康的吉他，隨手撥了幾個和弦。本來想唱首最近流行的歌，手指卻自己滑到了那個熟悉的調子。","id":"1ye8rh9","ln":99},{"t":"say","k":"n","text":"奶奶教我的漁歌。","id":"j70afh","ln":101},{"t":"say","k":"n","text":"小時候每次爸爸出海，奶奶就坐在門口對著海唱這首歌。她說這是唱給海聽的，海聽了，就會把出門的人還回來。","id":"1yd251s","ln":103},{"t":"say","k":"n","text":"後來爸爸沒有回來。奶奶還是每天唱。","id":"1y9dgr7","ln":105},{"t":"bgm","name":"營火之歌","ln":107},{"t":"say","k":"d","who":"孫承完","text":"「♪ 月亮落進海裡頭——」","ln":109,"id":"k2ut2b"},{"t":"say","k":"d","who":"孫承完","text":"「♪ 潮水把歌帶著走——」","ln":111,"id":"uqn0og"},{"t":"say","k":"d","who":"孫承完","text":"「♪ 海裡的姑娘別哭泣——」","ln":113,"id":"vzxdyb"},{"t":"say","k":"d","who":"孫承完","text":"「♪ 我的歌，給妳留——」","ln":115,"id":"c7rztw"},{"t":"say","k":"n","text":"營火安靜下來了。康難得停下了嘴裡的烤魷魚，阿英把啤酒放在沙上，抱著膝蓋聽。","id":"2dywim","ln":117},{"t":"say","k":"n","text":"我唱著唱著，視線不自覺地飄向海面。","id":"1to7ej2","ln":119},{"t":"say","k":"n","text":"然後我看見了她。","id":"xd0ypm","ln":121},{"t":"cg","id":"02","title":"營火邊的歌聲","ln":123},{"t":"say","k":"n","text":"在碎浪的外側，月光鋪成的那條銀色的路上，有一個女人。","id":"wlkdth","ln":125},{"t":"say","k":"n","text":"她浮在水裡，只露出肩膀以上。長長的頭髮貼在肩上，濕濕地發著光。距離太遠，我看不清她的臉，但我知道她在看我。","id":"1tcj22d","ln":127},{"t":"say","k":"n","text":"不是看營火，不是看我們這群人。","id":"fa8xtz","ln":129},{"t":"say","k":"n","text":"是看我。","id":"1evqdxv","ln":131},{"t":"say","k":"n","text":"我一顫，手指停在弦上。","id":"xrj24c","ln":133},{"t":"say","k":"d","who":"孫承完","text":"「……有人在水裡。」","ln":135,"expr":"驚訝","id":"1i521ip"},{"t":"say","k":"d","who":"阿英","text":"「什麼？」","ln":137,"id":"6pcu98"},{"t":"cgEnd","ln":139},{"t":"hide","all":true,"ln":140},{"t":"say","k":"n","text":"我已經站起來了。這是身體的反射，——晚上、離岸、沒有救生衣、一個人。每一項都是我會在值班日誌上用紅筆圈起來的東西。","id":"4myvug","ln":142},{"t":"say","k":"n","text":"我衝向水邊，浪打濕了我的腳踝。","id":"1w452gc","ln":144},{"t":"say","k":"d","who":"孫承完","text":"「喂——！妳還好嗎——！」","ln":146,"id":"19zuh2l"},{"t":"say","k":"n","text":"海面上什麼都沒有。","id":"zt6yhr","ln":148},{"t":"say","k":"n","text":"只有月光，和一圈正在慢慢散開的漣漪。","id":"e1683o","ln":150},{"t":"bgm","stop":"fade","ln":152},{"t":"say","k":"d","who":"康","text":"「承完？妳是不是喝太多了？」","ln":154,"id":"do8vh6"},{"t":"show","list":[{"c":"康","e":"慌張"}],"ln":156},{"t":"say","k":"d","who":"孫承完","text":"「我只喝了半罐。」","ln":158,"id":"15pyqn1"},{"t":"show","list":[{"c":"阿英","e":"擔心"}],"ln":160},{"t":"say","k":"n","text":"阿英走到我身邊，往海看了看，又盯著我。","id":"3xq8v8","ln":162},{"t":"say","k":"d","who":"阿英","text":"「……妳臉色不太好。」","ln":164,"id":"18qmq3p"},{"t":"say","k":"d","who":"孫承完","text":"「剛剛那裡真的有人。」","ln":166,"expr":"認真","id":"k2hz45"},{"t":"say","k":"n","text":"阿英沒有笑我。她只是說：","id":"18nithn","ln":168},{"t":"say","k":"d","who":"阿英","text":"「我阿嬤以前講過，晚上在海邊唱歌，不要對著海唱。」","ln":170,"expr":"認真","id":"uaztam"},{"t":"say","k":"d","who":"孫承完","text":"「為什麼？」","ln":172,"id":"1h9z2p4"},{"t":"say","k":"d","who":"阿英","text":"「她說，會有東西回應。」","ln":174,"id":"uydb25"},{"t":"say","k":"n","text":"浪又打上來一次，冰涼地淹過我的腳背。","id":"j7atdn","ln":176},{"t":"say","k":"n","text":"我盯著那片漆黑的海，直到營火快要熄滅。","id":"ennemk","ln":178},{"t":"say","k":"n","text":"她沒有再出現。","id":"vjd85z","ln":180},{"t":"label","id":"1-3","title":"溺水","ln":182},{"t":"hide","all":true,"ln":184},{"t":"trans","kind":"out","ln":185},{"t":"bg","name":"救生站・白天","ln":186},{"t":"trans","kind":"in","ln":187},{"t":"bgm","name":"白鹽灣日常","ln":188},{"t":"say","k":"n","text":"隔天下午，我照常值班。","id":"n1hb1d","ln":190},{"t":"say","k":"n","text":"觀光客不多。幾個小孩在淺灘堆沙堡，一對老夫婦撐著傘散步。天氣好得不像話，海是那種藍得會讓人放下戒心的藍。","id":"xovw34","ln":192},{"t":"say","k":"n","text":"我坐在瞭望台上轉著哨子，忍不住一直看向昨晚那片海域。","id":"17cmj00","ln":194},{"t":"say","k":"i","text":"（大概是看錯了吧。月光、浪花、加上一點啤酒……）","id":"1d19gmp","ln":196},{"t":"say","k":"n","text":"就在這時——","id":"zml2bc","ln":198},{"t":"bgm","stop":"stop","ln":200},{"t":"se","names":["水花"],"ln":201},{"t":"say","k":"d","who":"？？？","text":"「救——救命啊——！」","ln":203,"id":"116vqs"},{"t":"say","k":"n","text":"聲音從警戒旗外面傳來。","id":"o74vyr","ln":205},{"t":"say","k":"n","text":"一個女人在水裡掙扎，雙手拍打著水面，頭一下沉、一下浮。","id":"l4hins","ln":207},{"t":"say","k":"n","text":"我的身體比腦子先動。哨子、浮標、跳下瞭望台、衝進海裡——","id":"1yw38pe","ln":209},{"t":"bg","name":"白鹽灣海面・白天","ln":211},{"t":"bgm","name":"緊張","ln":212},{"t":"say","k":"n","text":"浪比看起來的大。我穿過碎浪，用最快的速度游向她。","id":"f89q81","ln":214},{"t":"say","k":"n","text":"靠近的時候，我發現一件奇怪的事。","id":"199itrx","ln":216},{"t":"say","k":"n","text":"她明明在「掙扎」，拍水的動作卻……很誇張。誇張得像在演戲。而且她每次沉下去都沉得很從容，浮上來的時候，頭髮一絲都沒亂。那頭長髮在水裡散開，像一大團化開的墨。","id":"gt7op4","ln":218},{"t":"say","k":"i","text":"（……先救再說。）","id":"15yqr6s","ln":220},{"t":"say","k":"n","text":"我從背後抱住她，把浮標塞到她胸前。","id":"1sxdhgj","ln":222},{"t":"say","k":"n","text":"我的腿碰到她的腿的那一瞬間，傳來一種很滑、很涼的觸感。","id":"1i7bbyu","ln":224},{"t":"say","k":"n","text":"不像皮膚。","id":"1jb2omg","ln":226},{"t":"say","k":"n","text":"像……","id":"bgfcf7","ln":228},{"t":"say","k":"d","who":"孫承完","text":"「放鬆！我抓住妳了！不要亂動！」","ln":230,"id":"gy88qj"},{"t":"say","k":"n","text":"她果然不動了。","id":"sjbw9t","ln":232},{"t":"say","k":"n","text":"不只是不動。她整個人軟下來靠在我身上，順從得像是一直在等這一刻。","id":"1m9t8ss","ln":234},{"t":"label","id":"1-4","title":"妳的呼吸","ln":236},{"t":"bg","name":"白鹽灣沙灘・白天","ln":238},{"t":"bgm","stop":"stop","ln":239},{"t":"se","names":["海浪"],"ln":240},{"t":"say","k":"n","text":"我把她拖上岸，放在乾的沙灘上。","id":"12ln3rd","ln":242},{"t":"say","k":"n","text":"她閉著眼睛，沒有呼吸。","id":"1h472c5","ln":244},{"t":"say","k":"n","text":"我跪在她旁邊，確認呼吸道、確認脈搏——脈搏很強，強得不像溺水的人。","id":"1ciax6e","ln":246},{"t":"say","k":"n","text":"但她就是沒有呼吸。","id":"1a6pam8","ln":248},{"t":"say","k":"i","text":"（不管了。）","id":"j0u3ie","ln":250},{"t":"say","k":"n","text":"我捏住她的鼻子，低下頭。","id":"5ln7hn","ln":252},{"t":"cg","id":"03","title":"沙灘救援","ln":254},{"t":"say","k":"n","text":"她的嘴唇是涼的，鹹的，像海水本身。","id":"1wit2pv","ln":256},{"t":"say","k":"n","text":"我吹進第一口氣。","id":"5fkpke","ln":258},{"t":"say","k":"n","text":"然後她睜開了眼睛。","id":"1pq397t","ln":260},{"t":"say","k":"n","text":"近得不能再近。那雙眼睛是很深的顏色，深得像看不見底的海溝，裡頭映著我的臉。","id":"wnan5e","ln":262},{"t":"say","k":"n","text":"她一把抓住我的衣領。","id":"1gvuge7","ln":264},{"t":"say","k":"n","text":"那一瞬間，她的眼神讓我背脊發涼。那是一種很飢餓的眼神，像一個在沙漠裡走了很久很久的人，終於看見了水。","id":"15fh9qy","ln":266},{"t":"say","k":"n","text":"我感覺到她在吸氣。很深、很深地吸，像是要把我肺裡的什麼東西整個抽走——","id":"1769xhu","ln":268},{"t":"say","k":"n","text":"然後，她停住了。","id":"efh1e2","ln":270},{"t":"say","k":"n","text":"她的眼神變了。侵略不見了，換成一種……恍惚。像喝醉了，像剛從一場很長的夢裡醒來，不知道自己在哪裡。","id":"6pzlm5","ln":272},{"t":"say","k":"n","text":"她鬆開我的衣領，躺回沙灘上，木然地看著我。","id":"oi5une","ln":274},{"t":"cgEnd","ln":276},{"t":"show","list":[{"c":"裴柱現","e":"恍惚"}],"ln":277},{"t":"say","k":"d","who":"？？？","text":"「……妳……」","ln":279,"id":"1gz2g93"},{"t":"say","k":"n","text":"她的聲音很好聽。低低的，帶一點沙啞，我想到浪退回海裡時拖過碎石的聲音。","id":"1m1eij5","ln":281},{"t":"say","k":"d","who":"？？？","text":"「……妳是什麼東西？」","ln":283,"id":"1q4gn2h"},{"t":"say","k":"d","who":"孫承完","text":"「蛤……我是救生員。」","ln":285,"id":"8si4lo"},{"t":"say","k":"d","who":"？？？","text":"「我知道妳是救生員。我是說——」","ln":287,"id":"1p0quj2"},{"t":"show","list":[{"c":"裴柱現","e":"驚慌"}],"ln":289},{"t":"say","k":"n","text":"她說到一半，突然看向自己的腿，臉色大變。","id":"1d19r3c","ln":291},{"t":"say","k":"n","text":"她一把搶走我掛在脖子上的毛巾，手忙腳亂地把整雙腿裹起來，裹得像一隻蝦。","id":"31pn4v","ln":293},{"t":"say","k":"n","text":"我好像在那一瞬間，看到她的小腿上有一片閃閃發光的東西。湛藍色的，一片一片，像亮片。","id":"17cuf3i","ln":295},{"t":"say","k":"i","text":"（……現在的泳衣連腿上都要貼亮片了嗎？）","id":"vy2yui","ln":297},{"t":"say","k":"d","who":"孫承完","text":"「妳還好嗎？有沒有哪裡痛？有沒有嗆到很多水？」","ln":299,"id":"13k3cdu"},{"t":"say","k":"d","who":"？？？","text":"「沒有。我很好。很好……。」","ln":301,"id":"17a7vok"},{"t":"say","k":"d","who":"孫承完","text":"「妳剛剛沒有呼吸。」","ln":303,"id":"1vjovhx"},{"t":"say","k":"d","who":"？？？","text":"「……我剛剛在休息。」","ln":305,"id":"v3ayz5"},{"t":"say","k":"d","who":"孫承完","text":"「在水裡休息？」","ln":307,"id":"1lq8f8l"},{"t":"show","list":[{"c":"裴柱現","e":"得意"}],"ln":309},{"t":"say","k":"d","who":"？？？","text":"「不行嗎？」","ln":311,"id":"1gd8juo"},{"t":"say","k":"n","text":"她抬起下巴看我。明明全身濕透、腿上裹著一條印著「白鹽灣救生站」的毛巾，那個表情卻像女王在接見臣民。","id":"14omko7","ln":313},{"t":"say","k":"n","text":"我這輩子救過幾百個人，從來沒有一個人被救起來之後，用這種眼神看我。","id":"1th1fqs","ln":315},{"t":"say","k":"n","text":"而且——","id":"t2mffm","ln":317},{"t":"show","list":[{"c":"裴柱現","e":"普通"}],"ln":319},{"t":"say","k":"n","text":"我這才真正看清楚她的臉。","id":"u4a34j","ln":321},{"t":"say","k":"n","text":"然後我忘了自己要說什麼。","id":"q6jys7","ln":323},{"t":"say","k":"n","text":"在白鹽灣當了十年救生員，我看過許多人。來拍婚紗的新娘、來度假的模特兒、每年夏天把沙灘當伸展台的觀光客。我以為自己對「漂亮」這件事早就麻痺了。","id":"bxfuf","ln":325},{"t":"say","k":"n","text":"但她不一樣。","id":"9be013","ln":327},{"t":"say","k":"n","text":"她的頭髮是很深很深的藍黑色，又長又直，濕漉漉地散在沙子上。陽光一照，髮絲裡泛出一層深藍色的光澤，其中幾縷黏在她的頸側，彎成我這輩子見過最好看的弧線。","id":"13jto6k","ln":329},{"t":"say","k":"n","text":"我順著髮絲看向她的頸，她的皮膚白得不像曬過太陽。很像貝殼的內側——那種要把貝殼翻過來、對著光才看得到的、帶著一點珍珠色的白。水珠沿著她的下巴滑下來，遲遲不肯掉，好像連水都捨不得離開她。","id":"1csg71y","ln":331},{"t":"say","k":"n","text":"她的眼睛是很深的褐色，眼尾微微上挑。左眼的眼角旁邊，有一顆很小的痣。睫毛又長又密，上面掛著細細的水珠，她一眨眼，那些水珠就碎成光。","id":"17sqd7j","ln":333},{"t":"say","k":"n","text":"……還有嘴唇。剛剛碰過的那雙嘴唇，現在微微張著，顏色淡得像珊瑚，帶著一點被海水泡過的反光。","id":"7y4ft3","ln":335},{"t":"say","k":"i","text":"（……漂亮得不像真的。）","id":"1jwd0ws","ln":337},{"t":"say","k":"n","text":"不，「漂亮」這個詞太輕了。","id":"ed7gk3","ln":339},{"t":"say","k":"n","text":"也許是「美」？。她像是有人照著這個字的定義一筆一筆刻出來。美到，讓人覺得多看一眼，就會被拖進什麼回不來的地方。","id":"18ykbws","ln":341},{"t":"say","k":"n","text":"因為剛才的騷動，沙灘上的人開始圍過來了。我聽見有人倒抽一口氣，一個大學生手上的飲料直接掉在沙上。連那對散步的老夫婦都停下腳步，老先生看得太入神，被老太太狠狠捏了一把。","id":"ipugeo","ln":343},{"t":"say","k":"n","text":"她對這一切毫不在意，好像被人這樣瞻望是天經地義的事。","id":"1o350ul","ln":345},{"t":"say","k":"n","text":"她只是看著我，看得很專注。我不知讓我耳朵發燙的是她的眼神，還是我頭頂的太陽。","id":"h0h6ml","ln":347},{"t":"choice","title":"選擇①","options":[{"key":"A","text":"問她的名字","to":"1-5A","eff":[{"s":"心動","d":1},{"f":"知道名字","clear":false}]},{"key":"B","text":"堅持送她去診所","to":"1-5B"}],"ln":349},{"t":"label","id":"1-5A","title":"名字","ln":353},{"t":"say","k":"d","who":"孫承完","text":"「……我叫孫承完。妳呢？」","ln":355,"expr":"害羞","id":"73pznn"},{"t":"say","k":"n","text":"她眨了眨眼，好像沒想到我會問這個。","id":"9p07lz","ln":357},{"t":"say","k":"d","who":"？？？","text":"「孫……承完。」","ln":359,"id":"10a3bta"},{"t":"say","k":"n","text":"她把我的名字慢慢地唸了一遍，像在學習新的發音。","id":"1crgicn","ln":361},{"t":"say","k":"n","text":"然後她抬起下巴，用一種宣布重大事項的語氣說：","id":"6w0vyg","ln":363},{"t":"say","k":"d","who":"裴柱現","text":"「裴柱現。」","ln":365,"expr":"得意","id":"1wbem7z"},{"t":"say","k":"d","who":"孫承完","text":"「……裴柱現？」","ln":367,"id":"3v617h"},{"t":"say","k":"d","who":"裴柱現","text":"「有意見？」","ln":369,"expr":"生氣","id":"50kvt8"},{"t":"say","k":"d","who":"孫承完","text":"「沒有沒有。」","ln":371,"id":"1x3t3y7"},{"t":"say","k":"n","text":"我忍不住笑出來。","id":"1ua4lf3","ln":373},{"t":"say","k":"d","who":"孫承完","text":"「只是……很好聽。像古代公主的名字。」","ln":375,"expr":"笑","id":"vusknz"},{"t":"say","k":"n","text":"她愣了一下。","id":"153gizd","ln":377},{"t":"say","k":"d","who":"裴柱現","text":"「……本來就是。」","ln":379,"expr":"得意","id":"etrxbw"},{"t":"say","k":"d","who":"孫承完","text":"「什麼？」","ln":381,"id":"6p7ray"},{"t":"say","k":"d","who":"裴柱現","text":"「我是說，謝謝。」","ln":383,"expr":"驚慌","id":"yv8aam"},{"t":"say","k":"d","who":"孫承完","text":"「妳講話的樣子真的很像公主耶。剛剛被我救起來的時候也是，好像我應該跪下來謝主隆恩一樣。」","ln":385,"expr":"笑","id":"5or8i4"},{"t":"say","k":"n","text":"她瞪著我。瞪了大概三秒。","id":"i6xeob","ln":387},{"t":"say","k":"n","text":"然後她的嘴角，很輕很輕地動了一下。","id":"ba62nl","ln":389},{"t":"say","k":"d","who":"裴柱現","text":"「……無禮的人類。」","ln":391,"expr":"笑","id":"1fy26n9"},{"t":"say","k":"d","who":"孫承完","text":"「嗯？」","ln":393,"id":"1ebd303"},{"t":"say","k":"d","who":"裴柱現","text":"「我是說，無禮的……人。」","ln":395,"expr":"驚慌","id":"1q1u36h"},{"t":"say","k":"n","text":"她裹著我的毛巾站起來，搖搖晃晃，像一隻剛學會走路的小鹿。我伸手想扶她，她卻躲開了。","id":"tes98b","ln":397},{"t":"say","k":"d","who":"裴柱現","text":"「這塊布，我借走了。」","ln":399,"expr":"得意","id":"1svyjqk"},{"t":"say","k":"d","who":"孫承完","text":"「那是毛巾——等等，妳要去哪？妳家在哪裡？」","ln":401,"id":"19t7fnl"},{"t":"say","k":"n","text":"她沒有回答，一步一步、歪歪扭扭地走向堤防。","id":"1yegmga","ln":403},{"t":"say","k":"n","text":"走到一半，她回過頭來。","id":"1jqj8o2","ln":405},{"t":"say","k":"d","who":"裴柱現","text":"「孫承完。」","ln":407,"expr":"普通","id":"w5hgz6"},{"t":"say","k":"n","text":"她連名帶姓地叫我，像即將宣讀聖旨。","id":"q3kq7m","ln":409},{"t":"say","k":"d","who":"孫承完","text":"「有？」","ln":411,"id":"1j2i245"},{"t":"say","k":"d","who":"裴柱現","text":"「妳唱的歌……」","ln":413,"id":"18pyozu"},{"t":"say","k":"n","text":"她頓了一下，好像想說什麼，最後只是轉回頭去。","id":"1xgmgik","ln":415},{"t":"say","k":"d","who":"裴柱現","text":"「……沒事。」","ln":417,"expr":"害羞","id":"xgybbt"},{"t":"hide","list":["裴柱現"],"ln":419},{"t":"say","k":"i","text":"（……歌？）","id":"abna5z","ln":421},{"t":"say","k":"n","text":"我站在原地，過了好久才想起來：我今天唱過歌嗎？","id":"o6sgw4","ln":423},{"t":"jump","to":"1-6","ln":425},{"t":"label","id":"1-5B","title":"診所","ln":427},{"t":"say","k":"d","who":"孫承完","text":"「不行，妳剛剛真的沒有呼吸。我帶妳去鎮上的診所檢查一下——」","ln":429,"id":"ilj72g"},{"t":"say","k":"d","who":"？？？","text":"「診所？」","ln":431,"id":"1afjt0t"},{"t":"say","k":"d","who":"孫承完","text":"「就是看醫生的地方。」","ln":433,"id":"1havlf5"},{"t":"show","list":[{"c":"裴柱現","e":"驚慌"}],"ln":435},{"t":"say","k":"n","text":"她的臉一下子白了。","id":"53dz1g","ln":437},{"t":"say","k":"d","who":"？？？","text":"「不要！我不去！」","ln":439,"id":"uhmx4x"},{"t":"say","k":"d","who":"孫承完","text":"「只是簡單檢查，不會痛的——」","ln":441,"id":"dqtbix"},{"t":"say","k":"d","who":"？？？","text":"「不准帶我去任何有醫生的地方！」","ln":443,"id":"15dcwdk"},{"t":"hide","list":["裴柱現"],"ln":445},{"t":"say","k":"n","text":"她裹著我的毛巾跳起來——說是跳，其實比較像一條魚在砧板上彈了一下——然後頭也不回地朝堤防跑去。跑得歪歪扭扭，好幾次差點跌倒，卻怎麼樣都不肯停。","id":"dk6qai","ln":447},{"t":"say","k":"d","who":"孫承完","text":"「喂！我的毛巾——！」","ln":449,"expr":"驚訝","id":"6xzce1"},{"t":"say","k":"n","text":"她沒有回頭。","id":"3h9dil","ln":451},{"t":"say","k":"n","text":"我站在原地，看著那個裹著救生站毛巾的背影消失在堤防後面。","id":"lrbdmd","ln":453},{"t":"say","k":"i","text":"（……我連她叫什麼都不知道。）","id":"1rgww96","ln":455},{"t":"jump","to":"1-6","ln":457},{"t":"label","id":"1-6","title":"夜","ln":459},{"t":"hide","all":true,"ln":461},{"t":"trans","kind":"out","ln":462},{"t":"bg","name":"孫承完的房間・夜","ln":463},{"t":"trans","kind":"in","ln":464},{"t":"bgm","name":"心動（安靜版）","ln":465},{"t":"say","k":"n","text":"那天晚上，我睡不著。","id":"1bgzxpy","ln":467},{"t":"say","k":"n","text":"我躺在床上盯著天花板，嘴唇上好像還留著那個涼涼的、鹹鹹的觸感。","id":"17ejjo5","ln":469},{"t":"say","k":"n","text":"我想起她抓住我衣領時的眼神。那一瞬間，我真的有點怕。","id":"1fx7ijg","ln":471},{"t":"say","k":"n","text":"但我更常想起的，是之後那個恍惚的表情。好像她吸進去的不是空氣，是別的什麼東西。而那個東西讓她……醉了。","id":"xynaen","ln":473},{"t":"say","k":"i","text":"（我在想什麼啊。）","id":"it2ro8","ln":475},{"t":"say","k":"n","text":"我翻了個身，小聲哼起奶奶的漁歌。","id":"3p1zs3","ln":477},{"t":"say","k":"n","text":"窗外，海很安靜。","id":"1baanur","ln":479},{"t":"say","k":"n","text":"安靜得像是在聽。","id":"5v8onp","ln":481},{"t":"chend","text":"第一章　完","ln":483}]},{"key":"02_第二章_姐姐","name":"02_第二章_姐姐.md","route":"main","num":2,"title":"第二章　姐姐","ops":[{"t":"title","text":"第二章　姐姐","card":true,"ln":1},{"t":"label","id":"2-1","title":"退潮","ln":3},{"t":"bg","name":"酒吧「退潮」・夜","ln":5},{"t":"bgm","name":"白鹽灣日常","ln":6},{"t":"se","names":["開門"],"ln":7},{"t":"say","k":"n","text":"生日過後第三天，我下班後照例去阿英的酒吧。","id":"1y0vl6i","ln":9},{"t":"say","k":"n","text":"「退潮」開在堤防邊，木頭門、木頭吧檯，牆上掛滿了漂流木和舊浮標，是我從高中看到現在的樣子。","id":"7x8uyv","ln":11},{"t":"say","k":"n","text":"推開門的那一瞬間，我差點撞上一個端著托盤的人。","id":"1qk6mcg","ln":13},{"t":"say","k":"n","text":"托盤上三杯啤酒晃了一下，被一隻很白、很細的手穩穩扶住。","id":"kj48ml","ln":15},{"t":"show","list":[{"c":"裴柱現","e":"驚慌"}],"ln":17},{"t":"say","k":"n","text":"然後我抬起頭，看見了那張臉。","id":"1tcetnv","ln":19},{"t":"if","cond":[[{"f":"知道名字","neg":false}]],"to":"2-1A","ln":21},{"t":"jump","to":"2-1B","ln":22},{"t":"label","id":"2-1A","title":"重逢","ln":24},{"t":"say","k":"d","who":"孫承完","text":"「……裴柱現？」","ln":26,"expr":"驚訝","id":"lepyra"},{"t":"say","k":"d","who":"裴柱現","text":"「……孫承完。」","ln":28,"expr":"普通","id":"q3y6w5"},{"t":"say","k":"n","text":"她穿著酒吧的黑色圍裙，長髮用一根筷子隨便盤在腦後。明明是全鎮最普通的打工制服，穿在她身上卻像什麼高級名牌的當季新款。","id":"1kxyrrj","ln":30},{"t":"say","k":"d","who":"阿英","text":"「妳們認識？」","ln":32,"id":"1udensq"},{"t":"show","list":[{"c":"阿英","e":"普通"}],"ln":34},{"t":"say","k":"d","who":"孫承完","text":"「她就是前天我救起來的那個人。」","ln":36,"id":"5e2tlm"},{"t":"say","k":"d","who":"裴柱現","text":"「是我讓她救的。」","ln":38,"expr":"得意","id":"h0jab6"},{"t":"say","k":"d","who":"孫承完","text":"「……什麼？」","ln":40,"id":"lio89j"},{"t":"say","k":"d","who":"裴柱現","text":"「我是說，是她救了我。謝謝。」","ln":42,"expr":"驚慌","id":"1wg1vbz"},{"t":"say","k":"n","text":"她轉身，走到一張木桌旁，把三杯啤酒放到客人桌上，整套動作僵硬得像第一次用腳走路的人。","id":"p2rcue","ln":44},{"t":"jump","to":"2-2","ln":46},{"t":"label","id":"2-1B","title":"毛巾小偷","ln":48},{"t":"say","k":"d","who":"孫承完","text":"「啊！毛巾小偷！」","ln":50,"expr":"驚訝","id":"graxbr"},{"t":"say","k":"d","who":"？？？","text":"「……」","ln":52,"id":"18hl9xx"},{"t":"say","k":"n","text":"她穿著酒吧的黑色圍裙，頭髮用一根筷子隨便盤在腦後。明明是全鎮最普通的打工制服，穿在她身上卻像什麼高級名牌的當季新款。","id":"1tsb0qx","ln":54},{"t":"show","list":[{"c":"裴柱現","e":"生氣"}],"ln":56},{"t":"say","k":"d","who":"？？？","text":"「無禮，我有名字。」","ln":58,"id":"fye2kg"},{"t":"say","k":"d","who":"孫承完","text":"「那妳叫什麼？」","ln":60,"id":"14o4feq"},{"t":"say","k":"n","text":"她抬起下巴，用一種宣布重大事項的語氣說：","id":"19n5nav","ln":62},{"t":"say","k":"d","who":"裴柱現","text":"「裴柱現。」","ln":64,"expr":"得意","id":"pe3qok"},{"t":"say","k":"d","who":"孫承完","text":"「……裴柱現？」","ln":66,"id":"l4qd2b"},{"t":"say","k":"d","who":"裴柱現","text":"「有意見？」","ln":68,"expr":"生氣","id":"2a3p9b"},{"t":"say","k":"d","who":"孫承完","text":"「沒有沒有，很好聽。像古代公主的名字。我叫孫承完。」","ln":70,"expr":"笑","id":"gup7qf"},{"t":"say","k":"d","who":"裴柱現","text":"「……本來就是。」","ln":72,"expr":"得意","id":"12vcut1"},{"t":"say","k":"d","who":"孫承完","text":"「啊？」","ln":74,"id":"8tml9n"},{"t":"say","k":"d","who":"裴柱現","text":"「我是說……孫承完。我記住了。」","ln":76,"expr":"驚慌","id":"1qlewqh"},{"t":"say","k":"n","text":"她瞪了我三秒，然後很輕很輕地哼了一聲。","id":"sgbjae","ln":78},{"t":"say","k":"d","who":"裴柱現","text":"「毛巾我洗過了。等一下還妳。」","ln":80,"expr":"普通","id":"1hb7h2n"},{"t":"say","k":"d","who":"阿英","text":"「妳們認識？」","ln":82,"id":"1u3f23r"},{"t":"show","list":[{"c":"阿英","e":"普通"}],"ln":84},{"t":"say","k":"d","who":"孫承完","text":"「她就是前天我救起來的那個人。」","ln":86,"id":"5437wn"},{"t":"flag","names":["知道名字"],"ln":88},{"t":"jump","to":"2-2","ln":90},{"t":"label","id":"2-2","title":"姐姐","ln":92},{"t":"say","k":"n","text":"阿英說，裴柱現是兩天前出現在店門口的。","id":"z4b8a0","ln":94},{"t":"say","k":"n","text":"全身上下只有一條毛巾、一個破舊的帆布包，問阿英能不能讓她工作，什麼都願意做。","id":"yb3jp9","ln":96},{"t":"say","k":"d","who":"阿英","text":"「我本來要拒絕的。結果她在門口站了五分鐘，有三個客人撞到柱子。」","ln":98,"expr":"普通","id":"1qe29pi"},{"t":"say","k":"d","who":"孫承完","text":"「……所以妳就錄取她了？」","ln":100,"id":"1gzvvat"},{"t":"say","k":"d","who":"阿英","text":"「營業額是上週的兩倍。我又不是慈善機構。」","ln":102,"id":"q573gs"},{"t":"say","k":"n","text":"阿英把她安排在樓上的儲藏室住。我問她從哪裡來，阿英聳聳肩。","id":"1baetaf","ln":104},{"t":"say","k":"d","who":"阿英","text":"「她說『海的那邊』。我問哪邊，她說『比較深的那邊』。」","ln":106,"id":"wngfjt"},{"t":"say","k":"n","text":"我看向吧檯。","id":"d2qa86","ln":108},{"t":"say","k":"n","text":"裴柱現正盯著廚房剛端出來的一鍋蛤蜊湯，臉色鐵青。","id":"3u1y52","ln":110},{"t":"show","list":[{"c":"裴柱現","e":"驚慌"}],"ln":112},{"t":"say","k":"d","who":"裴柱現","text":"「你們……把牠們怎麼了？」","ln":114,"id":"qxtplq"},{"t":"say","k":"d","who":"孫承完","text":"「那是蛤蜊湯。很好喝喔。」","ln":116,"id":"1ltykf9"},{"t":"say","k":"d","who":"裴柱現","text":"「牠們全都張著嘴……」","ln":118,"expr":"難過","id":"142fwhl"},{"t":"say","k":"d","who":"孫承完","text":"「因為煮熟了就會打開啊。」","ln":120,"id":"mesqsx"},{"t":"say","k":"n","text":"她用一種看嫌惡的眼神看著我。","id":"1xkgqf1","ln":122},{"t":"say","k":"n","text":"我實在忍不住，拿起旁邊的碗，舀了一些碗放在她面前。","id":"17xof17","ln":124},{"t":"say","k":"d","who":"孫承完","text":"「喝喝看。我保證妳會喜歡。」","ln":126,"expr":"笑","id":"tbd545"},{"t":"say","k":"n","text":"她瞪著那碗湯，瞪了很久，好像在跟裡面的蛤蜊做最後的告別。然後她端起碗，一口氣喝下去——","id":"l0y5ul","ln":128},{"t":"say","k":"d","who":"裴柱現","text":"「——！」","ln":130,"expr":"驚慌","id":"uv4n1s"},{"t":"say","k":"n","text":"太燙了。","id":"lc6oha","ln":132},{"t":"say","k":"n","text":"她整張臉皺起來，摀著嘴，眼眶一下子就紅了。","id":"1axfcaj","ln":134},{"t":"say","k":"n","text":"可是很奇怪。她的眼睛明明紅成那樣，卻一滴眼淚都沒有掉下來。","id":"temwpa","ln":136},{"t":"say","k":"i","text":"（……是忍住了嗎？）","id":"wsoin7","ln":138},{"t":"say","k":"d","who":"裴柱現","text":"「……人類的食物，都是這種刑罰嗎。」","ln":140,"expr":"生氣","id":"121cvon"},{"t":"say","k":"d","who":"孫承完","text":"「是妳喝太快了啦。」","ln":142,"id":"188h5q2"},{"t":"say","k":"n","text":"我倒了杯冰水給她。她接過去，喝完，舔了舔嘴唇，然後很小聲地說：","id":"1gpmgze","ln":144},{"t":"say","k":"d","who":"裴柱現","text":"「……再一碗。」","ln":146,"expr":"害羞","id":"kc1dhh"},{"t":"say","k":"n","text":"阿英在吧檯後面翻了個白眼，拿出一張表格。","id":"p5dqoc","ln":148},{"t":"say","k":"d","who":"阿英","text":"「對了，員工資料還沒填完。年齡？」","ln":150,"id":"1gdi6rw"},{"t":"say","k":"n","text":"裴柱現停住了。","id":"7tlwtf","ln":152},{"t":"say","k":"d","who":"裴柱現","text":"「……年齡。」","ln":154,"expr":"普通","id":"11epxpo"},{"t":"say","k":"d","who":"阿英","text":"「幾歲。」","ln":156,"id":"17xwngu"},{"t":"say","k":"n","text":"裴柱現的視線往上飄，好像在心裡算一個很複雜的數學題。過了好幾秒，她才很慎重地說：","id":"w5mooj","ln":158},{"t":"say","k":"d","who":"裴柱現","text":"「三十五。」","ln":160,"expr":"得意","id":"os6bd1"},{"t":"say","k":"n","text":"阿英瞇起眼睛看她。","id":"17yz0ta","ln":162},{"t":"say","k":"d","who":"阿英","text":"「……三十五？」","ln":164,"id":"1989nrr"},{"t":"say","k":"d","who":"裴柱現","text":"「有意見？」","ln":166,"expr":"生氣","id":"2k3aya"},{"t":"say","k":"d","who":"阿英","text":"「沒有。只是妳剛剛算得好像在報稅。」","ln":168,"id":"cyicpn"},{"t":"say","k":"d","who":"孫承完","text":"「三十五啊。那比我大三歲耶。」","ln":170,"expr":"笑","id":"1gtmgcy"},{"t":"say","k":"n","text":"我想都沒想，就順口說：","id":"3e295l","ln":172},{"t":"say","k":"d","who":"孫承完","text":"「那我以後叫妳姐姐好了。」","ln":174,"id":"mi6qli"},{"t":"cg","id":"04","title":"姐姐","ln":176},{"t":"say","k":"n","text":"裴柱現整個人僵住了。","id":"ovlk2z","ln":178},{"t":"say","k":"n","text":"她轉過頭來看我，眼睛睜得大大的。燈光落在她的睫毛上，那張冷冷的臉上，第一次出現了一種……很像小孩子的表情。","id":"1n8jevt","ln":180},{"t":"say","k":"d","who":"裴柱現","text":"「……姐姐？」","ln":182,"id":"uy3koy"},{"t":"say","k":"d","who":"孫承完","text":"「嗯，姐姐。」","ln":184,"id":"1v4kqjp"},{"t":"say","k":"n","text":"她慢慢地重複了一次，像在品嚐什麼稀有的東西。","id":"9tevnq","ln":186},{"t":"say","k":"d","who":"裴柱現","text":"「姐姐……」","ln":188,"id":"1ql01pt"},{"t":"say","k":"n","text":"然後她的嘴角翹起來，翹得藏都藏不住。","id":"c9946d","ln":190},{"t":"say","k":"d","who":"裴柱現","text":"「再叫一次。」","ln":192,"id":"wg1ays"},{"t":"say","k":"d","who":"孫承完","text":"「……姐姐？」","ln":194,"id":"10il19v"},{"t":"say","k":"d","who":"裴柱現","text":"「再一次。」","ln":196,"id":"16qe0pf"},{"t":"say","k":"d","who":"孫承完","text":"「姐姐。」","ln":198,"id":"188bila"},{"t":"say","k":"d","who":"裴柱現","text":"「准了。」","ln":200,"id":"1i1egiv"},{"t":"say","k":"d","who":"孫承完","text":"「准什麼？」","ln":202,"id":"1mrh61v"},{"t":"say","k":"n","text":"她沒有回答，只是端起第二碗蛤蜊湯，這次很小口很小口地喝，嘴角一直彎著。","id":"1gugxue","ln":204},{"t":"cgEnd","ln":206},{"t":"say","k":"n","text":"阿英把表格收回去，用只有我聽得見的聲音說：","id":"1yrtjd8","ln":208},{"t":"say","k":"d","who":"阿英","text":"「妳完了。」","ln":210,"expr":"擔心","id":"19vlmkf"},{"t":"say","k":"d","who":"孫承完","text":"「什麼完了？」","ln":212,"expr":"害羞","id":"1ocoect"},{"t":"say","k":"n","text":"阿英沒理我。","id":"1p5wzio","ln":214},{"t":"say","k":"n","text":"這時候，柱現放在吧檯上的帆布包動了一下。","id":"un3pua","ln":216},{"t":"say","k":"n","text":"一隻寄居蟹從包包口探出頭來，背著一個粉紅色的螺殼，兩根觸角直直地對著我。","id":"qc0j83","ln":218},{"t":"show","list":[{"c":"珊婆","e":"普通"}],"ln":220},{"t":"say","k":"d","who":"孫承完","text":"「……妳包包裡有螃蟹。」","ln":222,"expr":"驚訝","id":"1n350d5"},{"t":"say","k":"d","who":"裴柱現","text":"「那是我的……寵物。」","ln":224,"expr":"驚慌","id":"1dfzc7y"},{"t":"say","k":"d","who":"孫承完","text":"「牠叫什麼名字？」","ln":226,"id":"qx1m5a"},{"t":"say","k":"d","who":"裴柱現","text":"「牠叫珊……珊珊。」","ln":228,"id":"13r11ti"},{"t":"say","k":"n","text":"寄居蟹伸出鉗子，狠狠夾了她的手指一下。","id":"1seqd1q","ln":230},{"t":"say","k":"d","who":"裴柱現","text":"「啊——！」","ln":232,"expr":"生氣","id":"gdclte"},{"t":"say","k":"i","text":"（……我是不是看錯了，那隻螃蟹剛剛好像翻了個白眼。）","id":"p3ys2w","ln":234},{"t":"hide","list":["珊婆"],"ln":236},{"t":"label","id":"2-3","title":"浪打不到的地方","ln":238},{"t":"hide","all":true,"ln":240},{"t":"trans","kind":"out","ln":241},{"t":"bg","name":"白鹽灣沙灘・白天","ln":242},{"t":"trans","kind":"in","ln":243},{"t":"bgm","name":"白鹽灣日常","ln":244},{"t":"se","names":["海浪"],"ln":245},{"t":"say","k":"n","text":"之後的一個禮拜，我幾乎每天都去「退潮」。","id":"1nhtt3d","ln":247},{"t":"say","k":"n","text":"阿英說我是去喝酒的。康說我是去看美女的，說完就把我面前的花生吃光了。我說我是去確認溺水者的後續狀況。但沒有人相信我。","id":"1pf878c","ln":249},{"t":"say","k":"n","text":"我休假那天，約了柱現姐姐來海邊走走。她答應得很快，快得讓我有點意外。","id":"s38t6a","ln":251},{"t":"show","list":[{"c":"裴柱現","e":"笑"}],"ln":253},{"t":"say","k":"n","text":"她穿著從阿英那裡借來的白色洋裝，赤腳踩在沙灘上，裙擺被海風吹得一直翻。路過的衝浪客有兩個直接從板子上掉下去。","id":"10kfhc1","ln":255},{"t":"say","k":"n","text":"我走到浪花邊，讓海水沖過腳背。","id":"1fwknik","ln":257},{"t":"say","k":"d","who":"孫承完","text":"「姐姐，來呀！水很舒服喔！」","ln":259,"expr":"笑","id":"770547"},{"t":"say","k":"n","text":"她停住了。","id":"1vu4q7v","ln":261},{"t":"say","k":"n","text":"就停在乾沙和濕沙的交界線上，一步都沒有再往前。","id":"yjxik8","ln":263},{"t":"say","k":"d","who":"裴柱現","text":"「……我在這裡就好。」","ln":265,"expr":"普通","id":"1aprana"},{"t":"say","k":"d","who":"孫承完","text":"「妳不喜歡海嗎？」","ln":267,"id":"24yv7l"},{"t":"say","k":"d","who":"裴柱現","text":"「我很喜歡海。」","ln":269,"id":"cnh99c"},{"t":"say","k":"d","who":"孫承完","text":"「那為什麼不過來？」","ln":271,"id":"1vum7el"},{"t":"say","k":"n","text":"她看著那條白白的浪花線，表情很複雜。像想靠近，又像在害怕什麼。","id":"1wy5xgv","ln":273},{"t":"choice","title":"選擇②","options":[{"key":"A","text":"陪她坐在乾的沙灘上","to":"2-3A","eff":[{"s":"信任","d":1}]},{"key":"B","text":"拉她去踩浪","to":"2-3B","eff":[{"s":"心動","d":-1}]}],"ln":275},{"t":"label","id":"2-3A","title":"乾的沙灘","ln":279},{"t":"say","k":"n","text":"我想到第一次見到她的那天，我走回去，在她旁邊坐下。沙子被太陽曬得暖暖的。","id":"16kzp2b","ln":281},{"t":"say","k":"d","who":"孫承完","text":"「那就在這裡看吧。從這裡看，海也很漂亮。」","ln":283,"id":"1gs5itv"},{"t":"say","k":"n","text":"她愣了一下，然後慢慢坐下來，抱著膝蓋。","id":"li6myv","ln":285},{"t":"say","k":"d","who":"裴柱現","text":"「……妳不問為什麼？」","ln":287,"expr":"普通","id":"d52r57"},{"t":"say","k":"d","who":"孫承完","text":"「妳想說的時候再說就好。」","ln":289,"id":"mzesjq"},{"t":"show","list":[{"c":"裴柱現","e":"害羞"}],"ln":291},{"t":"say","k":"n","text":"她沒有說話。我們就這樣看了很久的海，看雲從一塊大陸變成另一塊大陸。","id":"1x37tz7","ln":293},{"t":"say","k":"n","text":"過了一會兒，她問：","id":"4f8vg2","ln":295},{"t":"say","k":"d","who":"裴柱現","text":"「孫承完，妳為什麼當救生員？」","ln":297,"expr":"普通","id":"15wijh0"},{"t":"say","k":"d","who":"孫承完","text":"「……我爸爸以前是漁夫。我十二歲那年，有艘觀光船在暴風雨裡翻了，他開船出去救人。救回來六個。」","ln":299,"id":"1hdx15l"},{"t":"say","k":"d","who":"孫承完","text":"「他自己沒有回來。」","ln":301,"id":"aahkfq"},{"t":"say","k":"n","text":"姐姐轉過頭看我。","id":"mjioln","ln":303},{"t":"say","k":"d","who":"裴柱現","text":"「……海拿走了妳的爸爸。」","ln":305,"id":"giksvc"},{"t":"say","k":"d","who":"孫承完","text":"「嗯。」","ln":307,"id":"16inj09"},{"t":"say","k":"d","who":"裴柱現","text":"「妳不恨海嗎？」","ln":309,"id":"1kqk0ar"},{"t":"say","k":"d","who":"孫承完","text":"「恨過啊。恨了好幾年。」","ln":311,"id":"1negm6d"},{"t":"say","k":"n","text":"我撿起一顆小石頭，在手裡轉。","id":"r2e248","ln":313},{"t":"say","k":"d","who":"孫承完","text":"「可是奶奶說，海也會難過。她說海裡面也有人在等人回家，就跟我們一樣。所以她每天都唱歌給海聽。」","ln":315,"id":"11sxjz"},{"t":"say","k":"d","who":"孫承完","text":"「很奇怪的老太太吧。」","ln":317,"expr":"笑","id":"1jp82rp"},{"t":"say","k":"n","text":"姐姐很久都沒有說話。","id":"ssnxj7","ln":319},{"t":"show","list":[{"c":"裴柱現","e":"難過"}],"ln":321},{"t":"say","k":"n","text":"她看著海，眼眶跟鼻子又紅了。可是跟那天喝熱湯一樣，一滴眼淚都沒有掉下來。","id":"13s3n55","ln":323},{"t":"say","k":"d","who":"裴柱現","text":"「……一點都不奇怪。」","ln":325,"id":"h5wbp2"},{"t":"say","k":"n","text":"她的聲音很輕，輕得幾乎被浪聲蓋過。","id":"16pyw4g","ln":327},{"t":"jump","to":"2-4","ln":329},{"t":"label","id":"2-3B","title":"浪","ln":331},{"t":"say","k":"d","who":"孫承完","text":"「來嘛，一下下就好！」","ln":333,"expr":"笑","id":"1ql4cty"},{"t":"say","k":"n","text":"我跑回去拉起她的手，笑著往浪花的方向拖。","id":"c4ky4x","ln":335},{"t":"show","list":[{"c":"裴柱現","e":"驚慌"}],"ln":337},{"t":"say","k":"d","who":"裴柱現","text":"「不要——！」","ln":339,"id":"1y21jo6"},{"t":"say","k":"n","text":"她用力甩開我的手。力氣大得嚇人，我差點往後跌倒。","id":"19g0urf","ln":341},{"t":"say","k":"n","text":"一道浪剛好在這時候打上來，舔過她的腳尖。她像被燙到一樣往後跳了一大步，把那隻腳整個埋進乾沙裡。","id":"evkn0a","ln":343},{"t":"say","k":"n","text":"我好像又看到了。她的腳背上，一閃一閃的，湛藍色的光。","id":"jwfhfk","ln":345},{"t":"say","k":"d","who":"孫承完","text":"「……姐姐？」","ln":347,"expr":"驚訝","id":"10skmyu"},{"t":"show","list":[{"c":"裴柱現","e":"難過"}],"ln":349},{"t":"say","k":"d","who":"裴柱現","text":"「……對不起。」","ln":351,"id":"1ssl3c0"},{"t":"say","k":"n","text":"她低著頭，聲音在發抖。","id":"a80w3z","ln":353},{"t":"say","k":"d","who":"裴柱現","text":"「我只是……不喜歡海水。」","ln":355,"id":"146mz5s"},{"t":"say","k":"d","who":"孫承完","text":"「……那妳為什麼要住在海邊？」","ln":357,"id":"wer6oi"},{"t":"say","k":"n","text":"她沉默了很久。","id":"n0knxe","ln":359},{"t":"say","k":"d","who":"裴柱現","text":"「因為這裡，有人唱歌。」","ln":361,"expr":"普通","id":"z27zel"},{"t":"say","k":"n","text":"她說完就轉身走了。我站在浪花裡，手上還留著被甩開時的那一點痛。","id":"qagnwr","ln":363},{"t":"say","k":"i","text":"（……我是不是做錯什麼了。）","id":"jqg3j8","ln":365},{"t":"jump","to":"2-4","ln":367},{"t":"label","id":"2-4","title":"休假日","ln":369},{"t":"hide","all":true,"ln":371},{"t":"bg","name":"白鹽灣海岸道路・白天","ln":372},{"t":"bgm","name":"白鹽灣日常","ln":373},{"t":"say","k":"n","text":"幾天後，我又休假了。我問柱現姐姐，她有沒有什麼想做的事。","id":"6mun2b","ln":375},{"t":"show","list":[{"c":"裴柱現","e":"普通"}],"ln":377},{"t":"say","k":"d","who":"裴柱現","text":"「想做的事？」","ln":379,"id":"2b2l4e"},{"t":"say","k":"d","who":"孫承完","text":"「嗯。來白鹽灣之後，有沒有什麼想試試看的？」","ln":381,"id":"1a1ztvg"},{"t":"say","k":"n","text":"她認真地想了很久。","id":"12jr78q","ln":383},{"t":"say","k":"d","who":"裴柱現","text":"「……那個有兩個輪子、人坐在上面、腳一直轉的東西。」","ln":385,"id":"170flc6"},{"t":"say","k":"d","who":"孫承完","text":"「腳踏車？」","ln":387,"id":"1q7x3id"},{"t":"say","k":"d","who":"裴柱現","text":"「先說我不是不會。我只是沒有騎過。」","ln":389,"expr":"得意","id":"1dzcmx1"},{"t":"say","k":"d","who":"孫承完","text":"「那不就是不會嗎。」","ln":391,"id":"16wwe7y"},{"t":"say","k":"d","who":"裴柱現","text":"「不一樣。」","ln":393,"expr":"生氣","id":"1nfgm05"},{"t":"say","k":"d","who":"裴柱現","text":"「還有……阿英說，妳們晚上會在沙灘上圍著火唱歌。」","ln":395,"id":"h037ku"},{"t":"say","k":"n","text":"她說這句話的時候，眼睛亮了一下。","id":"19m6alo","ln":397},{"t":"choice","title":"選擇③","options":[{"key":"A","text":"教姐姐騎腳踏車","to":"2-4A","eff":[{"s":"心動","d":1}]},{"key":"B","text":"帶姐姐去聽露營團唱歌","to":"2-4B","eff":[{"s":"心動","d":2}]}],"ln":399},{"t":"label","id":"2-4A","title":"腳踏車特訓","ln":403},{"t":"bg","name":"白鹽灣海岸道路・黃昏","ln":405},{"t":"say","k":"n","text":"我向康借了一台淑女車，在海岸道路的空地上開始特訓。","id":"u4hvbu","ln":407},{"t":"say","k":"n","text":"康借我車的條件是一份炸雞。她說這叫「租金」。","id":"1hmfxp3","ln":409},{"t":"say","k":"n","text":"結果比我想像的還慘。","id":"3wnsi8","ln":411},{"t":"say","k":"d","who":"裴柱現","text":"「我知道了。坐上去，然後轉腳。」","ln":413,"expr":"得意","id":"zl08sz"},{"t":"say","k":"n","text":"她坐上去，轉腳，然後連人帶車倒進路邊的草叢裡。","id":"1mptau1","ln":415},{"t":"say","k":"d","who":"裴柱現","text":"「……這東西有問題。」","ln":417,"expr":"生氣","id":"1spy44y"},{"t":"say","k":"d","who":"孫承完","text":"「是妳沒有往前看。」","ln":419,"id":"83va1x"},{"t":"say","k":"n","text":"第二次，倒。第三次，倒。第七次，她倒下去的時候還順便把我也撞倒了。","id":"1pfseo5","ln":421},{"t":"say","k":"d","who":"裴柱現","text":"「為什麼人類要發明一種會自己倒下去的東西！」","ln":423,"expr":"生氣","id":"ip5mnn"},{"t":"say","k":"d","who":"孫承完","text":"「……妳又說人類了。」","ln":425,"expr":"笑","id":"zxaijh"},{"t":"say","k":"d","who":"裴柱現","text":"「我是說，為什麼『我們』要發明。」","ln":427,"expr":"驚慌","id":"1s315nl"},{"t":"say","k":"n","text":"到了第十二次，她終於願意讓我扶著後座。","id":"1lmpjmn","ln":429},{"t":"say","k":"d","who":"孫承完","text":"「我扶著喔，妳只要往前看就好。」","ln":431,"id":"zns0gm"},{"t":"say","k":"d","who":"裴柱現","text":"「妳不准放手。」","ln":433,"id":"1nn7ri6"},{"t":"say","k":"d","who":"孫承完","text":"「好，我不放。」","ln":435,"id":"yhxrkb"},{"t":"say","k":"n","text":"我扶著後座跟著她跑。跑著跑著，車子愈來愈穩。","id":"wxenpd","ln":437},{"t":"say","k":"n","text":"然後我偷偷放開了手。","id":"ms1g18","ln":439},{"t":"cg","id":"05","title":"腳踏車特訓","ln":441},{"t":"say","k":"n","text":"她一個人騎在海岸道路上，夕陽把整片海染成金色。風把她的長髮整個吹起來，像一面藍黑色的旗子。","id":"262rrp","ln":443},{"t":"say","k":"n","text":"她在笑。","id":"1re9zyp","ln":445},{"t":"say","k":"n","text":"不是那種得意的、抬著下巴的笑，而是張開嘴、笑出聲音、像小孩子一樣的笑。","id":"1tgi5uc","ln":447},{"t":"say","k":"d","who":"裴柱現","text":"「孫承完！孫承完妳看！我在騎——」","ln":449,"id":"19w6ig4"},{"t":"say","k":"n","text":"她回過頭來，看見我站在二十公尺外。","id":"185myzc","ln":451},{"t":"say","k":"d","who":"裴柱現","text":"「……妳放手了？」","ln":453,"id":"1dzwfue"},{"t":"say","k":"d","who":"孫承完","text":"「嗯。」","ln":455,"id":"15oopxc"},{"t":"say","k":"d","who":"裴柱現","text":"「妳說妳不放的——！」","ln":457,"id":"m4lrt3"},{"t":"say","k":"n","text":"她不知道怎地還學會轉彎了，然後她連人帶車衝向我。","id":"1dgtfnq","ln":459},{"t":"say","k":"n","text":"我們一起倒在路邊的草地上。腳踏車在旁邊轉著輪子，她撐在我上方，頭髮垂下來，像一片簾子把我們和整個世界隔開。","id":"1mchp6g","ln":461},{"t":"say","k":"n","text":"她的臉離我很近。","id":"1gcl1df","ln":463},{"t":"say","k":"n","text":"近到我聞得到她身上的味道。不是香水，是海的味道。很神祕、很深的那種海。","id":"b9sqse","ln":465},{"t":"say","k":"d","who":"裴柱現","text":"「……妳說謊。」","ln":467,"expr":"害羞","id":"f1yyhq"},{"t":"say","k":"d","who":"孫承完","text":"「對不起。」","ln":469,"id":"1wzrykr"},{"t":"say","k":"d","who":"裴柱現","text":"「人類都這樣說謊嗎？」","ln":471,"id":"8blhwd"},{"t":"say","k":"d","who":"孫承完","text":"「……妳又說人類了。」","ln":473,"id":"z3bpgk"},{"t":"say","k":"n","text":"她沒有改口。她只是看著我，看了很久很久，然後很小聲地說：","id":"12mesik","ln":475},{"t":"say","k":"d","who":"裴柱現","text":"「……下次不准再放手。」","ln":477,"id":"hedz2"},{"t":"cgEnd","ln":479},{"t":"jump","to":"2-5","ln":480},{"t":"label","id":"2-4B","title":"營火","ln":482},{"t":"bg","name":"白鹽灣沙灘・夜","ln":484},{"t":"bgm","name":"營火之歌","ln":485},{"t":"se","names":["營火","海浪"],"ln":486},{"t":"say","k":"n","text":"那天晚上，露營團又在沙灘上生了火。","id":"l2e4tf","ln":488},{"t":"show","list":[{"c":"康","e":"大笑"},{"c":"裴柱現","e":"普通"}],"ln":490},{"t":"say","k":"n","text":"康一看到姐姐，就自告奮勇要唱歌給她聽。她唱了兩句就忘詞了，愣了三秒，然後很自然地接上了鎮上炸雞店的廣告歌。","id":"1szd3fx","ln":492},{"t":"say","k":"d","who":"裴柱現","text":"「……她是不是餓了？」","ln":494,"expr":"難過","id":"gi8fbf"},{"t":"say","k":"d","who":"孫承完","text":"「她一直都很餓。」","ln":496,"id":"2f5335"},{"t":"say","k":"d","who":"康","text":"「我沒有！……好啦有一點。」","ln":498,"expr":"慌張","id":"1qmg1xa"},{"t":"say","k":"n","text":"她從背包裡掏出一包棉花糖，插在樹枝上烤，烤好的第一串遞給了阿英。","id":"1d0cvzv","ln":500},{"t":"show","list":[{"c":"阿英","e":"普通"}],"ln":502},{"t":"say","k":"n","text":"阿英看都沒看就接過去了。康看著她吃，傻笑了很久。","id":"1mtay95","ln":504},{"t":"say","k":"i","text":"（……康啊……全世界都知道，只有阿英在裝傻。）","id":"1i1raug","ln":506},{"t":"say","k":"n","text":"阿英坐在對面，一邊吃棉花糖，一邊不動聲色地觀察姐姐。","id":"g49vqy","ln":508},{"t":"say","k":"n","text":"姐姐轉過頭看我。","id":"mtiaam","ln":510},{"t":"say","k":"d","who":"裴柱現","text":"「我要聽妳唱。」","ln":512,"expr":"普通","id":"3c3ha"},{"t":"say","k":"d","who":"孫承完","text":"「我？」","ln":514,"id":"v976lq"},{"t":"say","k":"d","who":"裴柱現","text":"「妳唱的才是歌。」","ln":516,"id":"1gnoa8j"},{"t":"say","k":"n","text":"她說得理所當然，好像在陳述海是鹹的這種事實。我的耳朵一下子熱起來。","id":"71c7o7","ln":518},{"t":"se","names":["刷和弦"],"ln":520},{"t":"say","k":"n","text":"我拿起吉他，唱了一首很老的、關於離別的情歌。不是奶奶的漁歌——不知道為什麼，我不想在大家面前唱那首。","id":"1e0dbzf","ln":522},{"t":"say","k":"n","text":"我唱著唱著，感覺到肩膀上一沉。","id":"b2swe9","ln":524},{"t":"say","k":"n","text":"姐姐靠過來了。","id":"r3vkad","ln":526},{"t":"say","k":"n","text":"一開始只是輕輕挨著，唱到副歌的時候，她整個人已經靠在我肩上，閉著眼睛，呼吸很慢很慢，像睡著了，又像在很專心地聽。","id":"186wgus","ln":528},{"t":"say","k":"n","text":"我不敢動。手指差點彈錯和弦。","id":"hcjj6j","ln":530},{"t":"say","k":"n","text":"一曲唱完，營火劈啪響了一聲。","id":"dfx3tf","ln":532},{"t":"say","k":"d","who":"裴柱現","text":"「……人類的歌，原來是這樣的。」","ln":534,"expr":"恍惚","id":"1vsz1fx"},{"t":"show","list":[{"c":"康","e":"慌張"}],"ln":536},{"t":"say","k":"n","text":"康在旁邊哭得一塌糊塗，嘴裡還塞著棉花糖。","id":"1ltefbg","ln":538},{"t":"say","k":"d","who":"康","text":"「好好聽……嗚……承完妳怎麼可以唱得這麼好聽……」","ln":540,"id":"141qqzt"},{"t":"say","k":"n","text":"阿英看也沒看，就把一張面紙遞過去。康接過面紙，哭得更大聲了，臉紅到耳朵。","id":"xnb6vq","ln":542},{"t":"say","k":"n","text":"阿英沒有理她。她只是看著姐姐，很輕地重複了一次：","id":"4h1lcj","ln":544},{"t":"say","k":"d","who":"阿英","text":"「……『人類的歌』？」","ln":546,"expr":"認真","id":"1tcq8uw"},{"t":"say","k":"n","text":"姐姐沒有聽見。她還靠在我肩上，嘴角帶著一點點笑。","id":"8yqlwj","ln":548},{"t":"jump","to":"2-5","ln":550},{"t":"label","id":"2-5","title":"窗","ln":552},{"t":"hide","all":true,"ln":554},{"t":"bg","name":"酒吧「退潮」・夜","ln":555},{"t":"bgm","name":"夜","ln":556},{"t":"say","k":"n","text":"那天晚上，我送姐姐回到「退潮」。她上樓之後，阿英小聲把我叫住。","id":"vz1kh1","ln":558},{"t":"show","list":[{"c":"阿英","e":"認真"}],"ln":560},{"t":"say","k":"d","who":"阿英","text":"「承完。」","ln":562,"id":"1g9s02p"},{"t":"say","k":"d","who":"孫承完","text":"「嗯？」","ln":564,"id":"1taosdg"},{"t":"say","k":"d","who":"阿英","text":"「那個女人很怪。」","ln":566,"id":"b43ngj"},{"t":"say","k":"n","text":"阿英含著薄荷糖，一條一條地數給我聽。","id":"4w33mw","ln":568},{"t":"say","k":"d","who":"阿英","text":"「她不知道錢是什麼，第一天拿貝殼跟我找零。她半夜會跑去廚房吃生魚，整條的。她會跟那隻寄居蟹講話，而且吵架。她說她從海的那邊來，可是她連腳都不肯碰海水。」","ln":570,"id":"1362dgl"},{"t":"say","k":"d","who":"孫承完","text":"「……妳是嫉妒她業績比妳好吧。」","ln":572,"id":"1e815pq"},{"t":"say","k":"d","who":"阿英","text":"「我是擔心妳。」","ln":574,"expr":"擔心","id":"dcozlu"},{"t":"say","k":"n","text":"她把薄荷糖咬碎了。","id":"r6zw3n","ln":576},{"t":"say","k":"d","who":"阿英","text":"「妳每次都這樣！先救人，才想到自己。」","ln":578,"id":"pl41cp"},{"t":"say","k":"n","text":"我不知道該說什麼。","id":"adk4kx","ln":580},{"t":"say","k":"n","text":"走出酒吧的時候，我回頭看了一眼。","id":"f60zc2","ln":582},{"t":"say","k":"n","text":"二樓儲藏室的窗戶開著。","id":"t6zv8k","ln":584},{"t":"say","k":"n","text":"柱現姐姐站在窗邊，看著海。月光照在她臉上，那張美得不合理的臉，讓此刻像一幅畫。窗台上，那隻寄居蟹也朝著同一個方向。","id":"q9ai7m","ln":586},{"t":"say","k":"n","text":"她看著海的樣子，不知道為什麼特別悲傷。","id":"15a9m7s","ln":588},{"t":"say","k":"n","text":"我站在堤防下，也看了她很久。","id":"1j8vr58","ln":590},{"t":"say","k":"n","text":"她沒有發現我。","id":"5fjcei","ln":592},{"t":"chend","text":"第二章　完","ln":594}]},{"key":"03_第三章_不能下海的人","name":"03_第三章_不能下海的人.md","route":"main","num":3,"title":"第三章　不能下海的人","ops":[{"t":"title","text":"第三章　不能下海的人","card":true,"ln":1},{"t":"label","id":"3-1","title":"傳說","ln":3},{"t":"bg","name":"酒吧「退潮」・夜","ln":5},{"t":"bgm","name":"白鹽灣日常","ln":6},{"t":"say","k":"n","text":"三月了。","id":"1vbk88e","ln":8},{"t":"say","k":"n","text":"白鹽灣的三月，是觀光客開始變多、救生員開始變忙的季節。我每天在瞭望台上吹哨子吹到嘴唇發麻，下班後就窩到「退潮」的吧檯。","id":"yzjsh7","ln":10},{"t":"say","k":"n","text":"姐姐來白鹽灣快兩個禮拜，已經學會了很多事。","id":"yrdvaa","ln":12},{"t":"say","k":"n","text":"她學會用錢找零了。學會了蛤蜊湯要吹涼再喝。學會了在客人搭訕的時候，用一個眼神讓對方自己默默走開。","id":"1x7iw5r","ln":14},{"t":"say","k":"n","text":"可她還是不肯碰海水。","id":"1d0s3p9","ln":16},{"t":"say","k":"n","text":"我約過她三次游泳。第一次她說頭痛，第二次她說生理期，第三次更扯，她說：「我對鹽過敏。」","id":"bi03zf","ln":18},{"t":"say","k":"i","text":"（……那妳每天吃的生魚片是怎麼回事。）","id":"zpl8to","ln":20},{"t":"say","k":"n","text":"那天晚上，姐姐被阿英派去倉庫搬酒，吧檯只剩我、阿英和康。","id":"1xyeeit","ln":22},{"t":"show","list":[{"c":"康","e":"普通"},{"c":"阿英","e":"普通"}],"ln":24},{"t":"say","k":"d","who":"康","text":"「欸，承完，今年春潮祭妳要上台吧？」","ln":26,"expr":"普通","id":"jab0fq"},{"t":"say","k":"d","who":"孫承完","text":"「我？」","ln":28,"id":"6xtuma"},{"t":"say","k":"d","who":"康","text":"「漁會的陳伯說的啊。他說妳阿嬤以前每年都上台唱那首漁歌，今年想請妳接棒。」","ln":30,"id":"c9sguk"},{"t":"say","k":"d","who":"孫承完","text":"「……我考慮看看。」","ln":32,"id":"1wetc0g"},{"t":"say","k":"n","text":"春潮祭是白鹽灣每年春分的祭典。家家戶戶在堤防上擺攤，晚上點燈，最後全鎮的人一起對著海唱那首漁歌。","id":"1ssqxzj","ln":34},{"t":"say","k":"n","text":"為什麼要對海唱歌？沒有人知道。大家只知道，以前的人一直都這樣做。","id":"pc81d5","ln":36},{"t":"say","k":"n","text":"阿英擦著杯子，突然開口：","id":"10bpveu","ln":38},{"t":"say","k":"d","who":"阿英","text":"「妳們知道那首歌為什麼要對著海唱嗎？」","ln":40,"expr":"普通","id":"1v2rfi3"},{"t":"say","k":"d","who":"康","text":"「為了漁獲？」","ln":42,"id":"u91isr"},{"t":"say","k":"d","who":"阿英","text":"「我阿嬤說，是為了讓海裡的東西不要生氣。」","ln":44,"id":"frytv2"},{"t":"say","k":"n","text":"她放下杯子。","id":"bqcwl8","ln":46},{"t":"say","k":"d","who":"阿英","text":"「她說以前白鹽灣的海裡住著會唱歌的東西。月亮很圓的晚上，牠們會浮到船邊唱歌。聽到歌聲的漁夫，隔天早上會被發現躺在沙灘上，臉上帶著笑，好像做了這輩子最好的夢。」","ln":48,"expr":"認真","id":"1ioh2c3"},{"t":"say","k":"d","who":"阿英","text":"「但是他們會老好幾歲。頭髮白了，力氣也沒了，像是被吸走靈魂。有的再也沒醒過來。」","ln":50,"id":"krfzbq"},{"t":"say","k":"d","who":"孫承完","text":"「……被什麼東西？」","ln":52,"id":"ob8zlw"},{"t":"say","k":"d","who":"阿英","text":"「人魚。」","ln":54,"id":"1mz2u4m"},{"t":"say","k":"d","who":"康","text":"「人魚！我知道我知道，吃人魚肉會長生不老！」","ln":56,"expr":"大笑","id":"qk60wa"},{"t":"say","k":"d","who":"康","text":"「……欸，人魚吃起來是魚的味道，還是人的味道啊？」","ln":58,"expr":"普通","id":"jmfzko"},{"t":"say","k":"d","who":"阿英","text":"「康。」","ln":60,"expr":"擔心","id":"kt0sk1"},{"t":"say","k":"d","who":"康","text":"「我只是好奇！」","ln":62,"id":"binrve"},{"t":"say","k":"d","who":"阿英","text":"「那是另一個傳說。比較噁心的那個。」","ln":64,"id":"1v2gi7n"},{"t":"say","k":"n","text":"阿英的聲音冷了下來，又說起那個故事。","id":"8gaemz","ln":66},{"t":"say","k":"d","who":"阿英","text":"「三百年前，鎮上的人真的信了。他們造了特別的網，在月圓的晚上出海去抓。阿嬤說那一年，整片海都是紅的，也抓不到魚。」","ln":68,"id":"qthzm1"},{"t":"say","k":"n","text":"酒吧安靜了一下。康默默放下了手上的花生。","id":"9jsvth","ln":70},{"t":"say","k":"d","who":"阿英","text":"「從那之後，海上就再也沒有人唱歌了。不管是人，還是別的什麼。」","ln":72,"id":"27odtz"},{"t":"say","k":"d","who":"孫承完","text":"「……阿英，妳講這些幹嘛。」","ln":74,"id":"1ssorva"},{"t":"say","k":"n","text":"阿英看著我。","id":"qb776y","ln":76},{"t":"say","k":"d","who":"阿英","text":"「沒幹嘛。只是覺得，妳最近該聽一下。」","ln":78,"expr":"認真","id":"lsvl18"},{"t":"say","k":"n","text":"倉庫的門開了。柱現姐姐抱著一箱啤酒走出來，看到我們三個同時閉嘴，挑了挑眉毛。","id":"1rlmpr0","ln":80},{"t":"show","list":[{"c":"裴柱現","e":"普通"}],"ln":82},{"t":"say","k":"d","who":"裴柱現","text":"「妳們在講我的壞話？」","ln":84,"id":"xck6z7"},{"t":"say","k":"d","who":"康","text":"「沒有！在講人魚！還有人魚是什麼味道！」","ln":86,"expr":"慌張","id":"18pf6pk"},{"t":"say","k":"n","text":"柱現姐姐手上那箱啤酒，掉在了地上。","id":"z9n2ea","ln":88},{"t":"se","names":["玻璃碎裂"],"ln":90},{"t":"label","id":"3-2","title":"礁石","ln":92},{"t":"hide","all":true,"ln":94},{"t":"trans","kind":"out","ln":95},{"t":"bg","name":"礁石海岸・夜","ln":96},{"t":"trans","kind":"in","ln":97},{"t":"bgm","name":"夜","ln":98},{"t":"se","names":["海浪"],"ln":99},{"t":"say","k":"n","text":"幾天後的晚上，輪到我夜間巡邏。","id":"7tpnis","ln":101},{"t":"say","k":"n","text":"我拿著手電筒沿著海岸走，走到北邊那片礁石區的時候，聽見了說話的聲音。","id":"302z8b","ln":103},{"t":"say","k":"n","text":"是柱現姐姐。","id":"1vazuxn","ln":105},{"t":"say","k":"n","text":"她站在最外側的一塊礁石上，背對著我，面向海。月光很亮，把她的影子拉得長長的。她的肩膀上，蹲著那隻寄居蟹。","id":"10ipig6","ln":107},{"t":"say","k":"n","text":"她……在跟海說話？","id":"7epk3y","ln":109},{"t":"say","k":"d","who":"裴柱現","text":"「……我知道期限。」","ln":111,"id":"659qd7"},{"t":"say","k":"d","who":"裴柱現","text":"「不用一直提醒我。」","ln":113,"id":"cdjbbx"},{"t":"say","k":"n","text":"浪拍在礁石上，碎成白色的泡沫。浪聲裡，好像夾著另一個聲音。冷冷的，很遠，聽不清楚在說什麼。","id":"ybp44u","ln":115},{"t":"say","k":"d","who":"裴柱現","text":"「我會帶回去的。成年禮……我會帶回去的。」","ln":117,"id":"1g73syn"},{"t":"say","k":"d","who":"裴柱現","text":"「只是……再給我一點時間。」","ln":119,"id":"1g251h5"},{"t":"say","k":"n","text":"我看見離礁石不遠的海面上，有什麼東西閃了一下。","id":"1o306ot","ln":121},{"t":"say","k":"n","text":"銀白色的。很長。","id":"1k2oj55","ln":123},{"t":"say","k":"n","text":"像一條魚的尾巴，大得不像話的那種。","id":"1x1mhez","ln":125},{"t":"say","k":"n","text":"然後它沉下去了，海面只剩一圈漣漪。","id":"1exrgpm","ln":127},{"t":"say","k":"n","text":"姐姐低下頭，很久都沒有動。寄居蟹用鉗子碰了碰她的臉。","id":"1nqzl66","ln":129},{"t":"say","k":"i","text":"（……她在跟誰說話？）","id":"53ch2t","ln":131},{"t":"choice","title":"選擇④","options":[{"key":"A","text":"當作沒看到，悄悄離開","to":"3-2A","eff":[{"s":"信任","d":1}]},{"key":"B","text":"上前追問","to":"3-2B","eff":[{"s":"信任","d":-1}]}],"ln":133},{"t":"label","id":"3-2A","title":"沒看到","ln":137},{"t":"say","k":"n","text":"我關掉手電筒，往後退。","id":"vjltdv","ln":139},{"t":"say","k":"n","text":"一步、兩步——腳下踩碎了一片貝殼。","id":"xc9r7k","ln":141},{"t":"se","names":["腳步"],"ln":143},{"t":"say","k":"n","text":"裴柱現猛地回過頭來。","id":"kmo2d4","ln":145},{"t":"show","list":[{"c":"裴柱現","e":"驚慌"}],"ln":147},{"t":"say","k":"n","text":"我們隔著十幾公尺的礁石，在月光下看著彼此。","id":"1yt1o0z","ln":149},{"t":"say","k":"n","text":"她的表情很慌張，像一個被抓到偷東西的小孩。她張開嘴，好像想解釋什麼。","id":"1o78lyr","ln":151},{"t":"say","k":"n","text":"我只是朝她揮了揮手。","id":"1b73bii","ln":153},{"t":"say","k":"n","text":"然後轉身走了。","id":"171e1l3","ln":155},{"t":"hide","list":["裴柱現"],"ln":157},{"t":"say","k":"n","text":"隔天早上，我在瞭望台的欄杆上發現一個貝殼。","id":"18ylhho","ln":159},{"t":"say","k":"n","text":"很大、很漂亮的那種，內側是珍珠一樣的顏色，被人仔細地洗過、擦乾，端端正正地擺在那裡。","id":"2114di","ln":161},{"t":"say","k":"n","text":"沒有紙條，沒有署名。","id":"ymjk52","ln":163},{"t":"say","k":"n","text":"可是我知道是誰放的。","id":"10h8kv9","ln":165},{"t":"jump","to":"3-3","ln":167},{"t":"label","id":"3-2B","title":"追問","ln":169},{"t":"say","k":"d","who":"孫承完","text":"「姐姐。」","ln":171,"id":"1lgt9c2"},{"t":"show","list":[{"c":"裴柱現","e":"驚慌"}],"ln":173},{"t":"say","k":"n","text":"她猛地回過頭來，寄居蟹差點從她肩膀上掉下去。","id":"1rsbx4j","ln":175},{"t":"say","k":"d","who":"孫承完","text":"「這麼晚了，妳在這裡跟誰講話？」","ln":177,"id":"sgkg4c"},{"t":"say","k":"d","who":"裴柱現","text":"「……跟螃蟹。」","ln":179,"expr":"普通","id":"mv0n1y"},{"t":"say","k":"d","who":"孫承完","text":"「螃蟹會回答妳嗎？」","ln":181,"id":"lwom3n"},{"t":"say","k":"d","who":"裴柱現","text":"「會。牠很囉嗦。」","ln":183,"id":"ruzcwt"},{"t":"say","k":"n","text":"寄居蟹舉起鉗子，好像在抗議。","id":"qkef4f","ln":185},{"t":"say","k":"n","text":"我走近了一點。","id":"d4dimj","ln":187},{"t":"say","k":"d","who":"孫承完","text":"「我聽到妳說期限。還有成年禮。姐姐，妳是不是遇到什麼麻煩？如果是欠錢還是什麼的，我可以——」","ln":189,"expr":"認真","id":"pvu0ju"},{"t":"say","k":"d","who":"裴柱現","text":"「孫承完。」","ln":191,"expr":"生氣","id":"o0z0wl"},{"t":"say","k":"n","text":"她打斷我。聲音很冷，是我從沒聽過的冷。","id":"11m5o4h","ln":193},{"t":"say","k":"d","who":"裴柱現","text":"「妳管太多了。」","ln":195,"id":"iqozht"},{"t":"say","k":"n","text":"她從礁石上跳下來，從我身邊走過去，連看都沒有看我一眼。","id":"1jcof99","ln":197},{"t":"hide","list":["裴柱現"],"ln":199},{"t":"say","k":"n","text":"我站在原地，手電筒的光在礁石上晃。","id":"1obs1g8","ln":201},{"t":"say","k":"n","text":"海面上什麼都沒有了。","id":"m6tkoa","ln":203},{"t":"say","k":"i","text":"（……我只是想幫妳。）","id":"7rdifk","ln":205},{"t":"jump","to":"3-3","ln":207},{"t":"label","id":"3-3","title":"雨","ln":209},{"t":"hide","all":true,"ln":211},{"t":"bg","name":"救生站・黃昏","ln":212},{"t":"bgm","stop":"stop","ln":213},{"t":"se","names":["雨"],"ln":214},{"t":"say","k":"n","text":"三月的雨，總是來得很突然。","id":"kdtpbe","ln":216},{"t":"say","k":"n","text":"那天傍晚，天空一下子暗下來，豆大的雨點砸在沙灘上，遊客尖叫著往堤防跑。我吹哨清場，確定海裡一個人都沒有之後，才躲回救生站的小屋。","id":"l4xws6","ln":218},{"t":"say","k":"n","text":"然後我看見姐姐站在雨裡。","id":"bs5dny","ln":220},{"t":"show","list":[{"c":"裴柱現","e":"笑"}],"ln":222},{"t":"say","k":"n","text":"她手上抱著一個便當盒，全身濕透，頭髮貼在臉上。可是她沒有躲，反而仰起臉，張開手，讓雨打在身上。","id":"1j1jq7","ln":224},{"t":"say","k":"n","text":"她在笑。笑得好開心、好放鬆，像終於卸下了什麼很重的東西。","id":"8ugx2l","ln":226},{"t":"say","k":"d","who":"孫承完","text":"「姐姐！妳在幹嘛！快進來！」","ln":228,"expr":"驚訝","id":"1b6kaff"},{"t":"say","k":"n","text":"我衝出去把她拉進小屋。她還在笑。","id":"1baw28w","ln":230},{"t":"say","k":"d","who":"裴柱現","text":"「是雨！」","ln":232,"id":"sywsvf"},{"t":"say","k":"d","who":"孫承完","text":"「我知道是雨！妳會感冒的！」","ln":234,"id":"579go7"},{"t":"say","k":"d","who":"裴柱現","text":"「雨是甜的。妳知道嗎？雨是甜的。」","ln":236,"expr":"笑","id":"1ln9qnj"},{"t":"say","k":"n","text":"我不知道她在說什麼。我只知道她的手好冰。","id":"u8omq4","ln":238},{"t":"bg","name":"救生站小屋・夜","ln":240},{"t":"bgm","name":"心動","ln":241},{"t":"se","names":["雨（室內）"],"ln":242},{"t":"say","k":"n","text":"小屋很小，只有一張長椅、一個置物櫃，和一盞昏黃的燈。","id":"1br88lg","ln":244},{"t":"say","k":"n","text":"我從櫃子裡拿出毛巾，正是她當初「借走」、後來又還給我的那一條，蓋在她頭上，開始幫她擦頭髮。","id":"6yncf6","ln":246},{"t":"say","k":"d","who":"裴柱現","text":"「……我自己來。」","ln":248,"expr":"害羞","id":"1v2hxy3"},{"t":"say","k":"d","who":"孫承完","text":"「別動。」","ln":250,"id":"6rpy5o"},{"t":"say","k":"n","text":"她就真的不動了。","id":"3aq3h8","ln":252},{"t":"say","k":"n","text":"雨聲把整個世界都關在外面。小屋裡只剩下燈光、毛巾摩擦頭髮的聲音，和她的呼吸。","id":"ien5pj","ln":254},{"t":"say","k":"n","text":"她的頭髮好長，吸飽了水，沉甸甸的，在我手裡像一匹深色的絲。我一點一點擦，擦到她的耳後。她的耳朵涼得像一塊浸在水裡的玉。","id":"16c1s7f","ln":256},{"t":"say","k":"d","who":"孫承完","text":"「……那個便當是什麼？」","ln":258,"id":"1uhpxnd"},{"t":"say","k":"d","who":"裴柱現","text":"「給妳的。我做的。」","ln":260,"expr":"得意","id":"hced7h"},{"t":"say","k":"n","text":"我先將毛巾披在她頭上，接著打開便當蓋。裡面是一整條生的竹莢魚，眼睛還亮晶晶的。旁邊用海苔排出了一個胖胖歪歪的愛心。","id":"1yfnjq","ln":262},{"t":"say","k":"d","who":"孫承完","text":"「……謝謝姐姐。」","ln":264,"expr":"笑","id":"1mbuwrg"},{"t":"say","k":"d","who":"裴柱現","text":"「阿英說，人類……人喜歡收到親手做的便當。」","ln":266,"expr":"害羞","id":"1rnqchm"},{"t":"say","k":"n","text":"我笑出聲，她也笑了。笑著笑著，我們就安靜了下來。","id":"mxz0p9","ln":268},{"t":"say","k":"n","text":"毛巾從她頭上滑下來。我伸手想接，但沒接到，手停在她的臉頰邊，沒有收回來。","id":"9srcn9","ln":270},{"t":"say","k":"n","text":"她抬起頭看我。","id":"3ak5b8","ln":272},{"t":"say","k":"n","text":"燈光很暗，她的眼睛顯得更深了。睫毛上掛著雨水，嘴唇因為冷，顏色比平常更淡。瀏海還在一滴一滴地往下滴水，鼻尖凍得有一點紅。","id":"1ue86mz","ln":274},{"t":"say","k":"i","text":"（……好近。）","id":"1cc7yil","ln":276},{"t":"say","k":"n","text":"我聽見自己的心跳。比雨聲還吵。","id":"1f4t4xe","ln":278},{"t":"choice","title":"選擇⑤","options":[{"key":"A","text":"吻她","to":"3-3A","eff":[{"s":"心動","d":1}]},{"key":"B","text":"輕聲唱歌給她聽","to":"3-3B","eff":[{"s":"心動","d":2}]}],"ln":280},{"t":"label","id":"3-3A","title":"唇","ln":284},{"t":"say","k":"n","text":"我不知道是誰先靠近的。也許是我。","id":"hj4wbj","ln":286},{"t":"se","names":["short-kiss"],"ln":288},{"t":"say","k":"n","text":"我只知道，等我回過神來，我的嘴唇已經碰到了她的。","id":"1my6gyi","ln":290},{"t":"say","k":"n","text":"但是跟那天在沙灘上不一樣。那天是救人，今天不是。","id":"g1tyu7","ln":292},{"t":"say","k":"n","text":"她僵了一下。","id":"feaupq","ln":294},{"t":"say","k":"n","text":"然後，她伸手抓住了我的衣領——跟那天一模一樣的動作——我被拉得更近。","id":"fi6pci","ln":296},{"t":"jump","to":"3-4","ln":298},{"t":"label","id":"3-3B","title":"歌","ln":300},{"t":"say","k":"n","text":"我沒有吻她。","id":"1c55hjr","ln":302},{"t":"say","k":"n","text":"我只是把額頭輕輕靠在她的額頭上，閉上眼睛，很小聲地哼起奶奶的漁歌。","id":"11isi4x","ln":304},{"t":"say","k":"d","who":"孫承完","text":"「♪ 月亮落進海裡頭——」","ln":306,"id":"1ppt7ce"},{"t":"say","k":"n","text":"我感覺到她的呼吸停了一下。","id":"1alzamb","ln":308},{"t":"say","k":"d","who":"孫承完","text":"「♪ 潮水把歌帶著走——」","ln":310,"id":"1rey8y1"},{"t":"say","k":"n","text":"她的手抓住了我的衣角。抓得很緊。","id":"8ibzjx","ln":312},{"t":"say","k":"d","who":"孫承完","text":"「♪ 海裡的姑娘別哭泣——」","ln":314,"id":"8j6j04"},{"t":"say","k":"n","text":"她在發抖。","id":"i0vtdy","ln":316},{"t":"say","k":"d","who":"孫承完","text":"「♪ 我的歌，給妳——」","ln":318,"id":"1dvum0u"},{"t":"say","k":"n","text":"最後一個字，我沒能唱完。","id":"1mk8b0e","ln":320},{"t":"say","k":"n","text":"因為她吻了上來。","id":"1krh1t9","ln":322},{"t":"jump","to":"3-4","ln":324},{"t":"label","id":"3-4","title":"雨夜之吻","ln":326},{"t":"cg","id":"06","title":"雨夜之吻","ln":328},{"t":"say","k":"n","text":"她的嘴唇是涼的。","id":"hzhn5a","ln":330},{"t":"say","k":"n","text":"涼得像海水，可是嚐起來不鹹。是雨的味道，淡淡的、甜甜的。","id":"1udclyn","ln":332},{"t":"se","names":["long-kiss","breath"],"delays":[0,1.2],"ln":334},{"t":"say","k":"n","text":"她吻得很生疏，又很急，像一個第一次學游泳的人，不知道該怎麼換氣，只知道緊緊抓著唯一能抓住的東西。","id":"1ir7dw4","ln":336},{"t":"say","k":"n","text":"不知道為什麼，她的吻有種掠奪的感覺，但是我並不討厭。她的手從我的衣領滑到後頸，冰冷的指尖讓我整個人都顫了一下。","id":"j5nc91","ln":338},{"t":"say","k":"n","text":"我的手撫上她的腰，將身體也貼近她。她的心跳隔著衣物傳過來，很快、很亂，跟我一樣。","id":"wbunx0","ln":340},{"t":"say","k":"n","text":"雨打在鐵皮屋頂上，像一千面鼓。","id":"19aalnh","ln":342},{"t":"say","k":"n","text":"她的頭髮散在我的手臂上，冰涼地纏著。我輕輕吻她的嘴角，一點一點地，想把自己的體溫分給她。","id":"54lzib","ln":344},{"t":"se","names":["breath"],"ln":346},{"t":"say","k":"n","text":"她發出一聲很輕很輕的聲音。似嘆息，又似祈禱。","id":"1xj0kd3","ln":348},{"t":"say","k":"n","text":"像不想放過任何一處能感覺到的柔軟，我們的唇不斷碰觸又分開，直到發麻。","id":"15eazi5","ln":350},{"t":"say","k":"n","text":"她傾身，指腹滑入我的髮縫，將我的頭抬托起，從我的額頭、眉心，再吻到鼻尖，我能感受她的鼻息撫過我臉上的每寸細毛，柔得讓人發暈。","id":"1d6lpn2","ln":352},{"t":"say","k":"n","text":"將唇再次覆上我的唇時，她停止了溫柔的動作，呼吸和在我髮中的手都越來越重，她一下咬住我的上唇，用舌頭撬過我的齒間，交纏。一切行雲流水，我渾身發軟，甚至找不到時間換氣，感覺自己真的要把甚麼給她了，而且我願意給她。","id":"1r9cy6q","ln":354},{"t":"if","cond":[[{"s":"心動","op":"<","v":3}]],"to":"3-4B","ln":356},{"t":"jump","to":"3-4A","ln":357},{"t":"label","id":"3-4A","title":"苦","ln":359},{"t":"say","k":"n","text":"然後，她停住了。","id":"vjyh9n","ln":361},{"t":"say","k":"n","text":"她猛地往後退，退到長椅的另一端，用手摀著自己的嘴。","id":"w53aav","ln":363},{"t":"cgEnd","ln":365},{"t":"show","list":[{"c":"裴柱現","e":"驚慌"}],"ln":366},{"t":"say","k":"d","who":"孫承完","text":"「……柱現姐姐？」","ln":368,"expr":"驚訝","id":"1hwinlw"},{"t":"say","k":"n","text":"她看著我，眼睛睜得很大。那個表情很奇怪，不是生氣，不是害羞，是……驚恐。像發現了什麼不得了的事。","id":"prpb36","ln":370},{"t":"say","k":"d","who":"裴柱現","text":"「……苦的。」","ln":372,"id":"1vvvcwx"},{"t":"say","k":"d","who":"孫承完","text":"「什麼？」","ln":374,"id":"r35xo3"},{"t":"say","k":"d","who":"裴柱現","text":"「……沒事。」","ln":376,"expr":"難過","id":"1ixs2u0"},{"t":"say","k":"n","text":"她放下手。過了很久，她慢慢挪回來，把額頭靠在我的肩膀上。","id":"r3e5ri","ln":378},{"t":"say","k":"n","text":"她在發抖。","id":"hqw7oz","ln":380},{"t":"say","k":"d","who":"裴柱現","text":"「孫承完。」","ln":382,"id":"n707to"},{"t":"say","k":"d","who":"孫承完","text":"「嗯。」","ln":384,"id":"4gduzx"},{"t":"say","k":"d","who":"裴柱現","text":"「……我完了。」","ln":386,"id":"1c7j1tu"},{"t":"say","k":"n","text":"我不懂她在說什麼。我只是攬著她，聽著外面的雨，一直到雨停。","id":"1w50vki","ln":388},{"t":"say","k":"n","text":"那天晚上，她一句話都沒有再說。可是她一直沒有放開我的手。","id":"10ga7oq","ln":390},{"t":"jump","to":"3-5A","ln":392},{"t":"label","id":"3-4B","title":"潮汐","ln":394},{"t":"say","k":"n","text":"然後，我感覺到了。","id":"kz32ml","ln":396},{"t":"say","k":"n","text":"有什麼東西，在從我身體裡流出去。","id":"q4dec5","ln":398},{"t":"say","k":"n","text":"從胸口，經過喉嚨，經過嘴唇，流進她的嘴裡。暖暖的，像潮水退去時從腳邊抽走的沙。","id":"k8z3xi","ln":400},{"t":"say","k":"i","text":"（……好奇怪。）","id":"42jtrp","ln":402},{"t":"say","k":"n","text":"我應該要害怕的。可是我不怕。","id":"1pa1rmp","ln":404},{"t":"say","k":"n","text":"那種感覺太舒服了。像躺在被曬得恰好的海面上，被浪一下一下地推著、晃著。我的頭好暈，眼前的燈光開始旋轉，可是我一點都不想醒來。","id":"7vkgrv","ln":406},{"t":"say","k":"n","text":"她的手捧著我的臉。她的眼睛睜開了，那雙深褐色的眼睛深處，有一點點的光，像深海裡的什麼東西。","id":"ul2cc","ln":408},{"t":"say","k":"n","text":"我好像聽見了歌聲。","id":"156mf7w","ln":410},{"t":"say","k":"n","text":"不，不是歌。是哼唱。沒有歌詞，也沒有旋律，只是一個很低、很美的聲音，在我的腦子裡一圈一圈地繞，繞得我什麼都想不起來。","id":"1eptedn","ln":412},{"t":"say","k":"i","text":"（姐姐……）","id":"1uqxnsd","ln":414},{"t":"say","k":"n","text":"我想叫她。可是我發不出聲音。","id":"tmj4ee","ln":416},{"t":"trans","kind":"out","ln":418},{"t":"cgEnd","ln":419},{"t":"say","k":"n","text":"……","id":"1a5b9vf","ln":421},{"t":"se","names":["海浪"],"ln":423},{"t":"bg","name":"救生站小屋・清晨","ln":424},{"t":"trans","kind":"in","ln":425},{"t":"say","k":"n","text":"我醒來的時候，雨已經停了。","id":"dgvpuk","ln":427},{"t":"say","k":"n","text":"我躺在長椅上，身上蓋著那條毛巾。屋裡只有我一個人。","id":"1mdicrz","ln":429},{"t":"say","k":"n","text":"窗外的天是灰白色的。便當盒放在置物櫃上，蓋子蓋得好好的。","id":"11251pn","ln":431},{"t":"say","k":"n","text":"我坐起來，整個世界晃了一下。","id":"4hxp88","ln":433},{"t":"say","k":"i","text":"（……我怎麼睡著的？）","id":"zwfwd5","ln":435},{"t":"say","k":"n","text":"我想不起來。我只記得那個吻，還有那個在腦子裡繞個不停的聲音。","id":"gqcebd","ln":437},{"t":"say","k":"n","text":"我的嘴唇好冷。","id":"1uxoqfz","ln":439},{"t":"stat","list":[{"s":"採息","d":1}],"ln":441},{"t":"flag","names":["雨夜採息"],"ln":442},{"t":"jump","to":"3-5B","ln":443},{"t":"label","id":"3-5A","title":"便當","ln":445},{"t":"hide","all":true,"ln":447},{"t":"bg","name":"救生站・白天","ln":448},{"t":"bgm","name":"白鹽灣日常","ln":449},{"t":"say","k":"n","text":"隔天，柱現姐姐沒有來「退潮」上班。","id":"1l3spoa","ln":451},{"t":"say","k":"n","text":"阿英說她請了病假。我想著要傳什麼訊息關心她，——後來我才想到，她根本沒有手機。","id":"x7dmvp","ln":453},{"t":"say","k":"n","text":"第三天中午，我坐在瞭望台上吃麵包的時候，有人在下面清了清喉嚨。","id":"l70j0k","ln":455},{"t":"show","list":[{"c":"裴柱現","e":"害羞"}],"ln":457},{"t":"say","k":"n","text":"姐姐站在瞭望台底下，手上抱著一個便當盒，臉轉向旁邊，假裝在看海鷗。","id":"maug8y","ln":459},{"t":"say","k":"d","who":"裴柱現","text":"「……今天的有煮熟。」","ln":461,"id":"1b1qxoq"},{"t":"say","k":"d","who":"孫承完","text":"「……謝謝姐姐。」","ln":463,"expr":"笑","id":"1n5tpud"},{"t":"say","k":"n","text":"她把便當盒放在梯子上，轉身就要走。走了兩步，又停下來。","id":"1974i77","ln":465},{"t":"say","k":"d","who":"裴柱現","text":"「孫承完。」","ln":467,"id":"ngztin"},{"t":"say","k":"d","who":"孫承完","text":"「嗯？」","ln":469,"id":"1o4wvzk"},{"t":"say","k":"d","who":"裴柱現","text":"「那天……」","ln":471,"id":"1ccwr9l"},{"t":"say","k":"n","text":"她停了很久。耳朵紅得像煮熟的蝦。","id":"p9kjd5","ln":473},{"t":"say","k":"d","who":"裴柱現","text":"「……那天的雨，很甜。」","ln":475,"id":"qd7rhb"},{"t":"say","k":"n","text":"說完，她就跑了。跑得比第一天還歪歪扭扭。","id":"1mczjbb","ln":477},{"t":"say","k":"n","text":"我打開便當盒。這次是烤過頭的魚，焦了一半，旁邊的海苔愛心依然是胖胖歪歪的。","id":"2adqyb","ln":479},{"t":"say","k":"n","text":"她包包裡的寄居蟹探出頭來，朝我這邊看了一眼，好像在嘆氣。","id":"14f4n49","ln":481},{"t":"jump","to":"3-6","ln":483},{"t":"label","id":"3-5B","title":"白髮","ln":485},{"t":"hide","all":true,"ln":487},{"t":"bg","name":"孫承完的房間・白天","ln":488},{"t":"bgm","name":"夜","ln":489},{"t":"say","k":"n","text":"那天之後，我發燒了。","id":"vkqkdx","ln":491},{"t":"say","k":"n","text":"燒得不高，可是一直退不下去。我已經很久沒有感冒，全身沒有力氣，只能躺在床上看天花板，一整天都昏昏欲睡。","id":"kfiqrt","ln":493},{"t":"say","k":"n","text":"阿英帶著一鍋粥來看我，還有康託她帶來的一大袋零食。袋子已經被打開過了，看得出來內容物少了一些。","id":"1pr8mgl","ln":495},{"t":"show","list":[{"c":"阿英","e":"擔心"}],"ln":497},{"t":"say","k":"d","who":"阿英","text":"「……妳臉色好差。」","ln":499,"id":"93mish"},{"t":"say","k":"d","who":"孫承完","text":"「只是淋到雨啦。」","ln":501,"id":"1uay8eg"},{"t":"say","k":"n","text":"阿英沒說話。她坐在床邊，盯著我看了很久，然後伸手撥開我額前的頭髮。","id":"1v1u2cn","ln":503},{"t":"say","k":"n","text":"她的手停住了。","id":"65ujzy","ln":505},{"t":"say","k":"d","who":"阿英","text":"「承完。」","ln":507,"expr":"認真","id":"k2srth"},{"t":"say","k":"d","who":"孫承完","text":"「嗯？」","ln":509,"id":"1oyvp2h"},{"t":"say","k":"d","who":"阿英","text":"「妳有白頭髮了。」","ln":511,"id":"1tgnork"},{"t":"say","k":"n","text":"她從我的瀏海裡挑出一根頭髮，舉到我眼前。","id":"1e0t22g","ln":513},{"t":"say","k":"n","text":"是白的。從髮根到髮尾，整根都是白的。像被漂白過的死白。","id":"zhq9ot","ln":515},{"t":"say","k":"n","text":"我才三十二歲！","id":"1pnhbus","ln":517},{"t":"say","k":"d","who":"阿英","text":"「妳那天晚上，跟她在一起對不對。」","ln":519,"expr":"擔心","id":"wk2vyf"},{"t":"say","k":"n","text":"我沒有回答。","id":"2aq81l","ln":521},{"t":"say","k":"d","who":"阿英","text":"「失魂、發燒、沒力氣、一夜之間長白頭髮。」","ln":523,"id":"8aw5pz"},{"t":"say","k":"n","text":"她一個字一個字地說。","id":"srefpm","ln":525},{"t":"say","k":"d","who":"阿英","text":"「……承完，跟我阿嬤講的一模一樣。」","ln":527,"id":"13njzfb"},{"t":"say","k":"d","who":"孫承完","text":"「阿英，那是傳說，我只是太累。」","ln":529,"id":"baimpk"},{"t":"say","k":"d","who":"阿英","text":"「我知道。」","ln":531,"id":"hpyaur"},{"t":"say","k":"n","text":"她把那根白頭髮放在床頭櫃上，木頭的深襯的它像在發光。","id":"pjy73s","ln":533},{"t":"say","k":"d","who":"阿英","text":"「所以我才害怕。」","ln":535,"id":"1s7qygz"},{"t":"hide","list":["阿英"],"ln":537},{"t":"say","k":"n","text":"阿英走了之後，我一個人躺在床上。","id":"pkh6za","ln":539},{"t":"say","k":"n","text":"傍晚的時候，我聽見門外有腳步聲。很輕，停在我的門口。","id":"8s41pi","ln":541},{"t":"say","k":"n","text":"停了很久。","id":"8umo0","ln":543},{"t":"say","k":"n","text":"我等著敲門聲。可是沒有。","id":"1dehie7","ln":545},{"t":"say","k":"n","text":"過了一會兒，腳步聲又慢慢走遠了。","id":"11qsg6","ln":547},{"t":"say","k":"n","text":"我撐著身體走到門口，打開門。外面沒有人。","id":"2z0dn2","ln":549},{"t":"say","k":"n","text":"只有門口的地上，放著一個便當盒。","id":"1r4o52e","ln":551},{"t":"say","k":"n","text":"裡面是一條烤得很漂亮的魚，旁邊用海苔排了一個很工整的愛心。","id":"djn54l","ln":553},{"t":"say","k":"n","text":"這次一點都沒有歪。","id":"13e2xkz","ln":555},{"t":"jump","to":"3-6","ln":557},{"t":"label","id":"3-6","title":"邀請","ln":559},{"t":"hide","all":true,"ln":561},{"t":"bg","name":"酒吧「退潮」・夜","ln":562},{"t":"bgm","name":"白鹽灣日常","ln":563},{"t":"say","k":"n","text":"幾天後，漁會的陳伯親自來「退潮」找我。","id":"1u6ki8","ln":565},{"t":"show","list":[{"c":"陳伯","e":"普通"}],"ln":567},{"t":"say","k":"d","who":"陳伯","text":"「承完啊，春潮祭的事，妳考慮得怎麼樣？」","ln":569,"id":"1i6ybaf"},{"t":"say","k":"d","who":"孫承完","text":"「……陳伯，我真的唱得不好。」","ln":571,"id":"r8fum2"},{"t":"say","k":"d","who":"陳伯","text":"「妳阿嬤以前也這樣講。結果每年都唱到全鎮的人掉眼淚。」","ln":573,"id":"mbbwbs"},{"t":"say","k":"n","text":"他拍拍我的肩。","id":"1io3vvr","ln":575},{"t":"say","k":"d","who":"陳伯","text":"「那首歌啊，是要有人唱的。沒有人唱，海會寂寞。」","ln":577,"id":"1ggpfo5"},{"t":"say","k":"n","text":"我還沒回答，就聽見吧檯那邊傳來「鏘」的一聲。","id":"uwpbo6","ln":579},{"t":"show","list":[{"c":"裴柱現","e":"普通"}],"ln":581},{"t":"say","k":"n","text":"姐姐手上的托盤掉在吧檯上。她站在那裡，看著我和陳伯，臉色很奇怪。","id":"1gpj9m0","ln":583},{"t":"say","k":"d","who":"裴柱現","text":"「……春潮祭？」","ln":585,"id":"1dj9wi0"},{"t":"say","k":"d","who":"陳伯","text":"「對啊，下禮拜春分，全鎮一起對著海唱歌。承完要上台唱開場喔。」","ln":587,"id":"za0h68"},{"t":"say","k":"n","text":"姐姐看著我。","id":"1q6ubz2","ln":589},{"t":"say","k":"n","text":"那個眼神裡有很多東西。驚訝、害怕，還有一點點……我看不懂的、很深很深的渴望。","id":"10yqntd","ln":591},{"t":"say","k":"d","who":"裴柱現","text":"「……妳要唱給海聽？」","ln":593,"id":"144hroh"},{"t":"say","k":"d","who":"孫承完","text":"「嗯。可能吧。」","ln":595,"id":"1fl4k96"},{"t":"say","k":"n","text":"她沒有再說話，撿起托盤，轉身走進廚房。","id":"8iz9ga","ln":597},{"t":"say","k":"n","text":"我看見她包包裡的寄居蟹，從頭到尾一直盯著陳伯，一動也不動。","id":"1lg1crz","ln":599},{"t":"say","k":"n","text":"像是聽見了一句，很久很久以前聽過的話。","id":"1505wa6","ln":601},{"t":"chend","text":"第三章　完","ln":603}]},{"key":"04_第四章_春潮祭","name":"04_第四章_春潮祭.md","route":"main","num":4,"title":"第四章　春潮祭","ops":[{"t":"title","text":"第四章　春潮祭","card":true,"ln":1},{"t":"label","id":"4-1","title":"祭典","ln":3},{"t":"bg","name":"堤防祭典・黃昏","ln":5},{"t":"bgm","name":"白鹽灣日常","ln":6},{"t":"se","names":["人群"],"ln":7},{"t":"say","k":"n","text":"三月二十日，春分。","id":"1pg2sm8","ln":9},{"t":"say","k":"n","text":"從下午開始，堤防上就擺滿了攤子。烤魷魚、炸蝦餅、棉花糖，還有彈珠汽水。一串一串的紙燈籠從燈塔一路掛到漁港，風一吹，讓整條堤防看起來都在輕輕搖晃。","id":"26jd5j","ln":11},{"t":"say","k":"n","text":"我站在後台的帳篷邊，手心全是汗。","id":"qxqscu","ln":13},{"t":"say","k":"d","who":"裴柱現","text":"「孫承完。」","ln":15,"id":"1xr0zta"},{"t":"show","list":[{"c":"裴柱現","e":"笑"}],"ln":17},{"t":"say","k":"n","text":"我回過頭，然後呆住了。","id":"wkpb8p","ln":19},{"t":"say","k":"n","text":"姐姐穿著阿英借她的祭典長衫，深藍色的布料上印著白色的浪花，腰帶綁得歪歪的。頭髮盤起來，插著一根珍珠髮簪，露出一截白得發光的後頸。","id":"1dukzx4","ln":21},{"t":"say","k":"n","text":"周圍至少有五個人停下了腳步。一個賣棉花糖的大叔，手上的棉花糖捲成了一顆球都沒發現。","id":"wfvjsu","ln":23},{"t":"say","k":"d","who":"裴柱現","text":"「怎麼樣。」","ln":25,"expr":"得意","id":"jeeru3"},{"t":"say","k":"d","who":"孫承完","text":"「……很好看。」","ln":27,"expr":"害羞","id":"18ay45j"},{"t":"say","k":"d","who":"裴柱現","text":"「只是『很好看』？」","ln":29,"id":"1v6bjrj"},{"t":"say","k":"d","who":"孫承完","text":"「……非常好看。」","ln":31,"id":"10esb6h"},{"t":"say","k":"d","who":"裴柱現","text":"「准了。」","ln":33,"id":"tqorlq"},{"t":"say","k":"n","text":"她伸手，把我的手拉過去，塞了一串東西進來。","id":"knd5cc","ln":35},{"t":"say","k":"d","who":"裴柱現","text":"「給妳。這個叫做『雲』。妳們人……妳們把雲抓下來，插在棍子上賣。」","ln":37,"id":"1atljuh"},{"t":"say","k":"d","who":"孫承完","text":"「那是棉花糖啦。」","ln":39,"expr":"笑","id":"1l4whor"},{"t":"say","k":"d","who":"裴柱現","text":"「我知道。我在說笑話。」","ln":41,"expr":"普通","id":"lv0dsq"},{"t":"say","k":"i","text":"（……她絕對不知道。）","id":"v9ypks","ln":43},{"t":"if","cond":[[{"s":"採息","op":">=","v":1}]],"to":"4-1B","ln":45},{"t":"jump","to":"4-2","ln":46},{"t":"label","id":"4-1B","title":"白髮","ln":48},{"t":"say","k":"n","text":"她拉著我往攤子那邊走。走了幾步，她突然停下來。","id":"aowqut","ln":50},{"t":"say","k":"n","text":"她伸手，撥開我耳邊的頭髮。","id":"gko3fd","ln":52},{"t":"say","k":"n","text":"那裡有兩根白頭髮。我早上照鏡子的時候看到了，沒有拔，想說反正沒人會注意。","id":"kazsfp","ln":54},{"t":"say","k":"n","text":"她的手指停在那裡，很久都沒有動。","id":"hsizx5","ln":56},{"t":"show","list":[{"c":"裴柱現","e":"難過"}],"ln":58},{"t":"say","k":"d","who":"裴柱現","text":"「……對不起。」","ln":60,"id":"6qnm1v"},{"t":"say","k":"d","who":"孫承完","text":"「為什麼要道歉？」","ln":62,"id":"8npmnr"},{"t":"say","k":"n","text":"她沉默了一下。","id":"1jyzduv","ln":64},{"t":"say","k":"d","who":"裴柱現","text":"「……我剛剛踩到妳的腳了。」","ln":66,"expr":"普通","id":"5ucm6q"},{"t":"say","k":"n","text":"她沒有踩到。","id":"1uks0qd","ln":68},{"t":"say","k":"n","text":"但我沒有拆穿她。","id":"1pxg01e","ln":70},{"t":"jump","to":"4-2","ln":72},{"t":"label","id":"4-2","title":"銀髮的女人","ln":74},{"t":"show","list":[{"c":"裴柱現","e":"普通"}],"ln":76},{"t":"say","k":"n","text":"我們在攤子之間慢慢走。","id":"tlmvg8","ln":78},{"t":"say","k":"n","text":"姐姐在烤魷魚的攤子前面站了很久，表情很掙扎。","id":"1brzv9q","ln":80},{"t":"say","k":"d","who":"裴柱現","text":"「牠們是很討厭的鄰居。」","ln":82,"id":"qkcd6c"},{"t":"say","k":"d","who":"孫承完","text":"「……妳在說魷魚嗎？」","ln":84,"id":"t3gr7i"},{"t":"say","k":"d","who":"裴柱現","text":"「牠們喜歡亂噴墨。很沒禮貌。」","ln":86,"id":"1aa88l2"},{"t":"say","k":"n","text":"她還是買了三串，吃得非常開心。","id":"1o9hdvq","ln":88},{"t":"say","k":"n","text":"隔壁攤的康嘴裡咬著炸蝦餅，朝我們拼命揮手，然後又轉回去，把剛買的一杯冰沙小心翼翼地端給正在顧攤的阿英。","id":"13vhsap","ln":90},{"t":"say","k":"n","text":"人越來越多。走到撈金魚的攤子前面時，我被人群擠了一下，肩膀撞上了一個人。","id":"1twc13r","ln":92},{"t":"say","k":"d","who":"孫承完","text":"「啊，對不起——」","ln":94,"id":"17bgciq"},{"t":"show","list":[{"c":"澪","e":"普通"}],"ln":96},{"t":"say","k":"n","text":"我抬起頭，然後愣住了。","id":"1xpwjl1","ln":98},{"t":"say","k":"n","text":"那是一個女人。銀白色的長髮直直地垂到腰際，皮膚白得透明，五官跟柱現姐姐像得驚人。可是姐姐的美是溫的、是會笑的，她的美是冷的，像冬天的月亮照在冰上。","id":"1vp0otq","ln":100},{"t":"say","k":"n","text":"她低下頭看我。那個眼神，像在看一條擺在攤子上的魚。","id":"1aa6rou","ln":102},{"t":"say","k":"d","who":"？？？","text":"「……就是妳。」","ln":104,"id":"b95vpp"},{"t":"say","k":"d","who":"孫承完","text":"「什麼？」","ln":106,"id":"1td1az2"},{"t":"say","k":"n","text":"她把我從頭到腳看了一遍。","id":"15gqdfc","ln":108},{"t":"show","list":[{"c":"澪","e":"冷笑"}],"ln":110},{"t":"say","k":"d","who":"？？？","text":"「陸果。」","ln":112,"id":"2p1dki"},{"t":"say","k":"n","text":"她說完就走了。銀色的頭髮在燈籠的光裡一閃，消失在人群裡。","id":"gua72g","ln":114},{"t":"hide","list":["澪"],"ln":116},{"t":"say","k":"i","text":"（……ㄌㄨˋㄍㄨㄛˇ？什麼意思？）","id":"7e32xq","ln":118},{"t":"say","k":"n","text":"我轉過頭，想問姐姐有沒有看到。","id":"1oa4y8w","ln":120},{"t":"show","list":[{"c":"裴柱現","e":"驚慌"}],"ln":122},{"t":"say","k":"n","text":"姐姐的臉色白得像紙。","id":"1q5m7nh","ln":124},{"t":"say","k":"n","text":"她盯著那個女人消失的方向，手上的烤魷魚掉在地上。她包包裡的寄居蟹鑽個縮進殼裡。","id":"h5as9h","ln":126},{"t":"say","k":"d","who":"孫承完","text":"「姐姐？妳認識她嗎？」","ln":128,"id":"1jbii0y"},{"t":"say","k":"d","who":"裴柱現","text":"「……不認識。」","ln":130,"expr":"普通","id":"pbse2i"},{"t":"say","k":"n","text":"她說謊的時候，總是會往右邊看。","id":"10771et","ln":132},{"t":"say","k":"n","text":"像現在。","id":"150s2cd","ln":134},{"t":"say","k":"d","who":"裴柱現","text":"「孫承完，快開始了。妳該去後台了。」","ln":136,"id":"16sey1l"},{"t":"hide","all":true,"ln":138},{"t":"label","id":"4-3","title":"開場","ln":140},{"t":"bg","name":"春潮祭舞台・夜","ln":142},{"t":"bgm","stop":"stop","ln":143},{"t":"se","names":["人群"],"ln":144},{"t":"say","k":"n","text":"舞台搭在堤防的最前端，背對著海。","id":"dmt9z2","ln":146},{"t":"say","k":"n","text":"我站在台上，看著底下黑壓壓的人群。全鎮的人都來了。漁會的陳伯坐在第一排，康在後面揮著手，另一隻手還拿著烤玉米，阿英抱著手臂站在角落。","id":"jj20ck","ln":148},{"t":"say","k":"n","text":"還有柱現姐姐。","id":"1pwfjd4","ln":150},{"t":"say","k":"n","text":"她站在人群的最後面，靠近海的那一邊。燈籠的光照不到她，可是我還是一眼就找到她了。","id":"1mmrzvn","ln":152},{"t":"say","k":"n","text":"她在看我。跟那天晚上，在浪裡的時候一樣。","id":"rpc3iv","ln":154},{"t":"say","k":"n","text":"我抱著吉他，深吸一口氣。","id":"irg1wr","ln":156},{"t":"choice","title":"選擇⑥","options":[{"key":"A","text":"唱奶奶的漁歌","to":"4-3A","eff":[{"s":"心動","d":2}]},{"key":"B","text":"唱一首流行歌","to":"4-3B"}],"ln":158},{"t":"label","id":"4-3A","title":"潮約之歌","ln":162},{"t":"se","names":["撥和弦"],"ln":164},{"t":"say","k":"n","text":"我撥下第一個和弦。","id":"s6j6l6","ln":166},{"t":"bgm","name":"營火之歌","ln":168},{"t":"cg","id":"07","title":"春潮祭舞台","ln":169},{"t":"say","k":"d","who":"孫承完","text":"「♪ 月亮落進海裡頭——潮水把歌帶著走——」","ln":171,"id":"1jsirb8"},{"t":"say","k":"n","text":"人群安靜下來了。","id":"1qgvv6g","ln":173},{"t":"say","k":"d","who":"孫承完","text":"「♪ 海裡的姑娘別哭泣——我的歌，給妳留——」","ln":175,"id":"11o6v1k"},{"t":"say","k":"n","text":"這首歌還有第二段。只有奶奶教過我，我從來沒在別人面前唱過。","id":"113jox2","ln":177},{"t":"say","k":"n","text":"奶奶說，第二段是唱給「真的在聽的人」的。","id":"mm3fik","ln":179},{"t":"say","k":"d","who":"孫承完","text":"「♪ 船兒出海莫回頭——浪花替我牽妳手——」","ln":181,"id":"1658u7d"},{"t":"say","k":"d","who":"孫承完","text":"「♪ 等到潮水回來時——我走進海裡，換妳唱——」","ln":183,"id":"9wr2z4"},{"t":"say","k":"n","text":"第一排的陳伯閉上了眼睛。人群裡有幾個老人家，跟著輕輕哼了起來。然後越來越多人跟著唱，從舞台前面一路往後傳，像漲潮一樣。","id":"1yjpa95","ln":185},{"t":"say","k":"n","text":"就在這時候，有人驚呼了一聲。","id":"17lwvcu","ln":187},{"t":"say","k":"n","text":"舞台後面的海，在發光。","id":"13o2umq","ln":189},{"t":"say","k":"n","text":"一開始只是浪花的邊緣泛著一點點藍。然後整片海灣都亮起來了，淡藍色的光從水底浮上來，隨著歌聲一明一滅，像在呼吸。","id":"s2c7sw","ln":191},{"t":"say","k":"n","text":"全鎮的人都轉過頭去看。","id":"atnw9r","ln":193},{"t":"say","k":"n","text":"只有我沒有。","id":"bvjwpb","ln":195},{"t":"say","k":"n","text":"我在看人群最後面的姐姐。","id":"1cf25lq","ln":197},{"t":"say","k":"n","text":"她的眼眶紅透了。她用手摀著嘴，整個人在發抖。可是跟以前每一次一樣，一滴眼淚都沒有掉下來。","id":"1uweqth","ln":199},{"t":"say","k":"n","text":"她肩膀上的寄居蟹，高高地舉起了兩隻鉗子。像是在向誰致意。","id":"11x3kcp","ln":201},{"t":"say","k":"n","text":"最後一個音落下的時候，海上的光，慢慢暗了下去。","id":"1hkdyyq","ln":203},{"t":"cgEnd","ln":205},{"t":"jump","to":"4-4","ln":207},{"t":"label","id":"4-3B","title":"流行歌","ln":209},{"t":"se","names":["刷和弦"],"ln":211},{"t":"say","k":"n","text":"我唱了一首最近很紅的情歌。","id":"1q1dqq5","ln":213},{"t":"say","k":"n","text":"輕快、好記，副歌大家都會唱。台下的年輕人跟著拍手，康在後面跟著跳，跳到一半被阿英拉住，因為她手上的炒麵差點飛出去。","id":"4fi4n4","ln":215},{"t":"say","k":"n","text":"唱完之後，掌聲很熱烈。陳伯也在鼓掌，可是他的表情有一點點失望。","id":"1ga1epl","ln":217},{"t":"say","k":"n","text":"接著，按照慣例，全鎮的人一起對著海唱那首漁歌。沒有人帶，大家唱得零零落落，很多人只記得第一句。","id":"ph6jl","ln":219},{"t":"say","k":"n","text":"我在台上，看向人群最後面的姐姐。","id":"sepao3","ln":221},{"t":"say","k":"n","text":"她很專心地在聽。聽著全鎮的人跟著亂唱的漁歌，表情很溫柔，又有一點點寂寞。","id":"1qmnbua","ln":223},{"t":"say","k":"n","text":"像在等一個沒有赴約的人。","id":"1ey4fj8","ln":225},{"t":"jump","to":"4-4","ln":227},{"t":"label","id":"4-4","title":"浪","ln":229},{"t":"bg","name":"堤防祭典・夜","ln":231},{"t":"bgm","name":"緊張","ln":232},{"t":"say","k":"n","text":"歌唱完，我從舞台上走下來，往人群後面擠，想去找姐姐。","id":"oxiq9","ln":234},{"t":"say","k":"n","text":"然後，海突然安靜了。","id":"1ce03b7","ln":236},{"t":"say","k":"n","text":"不是那種平靜的安靜。是浪聲突然消失了，像整片海屏住了呼吸。","id":"8huhan","ln":238},{"t":"se","names":["海浪"],"ln":240},{"t":"shake","ln":241},{"t":"say","k":"n","text":"一道浪從平靜的海面上直直地站了起來。","id":"5c6ym1","ln":243},{"t":"say","k":"n","text":"不大，可是很高。它不是朝整條堤防打過來的。它朝一個地方打過來——","id":"18lfxt5","ln":245},{"t":"say","k":"n","text":"姐姐站的那個地方。","id":"173gxig","ln":247},{"t":"say","k":"d","who":"孫承完","text":"「姐姐——！」","ln":249,"expr":"驚訝","id":"12ptrt0"},{"t":"trans","kind":"flash","ln":251},{"t":"se","names":["水花"],"ln":252},{"t":"say","k":"n","text":"浪打在堤防上，碎成一大片白色的水花。周圍的人尖叫著往後退。","id":"1eawq8m","ln":254},{"t":"say","k":"n","text":"我衝過去的時候，姐姐全身都濕透了。","id":"5dfc08","ln":256},{"t":"say","k":"n","text":"海水從她的頭髮往下滴。她跌坐在地上，抱著自己的手臂，整個人縮成一團。","id":"6eaez0","ln":258},{"t":"show","list":[{"c":"裴柱現","e":"驚慌"}],"ln":260},{"t":"say","k":"d","who":"孫承完","text":"「妳有沒有受傷？讓我看——」","ln":262,"id":"wbx9hy"},{"t":"say","k":"d","who":"裴柱現","text":"「不要看！」","ln":264,"id":"2ki85s"},{"t":"say","k":"n","text":"她把手臂藏到背後。可是我已經看到了。","id":"xmgdsc","ln":266},{"t":"say","k":"n","text":"在燈籠的光裡，她的手臂上有東西在發亮。","id":"16o2eed","ln":268},{"t":"say","k":"n","text":"一片、一片、又一片。","id":"gsms33","ln":270},{"t":"say","k":"n","text":"我抬起頭。堤防的盡頭，那個銀髮的女人站在那裡，全身乾乾的，一滴水都沒沾到。","id":"xtq2sj","ln":272},{"t":"say","k":"n","text":"她在笑。","id":"o24gyc","ln":274},{"t":"say","k":"n","text":"然後她轉過身，消失在黑暗裡。","id":"1gruvt7","ln":276},{"t":"say","k":"d","who":"裴柱現","text":"「孫承完……帶我走。」","ln":278,"id":"1vii9mr"},{"t":"say","k":"n","text":"姐姐抓著我的衣角，聲音在發抖。","id":"8p5kgv","ln":280},{"t":"say","k":"d","who":"裴柱現","text":"「拜託妳……帶我去沒有海水的地方。」","ln":282,"expr":"難過","id":"19b357t"},{"t":"label","id":"4-5","title":"鱗","ln":284},{"t":"hide","all":true,"ln":286},{"t":"trans","kind":"out","ln":287},{"t":"bg","name":"孫承完的房間・夜","ln":288},{"t":"trans","kind":"in","ln":289},{"t":"bgm","name":"夜","ln":290},{"t":"say","k":"n","text":"我家是燈塔旁邊那棟小屋。以前是看守燈塔的人住的，奶奶去世後就留給了我。","id":"a55xhc","ln":292},{"t":"say","k":"n","text":"我把姐姐帶進浴室，打開水龍頭。","id":"110o6r1","ln":294},{"t":"show","list":[{"c":"裴柱現","e":"難過"}],"ln":296},{"t":"say","k":"n","text":"她坐在浴缸邊緣，一直把手臂藏在身後。濕透的長裙一直在滴水，在地板上積成一小灘。","id":"zu9t24","ln":298},{"t":"say","k":"d","who":"孫承完","text":"「姐姐，手給我。要把海水沖掉。」","ln":300,"id":"ur1cyk"},{"t":"say","k":"n","text":"她看著我，咬著嘴唇。過了很久，她才慢慢地把手臂伸出來。","id":"18hsw0i","ln":302},{"t":"cg","id":"08","title":"手臂上的鱗片","ln":304},{"t":"say","k":"n","text":"從手肘到手腕，長滿了鱗片。","id":"omy6ob","ln":306},{"t":"say","k":"n","text":"湛藍色的，薄薄的，每一片都只有指甲那麼大，整整齊齊地排列著，像一件穿在皮膚上的鎧甲。浴室的燈光照上去，它們就閃出彩虹一樣的光，從深藍變成淺藍、從淺藍變成銀白。","id":"k5s9sf","ln":308},{"t":"say","k":"n","text":"好漂亮。","id":"1v8p8kd","ln":310},{"t":"say","k":"n","text":"這是我腦子裡冒出來的第一個念頭。不是可怕，不是奇怪。是好漂亮。","id":"n43fko","ln":312},{"t":"say","k":"n","text":"她在發抖。不是因為冷，是她在等我說些什麼。","id":"112t8up","ln":314},{"t":"choice","title":"選擇⑦","options":[{"key":"A","text":"不追問，只幫她沖水擦藥","to":"4-5A","eff":[{"s":"信任","d":2}]},{"key":"B","text":"問她到底怎麼了","to":"4-5B","eff":[{"s":"信任","d":-1}]}],"ln":316},{"t":"label","id":"4-5A","title":"不問","ln":320},{"t":"say","k":"n","text":"但我沒有說話。","id":"1otyopv","ln":322},{"t":"say","k":"n","text":"我只是把蓮蓬頭的水調到溫溫的，一隻手托著她的手臂，一隻手拿著蓮蓬頭，慢慢地沖。","id":"1kk2z7o","ln":324},{"t":"say","k":"n","text":"淡水流過那些鱗片的時候，它們就像退潮一樣，一片一片地變淡、變透明，最後沉回她的皮膚底下，只剩下一點點珍珠色的光。","id":"1kxdew3","ln":326},{"t":"say","k":"d","who":"孫承完","text":"「……會痛嗎？」","ln":328,"id":"i4md8u"},{"t":"say","k":"d","who":"裴柱現","text":"「……不會。」","ln":330,"expr":"普通","id":"16yelsm"},{"t":"say","k":"n","text":"我拿毛巾把她的手臂擦乾，從櫃子裡拿出乳液，一點一點地抹上去。","id":"6kjrwj","ln":332},{"t":"say","k":"n","text":"她一直看著我。","id":"8b6ae8","ln":334},{"t":"say","k":"d","who":"裴柱現","text":"「……妳不問嗎？」","ln":336,"id":"1y4gqle"},{"t":"say","k":"d","who":"孫承完","text":"「問什麼？」","ln":338,"id":"kyew3n"},{"t":"say","k":"d","who":"裴柱現","text":"「這個。我。所有的事。」","ln":340,"id":"tnhxof"},{"t":"say","k":"n","text":"我把乳液的蓋子蓋上。","id":"1ndo8n0","ln":342},{"t":"say","k":"d","who":"孫承完","text":"「妳想說的時候再說就好。」","ln":344,"id":"kal2p7"},{"t":"say","k":"n","text":"她看著我，嘴唇動了動，什麼也沒說出來。","id":"c475k4","ln":346},{"t":"say","k":"n","text":"她的眼眶又紅了。","id":"1gt0mi","ln":348},{"t":"cgEnd","ln":350},{"t":"jump","to":"4-6","ln":351},{"t":"label","id":"4-5B","title":"問","ln":353},{"t":"say","k":"d","who":"孫承完","text":"「姐姐……這是什麼？」","ln":355,"id":"1vmwr8i"},{"t":"say","k":"n","text":"她把手縮回去一點。","id":"1p6sk01","ln":357},{"t":"say","k":"d","who":"裴柱現","text":"「……過敏。」","ln":359,"expr":"普通","id":"jtvarh"},{"t":"say","k":"d","who":"孫承完","text":"「過敏？」","ln":361,"id":"18yix7d"},{"t":"say","k":"d","who":"裴柱現","text":"「海水過敏。很嚴重的那種。」","ln":363,"id":"81frui"},{"t":"say","k":"d","who":"孫承完","text":"「過敏會長得像鱗片嗎？」","ln":365,"id":"16adslv"},{"t":"say","k":"n","text":"她往右邊看。","id":"56mgwv","ln":367},{"t":"say","k":"d","who":"裴柱現","text":"「……會。」","ln":369,"id":"xbh8n9"},{"t":"say","k":"n","text":"我知道她在說謊。","id":"1ky238i","ln":371},{"t":"say","k":"n","text":"她也知道我知道。","id":"5uto2h","ln":373},{"t":"say","k":"n","text":"我沒有再問。我只是把蓮蓬頭打開，幫她把海水沖掉。淡水流過那些鱗片，它們一片一片變淡，沉回她的皮膚底下。","id":"1s8wufu","ln":375},{"t":"say","k":"n","text":"我們都沒有說話。浴室裡只有水聲。","id":"1qk9e7p","ln":377},{"t":"say","k":"n","text":"那種沉默，比任何一句謊話都讓我難受。","id":"542hoh","ln":379},{"t":"cgEnd","ln":381},{"t":"jump","to":"4-6","ln":382},{"t":"label","id":"4-6","title":"燈塔之夜","ln":384},{"t":"bg","name":"孫承完的房間・夜","ln":386},{"t":"bgm","name":"夜","ln":387},{"t":"say","k":"n","text":"姐姐換上了我的舊T恤和運動褲。對她來說太大了，袖子長得蓋住手指，她一直在捲袖子，捲了又滑下來。","id":"18i98cw","ln":389},{"t":"say","k":"n","text":"我們坐在床邊。窗外，燈塔的光一圈一圈地轉，每隔幾秒就掃過房間一次，把她的臉照亮，又暗下去。","id":"16tz4ot","ln":391},{"t":"if","cond":[[{"s":"心動","op":">=","v":6}]],"to":"4-6A","ln":393},{"t":"jump","to":"4-6B","ln":394},{"t":"label","id":"4-6A","title":"被愛的夜","ln":396},{"t":"show","list":[{"c":"裴柱現","e":"害羞"}],"ln":398},{"t":"say","k":"d","who":"裴柱現","text":"「孫承完。」","ln":400,"id":"1xh1e4b"},{"t":"say","k":"d","who":"孫承完","text":"「嗯？」","ln":402,"id":"12dr5vz"},{"t":"say","k":"d","who":"裴柱現","text":"「……唱歌給我聽。」","ln":404,"id":"1y7dopj"},{"t":"say","k":"d","who":"孫承完","text":"「現在？」","ln":406,"id":"1guymrw"},{"t":"say","k":"d","who":"裴柱現","text":"「只唱給我聽。」","ln":408,"id":"fto65b"},{"t":"say","k":"n","text":"我沒有拿吉他。我只是靠過去，在她耳邊很小聲地唱。唱奶奶的漁歌，唱那首很老的情歌，唱我想得起來的每一首歌。","id":"30qy5l","ln":410},{"t":"say","k":"n","text":"她閉著眼睛聽。燈塔的光掃過來，又掃過去。","id":"4jeral","ln":412},{"t":"say","k":"n","text":"唱到一半，她睜開眼睛。","id":"j1ayoo","ln":414},{"t":"say","k":"d","who":"裴柱現","text":"「妳的歌，是熱的。」","ln":416,"id":"13vzybl"},{"t":"say","k":"d","who":"孫承完","text":"「……熱的？」","ln":418,"id":"2nf2c3"},{"t":"say","k":"d","who":"裴柱現","text":"「嗯。像太陽曬過的沙。」","ln":420,"id":"1d06qpe"},{"t":"say","k":"n","text":"她伸手摸我的臉。她的手還是涼的，可是沒有那天在雨裡那麼冰了。","id":"1jqtkd8","ln":422},{"t":"say","k":"n","text":"然後她吻了我。","id":"1d0mawt","ln":424},{"t":"cg","id":"09","title":"燈塔之夜","ln":426},{"t":"say","k":"n","text":"這個吻跟雨夜的那個不一樣。很慢，很輕，像在確認什麼。","id":"177dd1f","ln":428},{"t":"say","k":"n","text":"她吻完我，額頭抵著我的額頭，很小聲地說：","id":"1baij29","ln":430},{"t":"say","k":"d","who":"裴柱現","text":"「……我從來沒有被誰這樣抱過。」","ln":432,"expr":"害羞","id":"1m1h0l6"},{"t":"say","k":"d","who":"孫承完","text":"「……三十五歲了也沒有？」","ln":434,"id":"zeqe70"},{"t":"say","k":"d","who":"裴柱現","text":"「閉嘴。」","ln":436,"expr":"生氣","id":"oanm5f"},{"t":"say","k":"n","text":"我笑了。她也笑了。","id":"15p9c6r","ln":438},{"t":"say","k":"n","text":"笑完之後，她把袖子捲起來，露出手腕。洗過之後，那裡還留著一小片淡淡的、珍珠色的痕跡。","id":"1ftmfxg","ln":440},{"t":"say","k":"d","who":"裴柱現","text":"「……還沒有完全消掉。」","ln":442,"expr":"難過","id":"1366uda"},{"t":"say","k":"n","text":"她想把袖子放下來。我握住了她的手。","id":"gon9p6","ln":444},{"t":"say","k":"d","who":"孫承完","text":"「讓我看。」","ln":446,"id":"j4gd2y"},{"t":"say","k":"n","text":"她看著我，很久很久。","id":"fq912s","ln":448},{"t":"say","k":"n","text":"然後她沒有再躲。","id":"qcsqal","ln":450},{"t":"say","k":"n","text":"燈塔的光掃過來，照在她的手腕上。那一小片鱗在光裡一閃，像落在她身上的星星。","id":"1n62oqd","ln":452},{"t":"say","k":"n","text":"我低下頭，很輕很輕地吻了它一下。","id":"1l8bp2a","ln":454},{"t":"say","k":"n","text":"她輕抽了一口氣。","id":"195644z","ln":456},{"t":"say","k":"d","who":"裴柱現","text":"「……妳不怕嗎？」","ln":458,"id":"fclqw0"},{"t":"say","k":"d","who":"孫承完","text":"「怕什麼？」","ln":460,"id":"13dfowh"},{"t":"say","k":"d","who":"裴柱現","text":"「怕我。」","ln":462,"id":"11dr2lg"},{"t":"say","k":"d","who":"孫承完","text":"「姐姐，我只怕妳一直發抖。」","ln":464,"id":"32und2"},{"t":"say","k":"n","text":"她愣住了。然後她把臉埋進我的肩膀，整個人靠過來，我也把她抱得好緊好緊。","id":"15pyk8i","ln":466},{"t":"say","k":"n","text":"我們就這樣躺下來，面對面，她的手一直握著我的手。我繼續唱歌，唱得很小聲，像在哄一個睡不著的小孩。","id":"y61x7p","ln":468},{"t":"say","k":"n","text":"唱到第三首的時候，她的聲音從我的肩膀那裡悶悶地傳出來。","id":"1c6h8xg","ln":470},{"t":"say","k":"d","who":"裴柱現","text":"「……承完。」","ln":472,"expr":"害羞","id":"b7e6kd"},{"t":"say","k":"n","text":"我停住了。","id":"1m2nlg0","ln":474},{"t":"say","k":"d","who":"孫承完","text":"「……妳第一次沒有連名帶姓叫我。」","ln":476,"id":"orskdl"},{"t":"say","k":"d","who":"裴柱現","text":"「……不行嗎？」","ln":478,"id":"1dfid0s"},{"t":"say","k":"d","who":"孫承完","text":"「可以。很可以。」","ln":480,"id":"15mkctd"},{"t":"say","k":"n","text":"她沒有再說話。過了一會兒，她的呼吸變得又慢又長。","id":"1izdkmk","ln":482},{"t":"say","k":"n","text":"她睡著了。","id":"w98ful","ln":484},{"t":"say","k":"i","text":"（……原來，她也會睡著啊。）","id":"101hsuw","ln":486},{"t":"say","k":"n","text":"窗外的燈塔一圈一圈地轉。我看著她的睡臉，看了很久很久，直到自己也閉上眼睛。","id":"1tsr0av","ln":488},{"t":"trans","kind":"out","ln":490},{"t":"cgEnd","ln":491},{"t":"say","k":"n","text":"……","id":"zmiey","ln":493},{"t":"se","names":["海浪"],"ln":495},{"t":"bg","name":"孫承完的房間・清晨","ln":496},{"t":"trans","kind":"in","ln":497},{"t":"bgm","name":"心動（安靜版）","ln":498},{"t":"say","k":"n","text":"我醒來的時候，天剛亮。","id":"rppzmm","ln":500},{"t":"say","k":"n","text":"海浪的聲音從窗外傳進來，很慢、很溫柔。","id":"195cidg","ln":502},{"t":"say","k":"n","text":"姐姐還在睡。她蜷在我旁邊，頭髮散了滿枕頭，一隻手抓著我的手指，抓得緊緊的，好像怕我跑掉。","id":"1wmg6eb","ln":504},{"t":"say","k":"n","text":"我看了她很久。","id":"gpwkcu","ln":506},{"t":"say","k":"n","text":"在晨光裡，她的睫毛一動一動的。她慢慢睜開眼睛，看見我，愣了一下，然後把臉埋進被子裡。","id":"129ey3j","ln":508},{"t":"show","list":[{"c":"裴柱現","e":"害羞"}],"ln":510},{"t":"say","k":"d","who":"裴柱現","text":"「……看甚麼。」","ln":512,"id":"tdf7hn"},{"t":"say","k":"d","who":"孫承完","text":"「早安，姐姐。」","ln":514,"expr":"笑","id":"1jdy47t"},{"t":"say","k":"n","text":"她悶在被子裡，過了很久，才很小聲地說：","id":"oeyz5u","ln":516},{"t":"say","k":"d","who":"裴柱現","text":"「承完。」","ln":518,"id":"1yqv22d"},{"t":"say","k":"d","who":"孫承完","text":"「嗯？」","ln":520,"id":"12nqrky"},{"t":"say","k":"d","who":"裴柱現","text":"「……三月二十九日那天，妳有空嗎？」","ln":522,"id":"1yssvs5"},{"t":"say","k":"d","who":"孫承完","text":"「有啊。怎麼了？」","ln":524,"id":"l1qomn"},{"t":"say","k":"d","who":"裴柱現","text":"「那天……是我的生日。」","ln":526,"id":"s4vs6o"},{"t":"say","k":"d","who":"孫承完","text":"「真的嗎？那我要幫妳慶祝！要吃蛋糕，要插蠟燭——」","ln":528,"expr":"驚訝","id":"kd4iv3"},{"t":"say","k":"n","text":"我說到一半，停住了。","id":"i4yxxq","ln":530},{"t":"say","k":"n","text":"她從被子裡探出頭來看我。她在微笑，可是那個笑感覺不太一樣，不知道為什麼，讓我胸口一抽。","id":"qlcyuv","ln":532},{"t":"say","k":"d","who":"裴柱現","text":"「……好啊。」","ln":534,"expr":"難過","id":"mxkpud"},{"t":"jump","to":"4-7","ln":536},{"t":"label","id":"4-6B","title":"被誘惑的夜","ln":538},{"t":"show","list":[{"c":"裴柱現","e":"普通"}],"ln":540},{"t":"say","k":"n","text":"姐姐一直看著窗外的海。","id":"wm27te","ln":542},{"t":"say","k":"n","text":"燈塔的光掃過去，海面一閃，又暗下來。她的嘴唇動了動，很小聲地說了兩個字。","id":"h7a575","ln":544},{"t":"say","k":"d","who":"裴柱現","text":"「……九天。」","ln":546,"id":"19pzhws"},{"t":"say","k":"d","who":"孫承完","text":"「什麼？」","ln":548,"id":"1t31pa3"},{"t":"say","k":"n","text":"她轉過頭來。","id":"198kj1h","ln":550},{"t":"show","list":[{"c":"裴柱現","e":"魅惑"}],"ln":552},{"t":"say","k":"n","text":"她的表情變了。","id":"i6ylje","ln":554},{"t":"say","k":"n","text":"剛才那個發抖的、縮成一團的姐姐不見了。她的眼睛裡有一點光，深藍色的，在暗處幽幽地亮著，像深海裡某種會發光的魚，讓人想趨近。","id":"6cflv4","ln":556},{"t":"say","k":"n","text":"她靠過來。","id":"10d2h8r","ln":558},{"t":"say","k":"d","who":"裴柱現","text":"「孫承完。」","ln":560,"id":"1x71sfc"},{"t":"say","k":"n","text":"她的聲音也變了。更低、更柔，每一個字都像搔著我的耳朵。","id":"81hckf","ln":562},{"t":"say","k":"d","who":"裴柱現","text":"「妳想聽我唱歌嗎？只唱給妳一個人聽。」","ln":564,"id":"1owj8h2"},{"t":"say","k":"n","text":"我應該要覺得奇怪的。她從來沒有唱過歌。","id":"1lax0jo","ln":566},{"t":"say","k":"n","text":"可是我什麼都沒辦法想。","id":"eksss4","ln":568},{"t":"cg","id":"09","title":"燈塔之夜","ln":570},{"t":"say","k":"n","text":"她開始哼。","id":"1jac3wt","ln":572},{"t":"say","k":"n","text":"就是那個聲音。那天在雨夜裡聽見的哼唱，沒有歌詞、沒有旋律，在我的腦子裡一圈一圈地繞。","id":"1fpvw0k","ln":574},{"t":"say","k":"n","text":"她輕輕推著我的肩膀，我順從的躺下。她的手指梳過我的頭髮，一下、一下，冰涼又溫柔。","id":"et4mam","ln":576},{"t":"say","k":"n","text":"然後她吻了我。","id":"1c6nhtw","ln":578},{"t":"say","k":"n","text":"那個吻是甜的，甜得過分。","id":"1pc6zcn","ln":580},{"t":"say","k":"n","text":"整個房間在搖晃，像一艘船。燈塔的光掃過來，她的臉在光裡白得發亮，眼睛裡的那一點藍光越來越亮。","id":"2s5qlr","ln":582},{"t":"say","k":"n","text":"我好睏。","id":"xc32vx","ln":584},{"t":"say","k":"n","text":"不是累的那種睏。是像沉進溫暖的海裡，被浪一下一下地晃著，越沉越深的那種睏。我想一直這樣沉下去。我想一直被她這樣看著。","id":"129xmbl","ln":586},{"t":"say","k":"n","text":"那種感覺不像是我自己的。像是被潮水拉著走，一直往深處、往深處——","id":"leo953","ln":588},{"t":"say","k":"i","text":"（……姐姐……）","id":"15vhfq8","ln":590},{"t":"say","k":"n","text":"她在我耳邊哼著那個沒有旋律的歌。","id":"ifyg37","ln":592},{"t":"say","k":"n","text":"我好像在下沉。","id":"1606j17","ln":594},{"t":"say","k":"n","text":"下沉、下沉——","id":"xpk1qt","ln":596},{"t":"trans","kind":"out","ln":598},{"t":"cgEnd","ln":599},{"t":"say","k":"n","text":"……","id":"pmwpz","ln":601},{"t":"se","names":["海浪"],"ln":603},{"t":"bg","name":"孫承完的房間・清晨","ln":604},{"t":"trans","kind":"in","ln":605},{"t":"bgm","name":"夜","ln":606},{"t":"say","k":"n","text":"我醒來的時候，天已經大亮了。","id":"1vkooaf","ln":608},{"t":"say","k":"n","text":"床邊是空的。","id":"fahag1","ln":610},{"t":"say","k":"n","text":"我想坐起來，可是身體重得像灌了鉛。手臂、腿、眼皮，全都使不上力。我躺在那裡喘了很久，才勉強撐起上半身。","id":"1ljbeyp","ln":612},{"t":"say","k":"n","text":"枕頭上有沙。","id":"mqtg12","ln":614},{"t":"say","k":"n","text":"細細的、白色的沙，散在她坐過的地方。","id":"gn1246","ln":616},{"t":"say","k":"n","text":"沙子中間，有一片小小的、閃閃發亮的東西。","id":"7sbx7m","ln":618},{"t":"say","k":"n","text":"我把它撿起來。指甲那麼大，薄薄的，對著窗外的光一照，從深藍變成淺藍、從淺藍變成銀白。","id":"1eb8n7g","ln":620},{"t":"say","k":"n","text":"是一片鱗。","id":"1f0pqhn","ln":622},{"t":"say","k":"n","text":"我走到浴室，看著鏡子裡的自己。","id":"4dvsw6","ln":624},{"t":"say","k":"n","text":"眼睛底下有很深的黑眼圈。臉色白得嚇人。","id":"3t92bk","ln":626},{"t":"say","k":"n","text":"還有，頭髮。","id":"9wp7xe","ln":628},{"t":"say","k":"n","text":"鬢角那裡，多了一小撮白頭髮。昨天還沒有的。","id":"10w6ab5","ln":630},{"t":"stat","list":[{"s":"採息","d":1}],"ln":632},{"t":"flag","names":["燈塔採息"],"ln":633},{"t":"say","k":"n","text":"那天下午，姐姐來了。她站在門口，沒有進來。","id":"1yvp5l3","ln":635},{"t":"show","list":[{"c":"裴柱現","e":"難過"}],"ln":637},{"t":"say","k":"d","who":"裴柱現","text":"「……孫承完。」","ln":639,"id":"lctmqe"},{"t":"say","k":"n","text":"她看著我的臉，看到我的白頭髮。她的嘴唇在發抖。","id":"7askbn","ln":641},{"t":"say","k":"d","who":"裴柱現","text":"「三月二十九日……是我的生日。」","ln":643,"id":"1ld9kko"},{"t":"say","k":"d","who":"孫承完","text":"「……嗯。」","ln":645,"id":"15wszzy"},{"t":"say","k":"d","who":"裴柱現","text":"「那天，妳可以……陪我嗎？」","ln":647,"id":"ocu1b3"},{"t":"say","k":"n","text":"我看著她。我應該要問她很多事的。昨天晚上到底怎麼了，那片鱗是什麼，那個銀髮的女人是誰。","id":"39ab5c","ln":649},{"t":"say","k":"n","text":"可是我只說：","id":"vugm7f","ln":651},{"t":"say","k":"d","who":"孫承完","text":"「好。」","ln":653,"id":"1ozmszs"},{"t":"say","k":"n","text":"她低下頭，轉身走了。","id":"mgsso5","ln":655},{"t":"say","k":"n","text":"我手心裡，還握著那片鱗。","id":"n9jkx9","ln":657},{"t":"jump","to":"4-7","ln":659},{"t":"label","id":"4-7","title":"九天","ln":661},{"t":"hide","all":true,"ln":663},{"t":"bg","name":"燈塔・黃昏","ln":664},{"t":"bgm","name":"夜","ln":665},{"t":"say","k":"n","text":"那天傍晚，我一個人爬上燈塔。","id":"13fm8r5","ln":667},{"t":"say","k":"n","text":"從這裡可以看見整片白鹽灣。祭典的燈籠已經收起來了，堤防上只剩下幾個工人在拆攤子。","id":"qut9ib","ln":669},{"t":"say","k":"n","text":"海很平靜。平靜得看不出昨天晚上，它曾經發過光，也曾經站起來過。","id":"xvi4yk","ln":671},{"t":"say","k":"n","text":"我想起姐姐說的那兩個字。","id":"1me2qkr","ln":673},{"t":"say","k":"n","text":"九天。","id":"pdnxx2","ln":675},{"t":"say","k":"n","text":"三月二十日之後的第九天，是三月二十九日。","id":"1jx68hn","ln":677},{"t":"say","k":"n","text":"是她的生日。","id":"1ik7q9g","ln":679},{"t":"say","k":"i","text":"（……九天之後，會發生什麼事？）","id":"feu63h","ln":681},{"t":"say","k":"n","text":"海沒有回答我。","id":"1935nwz","ln":683},{"t":"say","k":"n","text":"燈塔的燈亮了。一圈、一圈，掃過整片黑下來的海。","id":"17uzcuu","ln":685},{"t":"chend","text":"第四章　完","ln":687}]},{"key":"05_第五章_鱗","name":"05_第五章_鱗.md","route":"main","num":5,"title":"第五章　鱗","ops":[{"t":"title","text":"第五章　鱗","card":true,"ln":1},{"t":"label","id":"5-0","title":"分歧","ln":3},{"t":"bg","name":"燈塔・夜","ln":5},{"t":"bgm","name":"夜","ln":6},{"t":"say","k":"n","text":"春潮祭之後，白鹽灣恢復了平靜。","id":"gul93t","ln":8},{"t":"say","k":"n","text":"觀光客回去了，攤子拆完了，海又變回那片普通的、藍色的海。好像那天晚上發光的、捲起的，都只是一場夢。","id":"1hw36qe","ln":10},{"t":"say","k":"n","text":"可是我清楚不是。","id":"15mgrrx","ln":12},{"t":"say","k":"n","text":"我抽屜裡的那片鱗，每天晚上都還在發光。","id":"7rrsvb","ln":14},{"t":"if","cond":[[{"s":"信任","op":">=","v":3}]],"to":"5-1A","ln":16},{"t":"jump","to":"5-1B","ln":17},{"t":"label","id":"5-1A","title":"月光","ln":19},{"t":"bg","name":"孫承完的房間・夜","ln":21},{"t":"say","k":"n","text":"三月二十二日的晚上，有人敲我的門。","id":"17xzprw","ln":23},{"t":"se","names":["開門"],"ln":25},{"t":"show","list":[{"c":"裴柱現","e":"普通"}],"ln":26},{"t":"say","k":"n","text":"是姐姐。她穿著第一次見面時那件白色洋裝，赤著腳，頭髮放下來，被海風吹得有點亂，帆布包斜背在身上。","id":"fihckj","ln":28},{"t":"say","k":"d","who":"裴柱現","text":"「承完。」","ln":30,"id":"qd4zb6"},{"t":"say","k":"d","who":"孫承完","text":"「姐姐？這麼晚了——」","ln":32,"id":"pp1m6a"},{"t":"say","k":"d","who":"裴柱現","text":"「妳說過，我想說的時候再說就好。」","ln":34,"id":"1qfee3w"},{"t":"say","k":"n","text":"她看著我。那雙深褐色的眼睛，在門口的燈下很亮、很認真。","id":"1pgo6rq","ln":36},{"t":"say","k":"d","who":"裴柱現","text":"「……我想說了。」","ln":38,"id":"y7d8r9"},{"t":"hide","all":true,"ln":40},{"t":"trans","kind":"out","ln":41},{"t":"bg","name":"白鹽灣沙灘・夜","ln":42},{"t":"trans","kind":"in","ln":43},{"t":"se","names":["海浪"],"ln":44},{"t":"say","k":"n","text":"月亮很圓。","id":"u9mnlg","ln":46},{"t":"say","k":"n","text":"沙灘上一個人都沒有，只有月光鋪成的那條銀色的路，從海平線一直延伸到我們腳邊。跟我生日那天晚上一樣。","id":"e0cgwo","ln":48},{"t":"say","k":"n","text":"姐姐把帆布包放在乾沙上，寄居蟹爬出來，爬到包包頂上蹲著，像一個準備看戲的觀眾。","id":"1h1211z","ln":50},{"t":"say","k":"n","text":"然後，她朝海走過去。","id":"q41n6j","ln":52},{"t":"say","k":"n","text":"走過乾沙。走過濕沙。走過那條她從來不肯跨過去的、白白的浪花線。","id":"w337rc","ln":54},{"t":"say","k":"d","who":"孫承完","text":"「姐姐——！」","ln":56,"expr":"驚訝","id":"n1qlvv"},{"t":"say","k":"n","text":"我的身體比腦子先動，想起她對海的異常害怕","id":"1i12gjj","ln":58},{"t":"say","k":"n","text":"可是她回過頭來，對我搖了搖頭。","id":"e2s3b2","ln":60},{"t":"say","k":"n","text":"我停住了。","id":"19ceyd1","ln":62},{"t":"say","k":"n","text":"海水淹過她的腳踝、她的小腿、她的膝蓋。白色的裙擺漂在水面上，像一朵慢慢打開的花。","id":"1uvevon","ln":64},{"t":"say","k":"n","text":"然後，光開始從水底亮起來。","id":"1nfw688","ln":66},{"t":"cg","id":"10","title":"月光下的魚尾","ln":68},{"t":"form","list":[{"c":"裴柱現","f":"人魚"}],"ln":69},{"t":"say","k":"n","text":"那些鱗片，從她的腳背開始，一片一片地攀上來。湛藍色的、銀色的，沿著她的小腿往上爬，在月光底下閃得像一整片星空。","id":"1p1p9pz","ln":71},{"t":"say","k":"n","text":"她的兩條腿，在水裡慢慢地合在一起。","id":"ikk8m9","ln":73},{"t":"say","k":"n","text":"變成了一條尾巴。","id":"lwaj1o","ln":75},{"t":"say","k":"n","text":"很長、很美的尾巴，湛藍色的鱗片一路漸層到尾端，尾鰭是半透明的淡藍色，薄得像紗，在水裡輕輕擺動，每擺一下，就帶起一圈發光的漣漪。","id":"1qdgk0t","ln":77},{"t":"say","k":"n","text":"她坐在淺灘的一塊礁石上，濕透的長髮披在肩上，回過頭看我。","id":"1o5oo6y","ln":79},{"t":"say","k":"n","text":"我不自覺地憋住呼吸。","id":"3xcp9z","ln":81},{"t":"say","k":"d","who":"裴柱現","text":"「我叫裴柱現。」","ln":83,"id":"ht786i"},{"t":"say","k":"d","who":"裴柱現","text":"「貝貝國的第七公主。人類的故事裡，叫我們人魚。」","ln":85,"id":"1c7moo0"},{"t":"say","k":"n","text":"我張開嘴，什麼聲音都發不出來。","id":"7ecywt","ln":87},{"t":"say","k":"n","text":"她看著我，好像在等我尖叫、逃跑，或者昏倒。","id":"1uf3vnp","ln":89},{"t":"say","k":"n","text":"過了很久，她又小聲地補了一句：","id":"ojlpvn","ln":91},{"t":"say","k":"d","who":"裴柱現","text":"「……還有，我其實不是三十五歲。」","ln":93,"expr":"害羞","id":"17snlo5"},{"t":"say","k":"d","who":"孫承完","text":"「……啊？」","ln":95,"id":"gzl5x9"},{"t":"say","k":"d","who":"裴柱現","text":"「我……少說了一個零。」","ln":97,"id":"gykfda"},{"t":"say","k":"d","who":"孫承完","text":"「……三、三百五十歲？」","ln":99,"expr":"驚訝","id":"1w2ro1v"},{"t":"say","k":"d","who":"裴柱現","text":"「人魚的三百五十歲跟人類的三十五歲差不多！我沒有騙妳！是……四捨五入！」","ln":101,"expr":"生氣","id":"90mjbj"},{"t":"say","k":"d","who":"孫承完","text":"「那不叫四捨五入吧！」","ln":103,"id":"19po49h"},{"t":"say","k":"n","text":"包包上的寄居蟹，發出了一聲很像嘆氣的聲音。","id":"1l3b676","ln":105},{"t":"flag","names":["坦白"],"ln":107},{"t":"choice","title":"選擇⑧","options":[{"key":"A","text":"走進海裡，牽住她的手","to":"5-1A-1","eff":[{"s":"心動","d":2}]},{"key":"B","text":"愣在原地","to":"5-1A-2"}],"ln":109},{"t":"label","id":"5-1A-1","title":"牽手","ln":113},{"t":"say","k":"n","text":"我走進海裡。","id":"1w9yhig","ln":115},{"t":"say","k":"n","text":"海水冰涼地淹過我的腳踝、我的膝蓋、我的腰。我一步一步走到她坐著的那塊礁石旁邊。","id":"ugcrhl","ln":117},{"t":"say","k":"n","text":"然後我牽起她的手。","id":"bfxehe","ln":119},{"t":"say","k":"n","text":"她的手很涼，涼得跟海水一樣。可是在我掌心裡，輕輕地在抖。","id":"i8mrue","ln":121},{"t":"cgEnd","ln":123},{"t":"show","list":[{"c":"裴柱現","e":"驚慌"}],"ln":124},{"t":"say","k":"d","who":"裴柱現","text":"「……妳不怕？」","ln":126,"id":"1b6tn5n"},{"t":"say","k":"d","who":"孫承完","text":"「我是救生員啊。」","ln":128,"expr":"笑","id":"7n2qv"},{"t":"say","k":"d","who":"孫承完","text":"「看到有人一個人待在海裡，就會想過去牽她的手。」","ln":130,"id":"jfb4cf"},{"t":"say","k":"n","text":"她看著我。看得比任何時候都用力。","id":"d6u36o","ln":132},{"t":"say","k":"n","text":"她的眼眶紅了，紅得那麼厲害。可是一滴眼淚都沒有掉下來。","id":"qhf8jb","ln":134},{"t":"say","k":"d","who":"裴柱現","text":"「……笨蛋。」","ln":136,"expr":"難過","id":"six890"},{"t":"say","k":"n","text":"她握緊了我的手。握得那麼緊，緊得像是怕我又放開。","id":"l21utm","ln":138},{"t":"jump","to":"5-2","ln":140},{"t":"label","id":"5-1A-2","title":"愣住","ln":142},{"t":"say","k":"n","text":"我站在原地，一步都動不了。","id":"1vlhjvq","ln":144},{"t":"say","k":"n","text":"腦子裡亂成一團。那些鱗片、那天的浪、阿英說的傳說、我的白頭髮——全部在腦子裡轉來轉去，轉得我頭好暈。","id":"1j7vek2","ln":146},{"t":"say","k":"n","text":"她看著我，等了很久，等我開口。我卻一句話都說不出來。","id":"z242r9","ln":148},{"t":"cgEnd","ln":150},{"t":"show","list":[{"c":"裴柱現","e":"難過"}],"ln":151},{"t":"say","k":"n","text":"然後，她慢慢地垂下眼睛。","id":"cbhqc8","ln":153},{"t":"say","k":"d","who":"裴柱現","text":"「……果然。」","ln":155,"id":"2zf5gb"},{"t":"say","k":"d","who":"孫承完","text":"「不是，我只是——」","ln":157,"id":"8dzlf8"},{"t":"say","k":"d","who":"裴柱現","text":"「沒關係。」","ln":159,"id":"12m5m45"},{"t":"say","k":"n","text":"她笑了一下。那個笑比哭還讓人難受。","id":"1tta1fx","ln":161},{"t":"say","k":"d","who":"裴柱現","text":"「人類本來就應該害怕。這樣比較安全。」","ln":163,"id":"1vyakj1"},{"t":"say","k":"n","text":"我想說些什麼，可是不知道要從哪裡開始。","id":"q61ecj","ln":165},{"t":"say","k":"n","text":"我們就這樣隔著幾公尺的海水，一個坐在礁石上，一個站在沙灘上，聽著浪一下一下地拍過來。","id":"hjlgcd","ln":167},{"t":"jump","to":"5-2","ln":169},{"t":"label","id":"5-1B","title":"救援","ln":171},{"t":"say","k":"n","text":"三月二十四日的晚上，我值夜班。","id":"a2dldl","ln":173},{"t":"say","k":"n","text":"快十一點的時候，無線電響了。北邊礁石區外，有個喝醉的觀光客說要游去對面的小島，游到一半就不見了。","id":"1pw28l0","ln":175},{"t":"bg","name":"礁石海岸・夜","ln":177},{"t":"bgm","name":"緊張","ln":178},{"t":"se","names":["海浪"],"ln":179},{"t":"say","k":"n","text":"我抓起浮標衝進海裡。","id":"hoqlo6","ln":181},{"t":"say","k":"n","text":"夜裡的海很黑，浪很亂。我游了很久才找到他，他已經嗆了好幾口水，整個人往下沉。我從背後抱住他，往回游。","id":"vkcrzm","ln":183},{"t":"say","k":"n","text":"然後，我的腿抽筋了。","id":"jjb6t","ln":185},{"t":"shake","ln":187},{"t":"say","k":"n","text":"劇痛從小腿一路竄上來。我抱著那個人，兩個人一起往下沉。","id":"o6m3gu","ln":189},{"t":"say","k":"n","text":"海水灌進我的鼻子和嘴巴。好冷。好黑。","id":"1x48on6","ln":191},{"t":"say","k":"i","text":"（……不行。至少要把他送回去——）","id":"49pytb","ln":193},{"t":"say","k":"n","text":"就在這時候，有什麼東西從底下托住了我們。","id":"zqzbpy","ln":195},{"t":"say","k":"n","text":"很有力、很穩，像一隻很大的手。","id":"mdrnh1","ln":197},{"t":"say","k":"n","text":"我們被托出水面。我嗆著水大口呼吸，在月光底下，看見了托住我們的東西。","id":"1en7r5e","ln":199},{"t":"bg","name":"白鹽灣海面・夜","ln":201},{"t":"form","list":[{"c":"裴柱現","f":"人魚"}],"ln":202},{"t":"say","k":"n","text":"一條尾巴。","id":"8oibgu","ln":204},{"t":"say","k":"n","text":"湛藍色的、閃著銀光的，很長很長的魚尾，在水裡有力地擺動，推著我們往岸邊游。","id":"rxsa6","ln":206},{"t":"say","k":"n","text":"我轉過頭。","id":"1kxvmg","ln":208},{"t":"say","k":"n","text":"一張我再熟悉不過的臉，就在我旁邊。","id":"14sqxk7","ln":210},{"t":"say","k":"n","text":"濕透的藍黑色長髮。深褐色的眼睛。眼角旁的那顆淚痣。","id":"1mu55an","ln":212},{"t":"show","list":[{"c":"裴柱現","e":"驚慌"}],"ln":214},{"t":"say","k":"d","who":"孫承完","text":"「……姐姐？」","ln":216,"expr":"驚訝","id":"1sjei7h"},{"t":"say","k":"n","text":"她看著我，眼睛睜得好大。","id":"13j50kz","ln":218},{"t":"say","k":"n","text":"然後我們被推上了淺灘。我把那個觀光客拖上岸，他已經昏過去了，但還有呼吸。","id":"1tyubb0","ln":220},{"t":"say","k":"n","text":"我回過頭。","id":"5mqavj","ln":222},{"t":"say","k":"n","text":"她還在淺灘的水裡，只露出肩膀以上。跟我生日那天晚上一模一樣。","id":"59xz6r","ln":224},{"t":"say","k":"n","text":"我們隔著月光看著彼此。","id":"1t1fct3","ln":226},{"t":"hide","list":["裴柱現"],"ln":228},{"t":"say","k":"n","text":"然後，她沉進水裡，消失了。","id":"4pedi7","ln":230},{"t":"label","id":"5-1B-1","title":"冷戰","ln":232},{"t":"bg","name":"孫承完的房間・夜","ln":234},{"t":"bgm","name":"夜","ln":235},{"t":"say","k":"n","text":"那天晚上，我一夜沒睡。","id":"1x5d1ov","ln":237},{"t":"say","k":"n","text":"所有的事都串起來了。不肯碰的海水。手臂上的鱗片。人工呼吸時那個飢餓的眼神。雨夜之後的發燒。阿英說的傳說。","id":"wl1cx3","ln":239},{"t":"say","k":"n","text":"還有，第一次見面那天，她說：「是我讓她救的。」","id":"1f9p5up","ln":241},{"t":"say","k":"i","text":"（……她是故意溺水，為什麼反而在這裡誠實啊。）","id":"15tgf16","ln":243},{"t":"say","k":"n","text":"我坐在床上，看著抽屜裡的那片鱗。","id":"1pwi9jx","ln":245},{"t":"say","k":"n","text":"我不知道自己是生氣、難過，還是害怕。","id":"12mneyw","ln":247},{"t":"say","k":"n","text":"我只知道，我被騙了。","id":"i9fsz1","ln":249},{"t":"say","k":"n","text":"接下來的兩天，姐姐沒有去「退潮」。","id":"18hpzb0","ln":251},{"t":"say","k":"n","text":"阿英說她請假了，沒說原因。阿英看我的眼神很複雜，可是她什麼都沒問。","id":"1jvz5ah","ln":253},{"t":"say","k":"n","text":"康塞了一顆肉包給我。","id":"gr02g7","ln":255},{"t":"say","k":"d","who":"康","text":"「承完，妳兩天沒吃東西了。」","ln":257,"expr":"普通","id":"7g75qc"},{"t":"say","k":"d","who":"孫承完","text":"「……妳怎麼知道？」","ln":259,"id":"1wml6z0"},{"t":"say","k":"d","who":"康","text":"「因為妳的臉，看起來跟我餓的時候一樣。」","ln":261,"id":"yataf4"},{"t":"choice","title":"選擇⑧","options":[{"key":"A","text":"主動去找她","to":"5-1B-2","eff":[{"s":"心動","d":1}]},{"key":"B","text":"等她來找我","to":"5-1B-3"}],"ln":263},{"t":"label","id":"5-1B-2","title":"去找她","ln":267},{"t":"hide","all":true,"ln":269},{"t":"bg","name":"礁石海岸・夜","ln":270},{"t":"se","names":["海浪"],"ln":271},{"t":"say","k":"n","text":"第三天晚上，我去了北邊的礁石區。","id":"e8oj60","ln":273},{"t":"say","k":"n","text":"我站在她那天跟海說話的那塊礁石上，對著黑漆漆的海大喊：","id":"a6uq9l","ln":275},{"t":"say","k":"d","who":"孫承完","text":"「裴柱現——！」","ln":277,"id":"1jpfg4e"},{"t":"say","k":"n","text":"只有浪聲回答我。","id":"77xpx","ln":279},{"t":"say","k":"d","who":"孫承完","text":"「裴柱現！我知道妳聽得到！」","ln":281,"id":"1op8tnj"},{"t":"say","k":"d","who":"孫承完","text":"「妳騙了我！妳從一開始就騙我！」","ln":283,"id":"1aqmsp7"},{"t":"say","k":"d","who":"孫承完","text":"「……可是妳也救了我。」","ln":285,"id":"v882a0"},{"t":"say","k":"n","text":"我的聲音啞了。","id":"me433r","ln":287},{"t":"say","k":"d","who":"孫承完","text":"「所以，出來。我們把話說清楚。」","ln":289,"id":"qfr2xp"},{"t":"say","k":"n","text":"我不斷地喊，過了很久很久。","id":"2gdpdw","ln":291},{"t":"say","k":"n","text":"海面上，冒出了一顆頭。","id":"ed4mg9","ln":293},{"t":"show","list":[{"c":"裴柱現","e":"難過"}],"ln":295},{"t":"say","k":"n","text":"她看著我，濕透的頭髮貼在臉上，看起來好小、好可憐，一點都不像公主。","id":"en1r22","ln":297},{"t":"say","k":"d","who":"裴柱現","text":"「……妳不應該來的。」","ln":299,"id":"f3e0mg"},{"t":"say","k":"d","who":"孫承完","text":"「但我已經在這裡了。」","ln":301,"id":"137yqv2"},{"t":"jump","to":"5-2","ln":303},{"t":"label","id":"5-1B-3","title":"等","ln":305},{"t":"say","k":"n","text":"我沒有去找她。","id":"h855iz","ln":307},{"t":"say","k":"n","text":"我告訴自己，被騙的人是我。應該道歉的人是她。","id":"y08nik","ln":309},{"t":"say","k":"n","text":"第三天、第四天，她都沒有出現。","id":"rmpktf","ln":311},{"t":"say","k":"n","text":"三月二十七日的晚上，有東西在敲我的門。","id":"jcqo57","ln":313},{"t":"say","k":"n","text":"叩、叩、叩。很小聲，位置很低。","id":"1296ze6","ln":315},{"t":"se","names":["開門"],"ln":317},{"t":"say","k":"n","text":"我打開門。門口沒有人。","id":"bta494","ln":319},{"t":"say","k":"n","text":"低頭一看，一隻背著粉紅色螺殼的寄居蟹，正舉著鉗子，敲我的門框。","id":"1jw8agg","ln":321},{"t":"show","list":[{"c":"珊婆","e":"吐槽"}],"ln":323},{"t":"say","k":"d","who":"寄居蟹","text":"「妳們兩個笨蛋，到底要僵到什麼時候？」","ln":325,"id":"xorrxe"},{"t":"say","k":"n","text":"我愣住了。","id":"1cfuvxe","ln":327},{"t":"say","k":"d","who":"孫承完","text":"「……螃蟹說話了。」","ln":329,"expr":"驚訝","id":"uhlzin"},{"t":"say","k":"d","who":"寄居蟹","text":"「螃蟹說話有什麼好奇怪的。人魚都看過了，還怕一隻會說話的螃蟹？」","ln":331,"id":"eqe83l"},{"t":"say","k":"d","who":"寄居蟹","text":"「走。她在礁石那邊等妳。」","ln":333,"id":"z72gcq"},{"t":"say","k":"d","who":"寄居蟹","text":"「她不敢來找妳，又怕妳不來。已經在那邊等了三個晚上了。」","ln":335,"id":"1f2bl01"},{"t":"jump","to":"5-2","ln":337},{"t":"label","id":"5-2","title":"真相","ln":339},{"t":"hide","all":true,"ln":341},{"t":"bg","name":"礁石海岸・夜","ln":342},{"t":"bgm","name":"夜","ln":343},{"t":"se","names":["海浪"],"ln":344},{"t":"say","k":"n","text":"我們坐在礁石上。","id":"29i7gj","ln":346},{"t":"say","k":"n","text":"姐姐的尾巴泡在海水裡，輕輕地擺動。我坐在她旁邊，褲管捲到膝蓋，腳也泡在水裡。那隻寄居蟹蹲在我們中間。","id":"1v181ff","ln":348},{"t":"show","list":[{"c":"裴柱現","e":"普通"},{"c":"珊婆","e":"普通"}],"ln":350},{"t":"say","k":"n","text":"她把所有的事都告訴了我。","id":"1fx1mue","ln":352},{"t":"say","k":"n","text":"海底有個國家，叫貝貝國。人魚的壽命是人類的十倍，可是人魚自己沒辦法產生生命力。人類的歌聲和呼吸裡，有一種東西，人魚叫它「歌息」。","id":"4qeskb","ln":354},{"t":"say","k":"d","who":"裴柱現","text":"「我們親吻人類，把歌息採走。採一點點，人類會累幾天，有可能少活幾年。採太多……」","ln":356,"id":"14cti5w"},{"t":"say","k":"n","text":"她沒有說下去。","id":"1fets33","ln":358},{"t":"say","k":"d","who":"裴柱現","text":"「三月二十九日，是我三百五十歲的生日。在貝貝國，叫做成年潮。」","ln":360,"id":"1nuz0c3"},{"t":"say","k":"d","who":"裴柱現","text":"「成年潮的天亮之前，我必須帶一個人類的歌息回去。那是我的成年禮。」","ln":362,"id":"1r0s3s8"},{"t":"say","k":"d","who":"孫承完","text":"「……如果帶不回去呢？」","ln":364,"id":"19yuo0p"},{"t":"say","k":"n","text":"她看著海。","id":"wbsasj","ln":366},{"t":"say","k":"d","who":"裴柱現","text":"「就會變成泡沫。」","ln":368,"id":"1t7xg33"},{"t":"say","k":"n","text":"我的心臟像被什麼東西狠狠揪了一下。","id":"vh74u1","ln":370},{"t":"say","k":"d","who":"裴柱現","text":"「我上岸那天晚上，本來只是想隨便挑一個人類。然後我聽見妳在唱歌。」","ln":372,"id":"1slof9c"},{"t":"say","k":"d","who":"裴柱現","text":"「我在海裡活了幾百年，從來沒有聽過那樣的聲音。我們人魚只會哼，不會唱。我們的聲音可以讓人類忘記自己是誰，可是……沒有辦法讓任何人哭。」","ln":374,"id":"2cilne"},{"t":"say","k":"d","who":"裴柱現","text":"「妳的歌可以。」","ln":376,"id":"e8oewk"},{"t":"say","k":"d","who":"裴柱現","text":"「所以我選了妳。」","ln":378,"id":"792cz4"},{"t":"say","k":"d","who":"孫承完","text":"「……那妳為什麼不直接跟我要？」","ln":380,"id":"mn1xpc"},{"t":"say","k":"d","who":"裴柱現","text":"「一開始，我根本沒想過要問。」","ln":382,"id":"1xtmvgy"},{"t":"say","k":"d","who":"裴柱現","text":"「在貝貝國，人類叫做『陸果』。誰會去問一顆果子，願不願意被摘？」","ln":384,"id":"vto4lb"},{"t":"say","k":"d","who":"裴柱現","text":"「而且三百年前，人類一知道海裡有我們，就帶著網子來了。」","ln":386,"id":"y1fsly"},{"t":"say","k":"n","text":"我想起阿英說的。那一年，整片海都是紅的。","id":"176nvpm","ln":388},{"t":"if","cond":[[{"s":"採息","op":">=","v":1}]],"to":"5-2B","ln":390},{"t":"jump","to":"5-2A","ln":391},{"t":"label","id":"5-2A","title":"苦的","ln":393},{"t":"say","k":"d","who":"裴柱現","text":"「可是我一次都沒有採成。」","ln":395,"id":"bcqsno"},{"t":"say","k":"d","who":"孫承完","text":"「……一次都沒有？」","ln":397,"id":"114oses"},{"t":"say","k":"d","who":"裴柱現","text":"「人工呼吸那次，我只吸了一口，就醉了。雨夜那次……」","ln":399,"id":"1up5xju"},{"t":"say","k":"n","text":"她停了一下。","id":"1l69d4f","ln":401},{"t":"say","k":"d","who":"裴柱現","text":"「是苦的。」","ln":403,"expr":"難過","id":"hq42xi"},{"t":"say","k":"n","text":"寄居蟹用鉗子敲了敲礁石。","id":"136um44","ln":405},{"t":"say","k":"d","who":"珊婆","text":"「人魚愛上一個人類之後，就再也採不了她的歌息。採到嘴裡，全是苦的。」","ln":407,"expr":"吐槽","id":"10nm7bd"},{"t":"say","k":"d","who":"珊婆","text":"「我早就跟她說了。她完了。」","ln":409,"id":"13ehbho"},{"t":"say","k":"d","who":"裴柱現","text":"「妳不要再說了！」","ln":411,"expr":"生氣","id":"14rl1mc"},{"t":"say","k":"n","text":"我看著她。她把臉轉開，耳朵紅得像煮熟的蝦。","id":"1apft69","ln":413},{"t":"say","k":"i","text":"（……那天在雨裡，她說「我完了」。原來是這個意思。）","id":"1sju8bz","ln":415},{"t":"jump","to":"5-3","ln":417},{"t":"label","id":"5-2B","title":"白髮","ln":419},{"t":"say","k":"n","text":"她轉過頭來，看著我鬢角的白頭髮。","id":"13qijg1","ln":421},{"t":"say","k":"d","who":"裴柱現","text":"「……那是我。」","ln":423,"expr":"難過","id":"1cg7hfo"},{"t":"say","k":"d","who":"孫承完","text":"「……」","ln":425,"id":"1kf5elk"},{"t":"if","cond":[[{"f":"燈塔採息","neg":false},{"f":"雨夜採息","neg":true}]],"to":"5-2D","ln":427},{"t":"say","k":"d","who":"裴柱現","text":"「雨夜那天。」","ln":429,"id":"1bx7bt1"},{"t":"if","cond":[[{"s":"採息","op":">=","v":2}]],"to":"5-2C","ln":431},{"t":"say","k":"d","who":"裴柱現","text":"「那天，我採了妳的歌息。妳的發燒、妳的白頭髮，都是我。」","ln":433,"id":"94gsnr"},{"t":"say","k":"d","who":"裴柱現","text":"「後來……我就採不了了。是苦的。」","ln":435,"id":"1yybg7m"},{"t":"say","k":"n","text":"她低下頭。","id":"18877fg","ln":437},{"t":"say","k":"d","who":"裴柱現","text":"「對不起。」","ln":439,"id":"13e1cju"},{"t":"jump","to":"5-3","ln":441},{"t":"label","id":"5-2C","title":"兩次","ln":443},{"t":"say","k":"d","who":"裴柱現","text":"「還有燈塔那天晚上。」","ln":445,"id":"1hd8i2"},{"t":"say","k":"d","who":"裴柱現","text":"「妳的發燒、妳的白頭髮、妳現在走兩步路就會喘……全都是我。」","ln":447,"id":"44aix2"},{"t":"say","k":"n","text":"她的聲音在發抖。","id":"eg8i47","ln":449},{"t":"say","k":"d","who":"裴柱現","text":"「我採了妳兩次。兩次的歌息，已經夠我的成年禮了。」","ln":451,"id":"ml6mnv"},{"t":"say","k":"n","text":"我看著她。腦子裡一片空白。","id":"1ydp0jg","ln":453},{"t":"say","k":"d","who":"孫承完","text":"「……所以，那天晚上，妳說要唱歌給我聽——」","ln":455,"id":"1hho9oc"},{"t":"say","k":"d","who":"裴柱現","text":"「我們不會唱歌。那是誘音。」","ln":457,"id":"r0ntbh"},{"t":"say","k":"d","who":"孫承完","text":"「……」","ln":459,"id":"1l947oh"},{"t":"say","k":"d","who":"裴柱現","text":"「對不起。」","ln":461,"id":"1341quv"},{"t":"say","k":"n","text":"她說了一次又一次。對不起、對不起、對不起。","id":"1gyxsoj","ln":463},{"t":"say","k":"n","text":"可是她的臉上，一滴眼淚都沒有。","id":"1tym4ut","ln":465},{"t":"jump","to":"5-3","ln":467},{"t":"label","id":"5-2D","title":"燈塔那晚","ln":469},{"t":"say","k":"d","who":"裴柱現","text":"「燈塔那天晚上。」","ln":471,"id":"s9ixg1"},{"t":"say","k":"d","who":"孫承完","text":"「……那天妳說要唱歌給我聽。」","ln":473,"id":"1y1az7"},{"t":"say","k":"d","who":"裴柱現","text":"「我們不會唱歌。那是誘音。」","ln":475,"id":"q6p08k"},{"t":"say","k":"n","text":"她的聲音很輕。","id":"15960ki","ln":477},{"t":"say","k":"d","who":"裴柱現","text":"「雨夜那天，我其實就已經嚐到苦味了。我以為只要再久一點、再用力一點，就可以把它吞下去。」","ln":479,"id":"fpqjcv"},{"t":"say","k":"d","who":"裴柱現","text":"「然後二姊在祭典上出現了。她用浪打我，是在提醒我，時間不多了。」","ln":481,"id":"1vtridl"},{"t":"say","k":"d","who":"裴柱現","text":"「我好怕。所以那天晚上，我逼自己採了。」","ln":483,"id":"19iiegg"},{"t":"say","k":"n","text":"她低下頭。","id":"19260id","ln":485},{"t":"say","k":"d","who":"裴柱現","text":"「好苦。苦得我在妳家門口，坐到天亮。」","ln":487,"expr":"難過","id":"1pdj2gd"},{"t":"say","k":"d","who":"裴柱現","text":"「對不起。」","ln":489,"id":"12u255w"},{"t":"jump","to":"5-3","ln":491},{"t":"label","id":"5-3","title":"那妳現在呢","ln":493},{"t":"say","k":"n","text":"海浪一下一下地拍在礁石上。","id":"cb2z05","ln":495},{"t":"say","k":"n","text":"我看著她。看著那條在月光下發光的尾巴，看著那張美得不合理的臉，看著她垂下來的、在發抖的睫毛。","id":"8ll8r4","ln":497},{"t":"say","k":"n","text":"我有好多話想問。","id":"8ww69x","ln":499},{"t":"choice","title":"選擇⑨","options":[{"key":"A","text":"「妳是不是只想利用我？」","to":"5-3A","eff":[{"s":"心動","d":-1}]},{"key":"B","text":"「那妳現在呢？」","to":"5-3B","eff":[{"s":"心動","d":1}]}],"ln":501},{"t":"label","id":"5-3A","title":"利用","ln":505},{"t":"say","k":"d","who":"孫承完","text":"「……所以，妳是不是只想利用我？」","ln":507,"expr":"認真","id":"1q8hvzx"},{"t":"say","k":"n","text":"她抬起頭。","id":"1q4i1ya","ln":509},{"t":"say","k":"d","who":"裴柱現","text":"「……一開始是。」","ln":511,"expr":"難過","id":"1o2ifsm"},{"t":"say","k":"n","text":"她沒有說謊。她沒有往右邊看。","id":"51jy43","ln":513},{"t":"say","k":"d","who":"裴柱現","text":"「一開始，妳只是一個聲音很好聽的陸果。」","ln":515,"id":"2rtmch"},{"t":"say","k":"n","text":"我閉上眼睛。這句話比任何事都還痛。","id":"p8pd2g","ln":517},{"t":"say","k":"d","who":"裴柱現","text":"「可是現在……」","ln":519,"id":"1wq7m5j"},{"t":"say","k":"n","text":"她停住了。張開嘴，又閉上。","id":"1dnshey","ln":521},{"t":"say","k":"d","who":"裴柱現","text":"「……我不知道人類的話要怎麼說。」","ln":523,"id":"17ce90l"},{"t":"say","k":"n","text":"那天晚上，她沒有把那句話說完。","id":"1eq6b86","ln":525},{"t":"jump","to":"5-4","ln":527},{"t":"label","id":"5-3B","title":"現在","ln":529},{"t":"say","k":"d","who":"孫承完","text":"「……那妳現在呢？」","ln":531,"id":"1pph9d9"},{"t":"say","k":"n","text":"她愣住了。","id":"1tbk0fu","ln":533},{"t":"say","k":"d","who":"孫承完","text":"「一開始是什麼，我不想管了。我想知道現在。」","ln":535,"id":"1g5rhoj"},{"t":"say","k":"d","who":"孫承完","text":"「現在，妳為什麼還在這裡？」","ln":537,"id":"1ywqpke"},{"t":"say","k":"n","text":"她看著我。月光落在她的眼睛裡，很深、很亮。","id":"s943zs","ln":539},{"t":"say","k":"d","who":"裴柱現","text":"「……現在，我只想聽妳唱歌。」","ln":541,"expr":"難過","id":"1wqudte"},{"t":"say","k":"d","who":"裴柱現","text":"「一直聽下去。聽到妳變成老奶奶，聽到我也變成老奶奶。」","ln":543,"id":"a9nbl9"},{"t":"say","k":"d","who":"裴柱現","text":"「可是人魚和人類，沒有辦法一起變老。」","ln":545,"id":"5ed63f"},{"t":"say","k":"n","text":"她伸手，碰了碰我的臉。手指很涼。","id":"16u7jcn","ln":547},{"t":"say","k":"d","who":"裴柱現","text":"「所以我只能，聽到三月二十九日。」","ln":549,"id":"73vblp"},{"t":"jump","to":"5-4","ln":551},{"t":"label","id":"5-4","title":"海螺","ln":553},{"t":"show","list":[{"c":"珊婆","e":"普通"}],"ln":555},{"t":"say","k":"n","text":"寄居蟹清了清喉嚨。如果螃蟹有喉嚨的話。","id":"26r1bp","ln":557},{"t":"say","k":"d","who":"珊婆","text":"「孫家的丫頭。」","ln":559,"id":"d517g9"},{"t":"say","k":"d","who":"孫承完","text":"「……妳知道我姓孫？」","ln":561,"id":"or4cf"},{"t":"say","k":"d","who":"珊婆","text":"「我知道的可多了。」","ln":563,"id":"jfc7tk"},{"t":"say","k":"d","who":"珊婆","text":"「妳唱的那首歌，妳知道是誰寫的嗎？」","ln":565,"id":"1akd9pf"},{"t":"say","k":"d","who":"孫承完","text":"「……奶奶說，是很久以前的漁夫留下來的。」","ln":567,"id":"uczd5o"},{"t":"say","k":"d","who":"珊婆","text":"「三百年前，白鹽灣有一個很會唱歌的漁夫。每個月圓的晚上，他都會走進海裡，對著海唱歌。」","ln":569,"id":"cuzlke"},{"t":"say","k":"d","who":"珊婆","text":"「那時候，人類和人魚有一個約定，叫做潮約。人類走進海裡唱歌，把歌息送給人魚；人魚保佑漁船平安回家。」","ln":571,"id":"1kxqbcz"},{"t":"say","k":"d","who":"珊婆","text":"「後來人類聽信了吃人魚肉會長生不老的傳說，開始獵捕人魚。那個漁夫，為了把一隻他喜歡的人魚藏起來，死在了自己人的網子裡。」","ln":573,"id":"oce2vb"},{"t":"say","k":"n","text":"珊婆的聲音很平靜。平靜得像在說別人的事。","id":"eplow8","ln":575},{"t":"say","k":"d","who":"珊婆","text":"「他姓孫。」","ln":577,"id":"1ea1ije"},{"t":"say","k":"n","text":"我愣住了。","id":"1c5va8f","ln":579},{"t":"say","k":"d","who":"孫承完","text":"「……那隻人魚——」","ln":581,"expr":"驚訝","id":"1olkx8e"},{"t":"say","k":"d","who":"珊婆","text":"「是我。」","ln":583,"id":"18gh21s"},{"t":"say","k":"n","text":"海浪拍在礁石上。姐姐低著頭，什麼都沒說。她早就知道了。","id":"1q3yj59","ln":585},{"t":"say","k":"d","who":"珊婆","text":"「好啦，老太婆的往事講完了。說正事。」","ln":587,"expr":"吐槽","id":"cth0u"},{"t":"say","k":"n","text":"牠用鉗子從礁石的縫隙裡，拖出了一個海螺。白色的，帶著淡淡的粉紅色，跟牠背上的殼很像。","id":"2u2d49","ln":589},{"t":"say","k":"d","who":"珊婆","text":"「採息，是人魚從人類身上拿走歌息。但是歌息還有另一種給法。」","ln":591,"id":"a3px50"},{"t":"say","k":"d","who":"珊婆","text":"「人類自己願意送出去的歌，也是歌息。」","ln":593,"id":"1ud8mbf"},{"t":"say","k":"d","who":"珊婆","text":"「孫家的丫頭，把妳的歌唱進這個海螺裡。如果妳願意把它送給這個笨公主，她就不用變成泡沫了。」","ln":595,"id":"boycix"},{"t":"say","k":"n","text":"我看著那個海螺。","id":"1q8d29x","ln":597},{"t":"say","k":"d","who":"孫承完","text":"「……就這樣？」","ln":599,"id":"19beu5g"},{"t":"say","k":"d","who":"珊婆","text":"「就這樣。不痛，不發燒，也不會長白頭髮。」","ln":601,"id":"a6ydxg"},{"t":"say","k":"d","who":"珊婆","text":"「只是，送出去的歌裡，裝著妳的壽命。這個笨公主把海螺喝下去的那一刻，妳就會少活五年。」","ln":603,"id":"1rdmuj9"},{"t":"say","k":"d","who":"孫承完","text":"「……少活五年？」","ln":605,"id":"12a0vz9"},{"t":"say","k":"d","who":"珊婆","text":"「本來能活到八十歲，就只能活到七十五歲。鏡子裡看不出來，身體也感覺不到。只是妳人生最後的那五年，沒有了。」","ln":607,"id":"1f8mr5o"},{"t":"say","k":"d","who":"珊婆","text":"「在她喝下去之前，那五年都還是妳的。」","ln":609,"id":"m694a2"},{"t":"say","k":"d","who":"孫承完","text":"「那為什麼不早說！」","ln":611,"id":"1g6y71u"},{"t":"say","k":"d","who":"珊婆","text":"「因為這個笨公主一直不准我說。她說，要是讓妳知道了，妳一定會想都不想就把五年給她。」","ln":613,"expr":"吐槽","id":"17dkn08"},{"t":"say","k":"n","text":"我轉頭看姐姐。","id":"151mvn3","ln":615},{"t":"say","k":"n","text":"她別開了臉。","id":"117d1rh","ln":617},{"t":"say","k":"d","who":"孫承完","text":"「……五年而已啊。」","ln":619,"id":"ajs6yu"},{"t":"say","k":"d","who":"裴柱現","text":"「就是這樣才不准說！」","ln":621,"expr":"生氣","id":"agfaq8"},{"t":"say","k":"d","who":"裴柱現","text":"「……妳每次都這樣。先救別人，再想自己。」","ln":623,"expr":"難過","id":"q0h8zm"},{"t":"say","k":"n","text":"那句話，阿英也說過。","id":"221prd","ln":625},{"t":"say","k":"n","text":"我接過海螺，把它貼在嘴邊。","id":"18579zz","ln":627},{"t":"say","k":"n","text":"我唱了奶奶的漁歌。從第一段，唱到第二段。","id":"6bzlab","ln":629},{"t":"say","k":"d","who":"孫承完","text":"「♪ 月亮落進海裡頭——潮水把歌帶著走——」","ln":631,"id":"1n02o3l"},{"t":"say","k":"d","who":"孫承完","text":"「♪ 海裡的姑娘別哭泣——我的歌，給妳留——」","ln":633,"id":"26mdtr"},{"t":"say","k":"n","text":"海螺在我手裡，慢慢地亮了起來。很淡、很溫暖的光，像燈塔的光，被裝進了一個小小的殼裡。","id":"psb45a","ln":635},{"t":"say","k":"n","text":"我把它遞給姐姐。","id":"1e8inmb","ln":637},{"t":"say","k":"n","text":"她看著那個海螺，很久都沒有伸手。","id":"4v0pm7","ln":639},{"t":"jump","to":"5-5","ln":641},{"t":"label","id":"5-5","title":"前夜","ln":643},{"t":"hide","all":true,"ln":645},{"t":"form","list":[{"c":"裴柱現","f":null}],"ln":646},{"t":"bg","name":"燈塔・夜","ln":647},{"t":"bgm","name":"心動（安靜版）","ln":648},{"t":"say","k":"n","text":"三月二十八日，最後一個晚上。","id":"19m89lm","ln":650},{"t":"say","k":"n","text":"姐姐上岸了。她坐在燈塔的欄杆旁邊，雙腿晃啊晃的，看著海。海螺被她用一條細繩串起來，掛在脖子上。","id":"h7kr5d","ln":652},{"t":"say","k":"n","text":"她收下了。可是她還沒有說，要不要用它。","id":"4b5w9d","ln":654},{"t":"show","list":[{"c":"裴柱現","e":"普通"}],"ln":656},{"t":"say","k":"d","who":"裴柱現","text":"「明天晚上，二姊會來。」","ln":658,"id":"13gfr2x"},{"t":"say","k":"d","who":"孫承完","text":"「那個銀頭髮的？」","ln":660,"id":"1uipgla"},{"t":"say","k":"d","who":"裴柱現","text":"「嗯。她叫澪。她會來帶我回去。」","ln":662,"id":"5g10na"},{"t":"say","k":"d","who":"孫承完","text":"「……那明天，我幫妳過生日。」","ln":664,"id":"b6bqod"},{"t":"say","k":"n","text":"她轉頭看我。","id":"dbkxqw","ln":666},{"t":"say","k":"d","who":"孫承完","text":"「蛋糕、蠟燭，還有生日快樂歌。我答應過妳的。」","ln":668,"id":"11g2ftg"},{"t":"say","k":"d","who":"孫承完","text":"「三百五十根蠟燭可能插不下，我們就插三十五根。四捨五入。」","ln":670,"id":"166pxfd"},{"t":"say","k":"n","text":"她大笑。笑得肩膀一直抖。","id":"jxtfmf","ln":672},{"t":"say","k":"n","text":"笑完之後，她把頭靠在我的肩膀上。","id":"ivusmp","ln":674},{"t":"say","k":"d","who":"裴柱現","text":"「承完。」","ln":676,"id":"q35dm7"},{"t":"say","k":"d","who":"孫承完","text":"「嗯。」","ln":678,"id":"f092ln"},{"t":"say","k":"d","who":"裴柱現","text":"「如果明天，我變成泡沫的話——」","ln":680,"id":"1nj3doo"},{"t":"say","k":"d","who":"孫承完","text":"「不會的。」","ln":682,"id":"3wc6du"},{"t":"say","k":"n","text":"我打斷她。","id":"1r9k7n5","ln":684},{"t":"say","k":"d","who":"孫承完","text":"「妳有海螺了。不會的。」","ln":686,"id":"eyex5x"},{"t":"say","k":"n","text":"她沒有回答。","id":"1ym36hv","ln":688},{"t":"say","k":"n","text":"燈塔的光，一圈一圈地掃過整片黑色的海。","id":"nh7aue","ln":690},{"t":"say","k":"n","text":"風開始變大了。遠遠的海平線那邊，雲層很厚，很低，壓得像一面牆。","id":"1m05bsg","ln":692},{"t":"say","k":"n","text":"是暴風雨要來了。","id":"4slks1","ln":694},{"t":"chend","text":"第五章　完","ln":696}]},{"key":"06_第六章_三月二十九日","name":"06_第六章_三月二十九日.md","route":"main","num":6,"title":"第六章　三月二十九日","ops":[{"t":"title","text":"第六章　三月二十九日","card":true,"ln":1},{"t":"label","id":"6-1","title":"準備","ln":3},{"t":"bg","name":"白鹽灣商店街・白天","ln":5},{"t":"bgm","name":"白鹽灣日常","ln":6},{"t":"say","k":"n","text":"三月二十九日。","id":"17blbiq","ln":8},{"t":"say","k":"n","text":"早上的收音機說，今晚有一個很強的暴風雨會從外海靠近。漁船全部回港，海灘封閉，救生站暫停值勤。","id":"1va9t69","ln":10},{"t":"say","k":"n","text":"我請了假。","id":"12htjlz","ln":12},{"t":"say","k":"n","text":"我去鎮上唯一一家麵包店訂了蛋糕。老闆問我要寫什麼字，我想了很久。","id":"1fgrudn","ln":14},{"t":"show","list":[{"c":"老闆","e":"普通"}],"ln":16},{"t":"say","k":"d","who":"孫承完","text":"「……姐姐，生日快樂。」","ln":18,"id":"j0p5gg"},{"t":"say","k":"d","who":"老闆","text":"「就這樣？」","ln":20,"id":"12hpv6w"},{"t":"say","k":"d","who":"孫承完","text":"「就這樣。」","ln":22,"id":"ckgiou"},{"t":"hide","list":["老闆"],"ln":24},{"t":"say","k":"n","text":"走出麵包店，康和阿英在門口等我。","id":"aub5b7","ln":26},{"t":"show","list":[{"c":"康","e":"大笑"},{"c":"阿英","e":"普通"}],"ln":28},{"t":"say","k":"d","who":"康","text":"「承完！我買到蠟燭了！」","ln":30,"expr":"大笑","id":"8vg073"},{"t":"say","k":"n","text":"她舉起一個塑膠袋，裡面是一大把彩色的生日蠟燭。","id":"18m6yqs","ln":32},{"t":"say","k":"d","who":"康","text":"「老闆問我要幾根，我說三百五十根，他說沒有那麼多。」","ln":34,"id":"1l5qn3x"},{"t":"say","k":"d","who":"孫承完","text":"「……妳為什麼會知道三百五十？」","ln":36,"id":"9cpub2"},{"t":"say","k":"d","who":"康","text":"「阿英說的。阿英還說『四捨五入是三十五』，我不懂什麼意思，所以兩種都問了。」","ln":38,"expr":"普通","id":"1d9e28"},{"t":"say","k":"n","text":"我轉頭看阿英。阿英含著薄荷糖，若無其事地看著天空。","id":"181ijvd","ln":40},{"t":"say","k":"d","who":"阿英","text":"「我開酒吧十年了。」","ln":42,"expr":"普通","id":"1m0xmmn"},{"t":"say","k":"d","who":"阿英","text":"「一個人喝醉的時候說了什麼，清醒的時候說了什麼，我分得出來。」","ln":44,"id":"qa4nuv"},{"t":"say","k":"d","who":"孫承完","text":"「……姐姐喝醉過？」","ln":46,"id":"rme5sk"},{"t":"say","k":"d","who":"阿英","text":"「喝了一杯梅酒，就抱著吧檯哭著說她三百五十歲，說人類的湯很燙。」","ln":48,"id":"1edcepi"},{"t":"say","k":"d","who":"阿英","text":"「……唉了一整晚，可是一滴眼淚都沒有。」","ln":50,"id":"3ul80i"},{"t":"say","k":"n","text":"我說不出話來。","id":"qj0njr","ln":52},{"t":"say","k":"n","text":"阿英把一個小紙袋塞到我手裡。","id":"9f8e71","ln":54},{"t":"say","k":"d","who":"阿英","text":"「給她的生日禮物。」","ln":56,"expr":"認真","id":"15bwrnt"},{"t":"say","k":"n","text":"我打開。是一個玻璃瓶，裡面裝著清清的水。","id":"1rac5po","ln":58},{"t":"say","k":"d","who":"阿英","text":"「山上的泉水。她好像很喜歡淡水。」","ln":60,"id":"zvc4oq"},{"t":"say","k":"d","who":"孫承完","text":"「……阿英。」","ln":62,"expr":"笑","id":"52cqm9"},{"t":"say","k":"d","who":"阿英","text":"「幹嘛。」","ln":64,"id":"1qbnmun"},{"t":"say","k":"d","who":"孫承完","text":"「謝謝。」","ln":66,"id":"10o0z9z"},{"t":"say","k":"n","text":"阿英別開臉。康在旁邊偷偷看著阿英，笑得好溫柔。","id":"jsndf7","ln":68},{"t":"if","cond":[[{"s":"採息","op":">=","v":2}]],"to":"6-1B","ln":70},{"t":"jump","to":"6-2","ln":71},{"t":"label","id":"6-1B","title":"約定","ln":73},{"t":"say","k":"n","text":"我們往燈塔的方向走。走到上坡的時候，我停下來喘了好一會兒。","id":"1qxobp0","ln":75},{"t":"say","k":"n","text":"心臟跳得好快。腿好軟。才走幾步路而已。","id":"1tpdxr0","ln":77},{"t":"show","list":[{"c":"阿英","e":"擔心"}],"ln":79},{"t":"say","k":"d","who":"阿英","text":"「承完。」","ln":81,"id":"16qylso"},{"t":"say","k":"d","who":"孫承完","text":"「……我沒事。」","ln":83,"id":"1iecenx"},{"t":"say","k":"d","who":"阿英","text":"「妳鬢角的白頭髮，比上禮拜又多了。」","ln":85,"id":"1w1bxly"},{"t":"say","k":"n","text":"她抓住我的手臂，抓得很用力。","id":"ozdb0s","ln":87},{"t":"say","k":"d","who":"阿英","text":"「今天晚上暴風雨。答應我，不管發生什麼事，妳都不准下海。」","ln":89,"expr":"認真","id":"ilpblf"},{"t":"say","k":"d","who":"孫承完","text":"「……」","ln":91,"id":"mdw26f"},{"t":"say","k":"d","who":"阿英","text":"「承完。答應我。」","ln":93,"id":"p3oguo"},{"t":"say","k":"n","text":"我看著她。她的眼睛紅紅的。認識她二十年，我第一次看她這樣。","id":"1glmbn3","ln":95},{"t":"say","k":"d","who":"孫承完","text":"「……好。我答應妳。」","ln":97,"id":"1lfyot7"},{"t":"say","k":"d","who":"康","text":"「我也要！我也要她答應！」","ln":99,"expr":"慌張","id":"1ykucc2"},{"t":"say","k":"d","who":"孫承完","text":"「好，也答應妳。」","ln":101,"expr":"笑","id":"tqyejb"},{"t":"jump","to":"6-2","ln":103},{"t":"label","id":"6-2","title":"生日","ln":105},{"t":"hide","all":true,"ln":107},{"t":"bg","name":"孫承完的房間・夜","ln":108},{"t":"bgm","name":"心動","ln":109},{"t":"se","names":["雨（室內）"],"ln":110},{"t":"say","k":"n","text":"天黑之後，雨開始下了。","id":"11agzaw","ln":112},{"t":"say","k":"n","text":"窗外的風越來越大，燈塔的光在雨幕裡一圈一圈地轉，照得窗戶上的雨點閃閃發亮。","id":"osad8z","ln":114},{"t":"say","k":"n","text":"姐姐坐在我家的小餐桌旁邊，看著桌上的蛋糕。","id":"1f6g26x","ln":116},{"t":"show","list":[{"c":"裴柱現","e":"普通"}],"ln":118},{"t":"say","k":"n","text":"蛋糕上用巧克力寫著「姐姐，生日快樂」。生怕浪費每一個空間般插著三十五根蠟燭，是康堅持要插的。旁邊放著阿英送的那瓶泉水。","id":"ysgurn","ln":120},{"t":"say","k":"d","who":"裴柱現","text":"「……這就是人類的生日。」","ln":122,"id":"qkgh2d"},{"t":"say","k":"d","who":"孫承完","text":"「嗯。要先唱歌，然後許願，最後吹蠟燭。」","ln":124,"id":"k5k2tq"},{"t":"say","k":"n","text":"我點起蠟燭。三十五個小小的火光，在昏暗的房間裡搖晃。","id":"dhzs4l","ln":126},{"t":"say","k":"n","text":"我唱了生日快樂歌。很普通、全世界的人都會唱的那一首，祝你生日快樂，親愛的裴柱現。","id":"c1ubke","ln":128},{"t":"say","k":"n","text":"姐姐一直看著我，從頭聽到尾。","id":"1pb1dav","ln":130},{"t":"say","k":"n","text":"唱完之後，她沒有馬上吹蠟燭。","id":"12ai349","ln":132},{"t":"say","k":"d","who":"裴柱現","text":"「……我在海裡過了三百四十九個生日。」","ln":134,"expr":"難過","id":"m13xeq"},{"t":"say","k":"d","who":"裴柱現","text":"「沒有一次，有人唱歌給我聽。」","ln":136,"id":"d2iad8"},{"t":"say","k":"d","who":"孫承完","text":"「那以後每一年，我都唱給妳聽。」","ln":138,"id":"94gmdj"},{"t":"say","k":"n","text":"她看著我。燭光在她的眼睛裡晃。","id":"12s6qme","ln":140},{"t":"say","k":"d","who":"裴柱現","text":"「……許願，要閉上眼睛嗎？」","ln":142,"id":"c79621"},{"t":"say","k":"d","who":"孫承完","text":"「嗯。而且不能說出來，說出來就不靈了。」","ln":144,"id":"1t6w1xc"},{"t":"say","k":"n","text":"她閉上眼睛，閉了很久。久到融化的蠟快要滴到蛋糕。但我們只是看著她。","id":"4kqx4","ln":146},{"t":"say","k":"n","text":"然後她吹熄了蠟燭。三十五根，一口氣。","id":"1hgeqbb","ln":148},{"t":"say","k":"n","text":"房間暗了下來。只剩燈塔的光，一圈一圈地掃過。","id":"15d1c03","ln":150},{"t":"say","k":"d","who":"裴柱現","text":"「……我許好了。」","ln":152,"expr":"笑","id":"1dxnfd"},{"t":"say","k":"d","who":"孫承完","text":"「許了什麼？」","ln":154,"id":"7hdkrj"},{"t":"say","k":"d","who":"裴柱現","text":"「妳剛剛說，說出來就不靈了。」","ln":156,"id":"iaidhx"},{"t":"say","k":"n","text":"她笑了。笑得很美，美得讓我有點想哭。","id":"ayaabe","ln":158},{"t":"say","k":"n","text":"然後，窗外傳來了一個聲音。","id":"opa1f4","ln":160},{"t":"say","k":"n","text":"不是風，不是雨。","id":"533icm","ln":162},{"t":"say","k":"n","text":"是歌。沒有歌詞、沒有旋律，很低、很冷的哼唱，從海那邊傳過來，穿過暴風雨，貼著窗戶。","id":"oci4m1","ln":164},{"t":"say","k":"n","text":"姐姐的笑容不見了。","id":"6681am","ln":166},{"t":"show","list":[{"c":"裴柱現","e":"驚慌"}],"ln":168},{"t":"say","k":"d","who":"裴柱現","text":"「……二姊來了。」","ln":170,"id":"1aat7e"},{"t":"label","id":"6-3","title":"貝刃","ln":172},{"t":"hide","all":true,"ln":174},{"t":"bg","name":"暴風雨的沙灘・夜","ln":175},{"t":"bgm","name":"暴風雨","ln":176},{"t":"se","names":["雷","雨","海浪"],"ln":177},{"t":"say","k":"n","text":"海在咆哮。","id":"16yqf6f","ln":179},{"t":"say","k":"n","text":"浪一道比一道高，撞在堤防上碎成白色的牆。雨打在臉上像小石子，風大得我幾乎站不穩。","id":"1q0c2uu","ln":181},{"t":"say","k":"n","text":"燈塔下面的礁石上，站著一個人。","id":"bkac4o","ln":183},{"t":"show","list":[{"c":"澪","e":"普通"}],"ln":185},{"t":"say","k":"n","text":"銀白色的長髮在風裡狂亂地飛著，下半身泡在翻滾的海水裡。一條銀色的、比姐姐大一倍的尾巴，在浪裡若隱若現。","id":"pgkhh7","ln":187},{"t":"say","k":"n","text":"她的身上，一滴雨都沒有沾到。","id":"1sg0wim","ln":189},{"t":"say","k":"d","who":"澪","text":"「柱現。」","ln":191,"id":"c3z9h2"},{"t":"say","k":"n","text":"姐姐走過去。我跟在她後面。寄居蟹不知道什麼時候爬到了我的肩膀上，緊緊抓著我的衣服。","id":"lw5cm3","ln":193},{"t":"show","list":[{"c":"裴柱現","e":"普通"},{"c":"澪","e":"普通"}],"ln":195},{"t":"say","k":"d","who":"澪","text":"「天亮之前，就是成年潮。」","ln":197,"id":"1inv8ag"},{"t":"say","k":"d","who":"澪","text":"「我來接妳回家。」","ln":199,"id":"1sw58ry"},{"t":"say","k":"n","text":"她伸出手。手心裡，躺著一把刀。","id":"1bljff4","ln":201},{"t":"cg","id":"11","title":"貝刃","ln":203},{"t":"say","k":"n","text":"刀身是用一整片貝殼磨成的，薄得透光，邊緣泛著珍珠的光澤。刀柄纏著海藻，鑲著一顆深藍色的珠子。","id":"jxsl4d","ln":205},{"t":"say","k":"d","who":"澪","text":"「這是貝刃。刺進陸果的心口，她剩下的歌息會一滴不剩地流進妳的身體。」","ln":207,"id":"161fqgv"},{"t":"say","k":"d","who":"澪","text":"「妳會活下來。而且活得比貝貝國裡任何人都久。」","ln":209,"id":"rt0jh1"},{"t":"say","k":"n","text":"我站在雨裡，聽著這些話，像在聽一個很遠很遠的故事。","id":"18gvrib","ln":211},{"t":"say","k":"n","text":"澪看向我。","id":"mynk51","ln":213},{"t":"say","k":"d","who":"澪","text":"「陸果。」","ln":215,"expr":"冷笑","id":"zfhg39"},{"t":"say","k":"d","who":"孫承完","text":"「我有名字。我叫孫承完。」","ln":217,"expr":"認真","id":"1tz7k3n"},{"t":"say","k":"d","who":"澪","text":"「我不需要知道食物的名字。」","ln":219,"id":"10300lu"},{"t":"cgEnd","ln":221},{"t":"if","cond":[[{"s":"採息","op":">=","v":2}]],"to":"6-3C","ln":223},{"t":"if","cond":[[{"s":"心動","op":">=","v":8},{"f":"坦白","neg":false},{"s":"採息","op":"==","v":0}]],"to":"6-3A","ln":224},{"t":"jump","to":"6-3B","ln":225},{"t":"label","id":"6-3A","title":"我不要","ln":227},{"t":"say","k":"n","text":"姐姐看著那把刀。","id":"1dbsy2t","ln":229},{"t":"say","k":"n","text":"她伸手接了過來。","id":"1nby0eh","ln":231},{"t":"say","k":"n","text":"我的心臟停了一拍。","id":"1i6jufg","ln":233},{"t":"say","k":"n","text":"然後，她轉過身，用盡全身的力氣，把它丟進了海裡。","id":"u5nxob","ln":235},{"t":"say","k":"n","text":"貝刃在空中劃出一道珍珠色的弧線，消失在黑色的浪裡。","id":"a50dls","ln":237},{"t":"show","list":[{"c":"澪","e":"怒"}],"ln":239},{"t":"say","k":"d","who":"澪","text":"「柱現！」","ln":241,"id":"4krhel"},{"t":"say","k":"n","text":"姐姐沒有理她。她走到我面前，取下掛在脖子上的海螺，掛回我的脖子上。","id":"10wi9lo","ln":243},{"t":"show","list":[{"c":"裴柱現","e":"笑"}],"ln":245},{"t":"say","k":"d","who":"孫承完","text":"「姐姐，妳在幹嘛——那是妳的——」","ln":247,"expr":"驚訝","id":"13cbm65"},{"t":"say","k":"d","who":"裴柱現","text":"「我不要。」","ln":249,"id":"18wflyf"},{"t":"say","k":"d","who":"孫承完","text":"「沒有它妳會變成泡沫的！」","ln":251,"id":"1nxyais"},{"t":"say","k":"d","who":"裴柱現","text":"「我知道。」","ln":253,"id":"me43sh"},{"t":"say","k":"n","text":"她捧著我的臉，雨水從她的睫毛上滴下來。","id":"19kf0od","ln":255},{"t":"say","k":"d","who":"裴柱現","text":"「承完，妳的白頭髮一根都沒有。我一次都沒有採成。」","ln":257,"id":"wwyap2"},{"t":"say","k":"d","who":"裴柱現","text":"「我想讓它一直這樣。」","ln":259,"id":"11wle3u"},{"t":"say","k":"d","who":"裴柱現","text":"「我不要妳的任何一年。」","ln":261,"id":"wwp0bg"},{"t":"say","k":"d","who":"澪","text":"「妳瘋了！妳會跟那個老太婆一樣——愛上人類，能有什麼好下場！」","ln":263,"expr":"怒","id":"ekwxyf"},{"t":"say","k":"n","text":"我肩膀上的寄居蟹，舉起了鉗子。","id":"4rh6wr","ln":265},{"t":"say","k":"d","who":"珊婆","text":"「我沒有變成泡沫，丫頭。」","ln":267,"id":"145f47j"},{"t":"say","k":"d","who":"珊婆","text":"「我只是失去了他。」","ln":269,"id":"17l1u9f"},{"t":"say","k":"n","text":"澪看著那隻寄居蟹，嘴唇動了動，什麼都沒有說。","id":"1v8m3mn","ln":271},{"t":"flag","names":["拒收海螺"],"ln":273},{"t":"jump","to":"6-4","ln":274},{"t":"label","id":"6-3B","title":"沉默","ln":276},{"t":"say","k":"n","text":"姐姐看著那把刀。","id":"1chu4zw","ln":278},{"t":"say","k":"n","text":"她伸手接了過來。","id":"1mhz7bk","ln":280},{"t":"say","k":"n","text":"我的心臟停了一拍。","id":"1j0inid","ln":282},{"t":"say","k":"n","text":"她握著那把刀，握了很久很久。雨水沿著刀身流下來，滴在她的手腕上。","id":"1alqv2h","ln":284},{"t":"show","list":[{"c":"裴柱現","e":"難過"}],"ln":286},{"t":"say","k":"n","text":"她沒有看我。","id":"16f4tcw","ln":288},{"t":"say","k":"d","who":"孫承完","text":"「……姐姐？」","ln":290,"id":"9dgwa0"},{"t":"say","k":"n","text":"然後，她把刀收進了帆布包裡。","id":"wfvv9o","ln":292},{"t":"say","k":"d","who":"澪","text":"「很好。」","ln":294,"expr":"冷笑","id":"1f150a6"},{"t":"say","k":"n","text":"姐姐低著頭，手按在胸前的海螺上。","id":"121rvyi","ln":296},{"t":"say","k":"n","text":"她沒有用那把刀。她也沒有把它丟掉。","id":"1c2ckjj","ln":298},{"t":"say","k":"n","text":"我不知道，她心裡在想什麼。","id":"182h3ga","ln":300},{"t":"jump","to":"6-4","ln":302},{"t":"label","id":"6-3C","title":"已經夠了","ln":304},{"t":"say","k":"n","text":"姐姐看著那把刀。","id":"1crtqov","ln":306},{"t":"say","k":"n","text":"她沒有伸手。","id":"1nimkpn","ln":308},{"t":"show","list":[{"c":"裴柱現","e":"難過"}],"ln":310},{"t":"say","k":"d","who":"裴柱現","text":"「我不需要它。」","ln":312,"id":"136s4ew"},{"t":"say","k":"d","who":"澪","text":"「什麼？」","ln":314,"id":"1j3jzg0"},{"t":"say","k":"d","who":"裴柱現","text":"「成年禮，我已經有了。」","ln":316,"id":"1d1u2v"},{"t":"say","k":"n","text":"她把手按在自己的胸口。","id":"17j9p49","ln":318},{"t":"say","k":"d","who":"裴柱現","text":"「兩次。她的歌息，已經在這裡了。」","ln":320,"id":"ev1aur"},{"t":"say","k":"n","text":"澪看著她，慢慢地收回了手。她的臉上，第一次出現了一點像是笑的表情。","id":"1y3wiyl","ln":322},{"t":"say","k":"d","who":"澪","text":"「……那就回家。」","ln":324,"id":"1njn6xd"},{"t":"say","k":"n","text":"姐姐轉過頭來看我。","id":"tfhi9e","ln":326},{"t":"say","k":"n","text":"她看了很久。看我的白頭髮、看我發白的嘴唇、看我站在雨裡一直在發抖的腿。","id":"1q2sj9a","ln":328},{"t":"say","k":"d","who":"裴柱現","text":"「……對不起。」","ln":330,"id":"13gw10p"},{"t":"say","k":"n","text":"她把脖子上的海螺取下來，放在礁石上。","id":"14112bx","ln":332},{"t":"say","k":"d","who":"裴柱現","text":"「這個，我用不到了。」","ln":334,"id":"xx51wi"},{"t":"say","k":"d","who":"孫承完","text":"「姐姐——」","ln":336,"id":"oafiwz"},{"t":"say","k":"d","who":"裴柱現","text":"「承完，答應我一件事。」","ln":338,"id":"1ccrmem"},{"t":"say","k":"d","who":"裴柱現","text":"「不准下海。」","ln":340,"id":"13t1t6t"},{"t":"say","k":"n","text":"那句話，阿英也說過。","id":"yr07v4","ln":342},{"t":"jump","to":"6-4","ln":344},{"t":"label","id":"6-4","title":"天亮之前","ln":346},{"t":"hide","all":true,"ln":348},{"t":"bg","name":"暴風雨的海・黎明前","ln":349},{"t":"bgm","name":"暴風雨","ln":350},{"t":"se","names":["雷","雨","海浪"],"ln":351},{"t":"say","k":"n","text":"天邊開始泛白了。","id":"1lnmx5t","ln":353},{"t":"say","k":"n","text":"暴風雨沒有停，可是雲層的縫隙裡，透出了一點點灰藍色的光。","id":"emco93","ln":355},{"t":"say","k":"n","text":"然後，潮水來了。","id":"1sln5iu","ln":357},{"t":"say","k":"n","text":"不是普通的浪。整片海像被什麼東西從深處拉著，開始往外退，退得又急又快。礁石露出來了，海草露出來了，然後海水又從遠方捲回來，像一隻巨大的手。","id":"b9pj8n","ln":359},{"t":"say","k":"n","text":"成年潮。","id":"rwrgxo","ln":361},{"t":"say","k":"n","text":"姐姐被那隻手捲了進去。","id":"12sjsiz","ln":363},{"t":"say","k":"d","who":"孫承完","text":"「姐姐——！」","ln":365,"expr":"驚訝","id":"1vn3gi"},{"t":"say","k":"n","text":"她的雙腿在海水裡合起來，變成了尾巴。浪把她往外帶，越帶越遠。她在浪裡回過頭來看我，越來越小、越來越遠。","id":"1xwioeo","ln":367},{"t":"if","cond":[[{"f":"拒收海螺","neg":false}]],"to":"6-4A","ln":369},{"t":"jump","to":"6-4B","ln":370},{"t":"label","id":"6-4A","title":"泡沫","ln":372},{"t":"say","k":"n","text":"然後我看見了。","id":"1mlblgz","ln":374},{"t":"say","k":"n","text":"她的尾鰭，在變成泡沫。","id":"7x9f0s","ln":376},{"t":"say","k":"n","text":"從最末端開始，那些薄得像紗的鰭，一點一點地化開，變成細細的、白色的泡沫，被浪一捲就散了。","id":"vawb28","ln":378},{"t":"say","k":"n","text":"天越來越亮。泡沫越爬越高。","id":"yddfoz","ln":380},{"t":"say","k":"n","text":"她沒有掙扎。她只是看著我，在越來越亮的天光裡，對我笑。","id":"7lb1rq","ln":382},{"t":"jump","to":"6-4C","ln":384},{"t":"label","id":"6-4B","title":"遠去","ln":386},{"t":"say","k":"n","text":"她在浪裡越漂越遠。","id":"1mt07a4","ln":388},{"t":"say","k":"n","text":"暴風雨把海攪得一片混亂，她的頭在浪尖上一下出現、一下消失。","id":"9a6jn2","ln":390},{"t":"say","k":"n","text":"我不知道她是在回家，還是在被海帶走。","id":"gcg0u5","ln":392},{"t":"jump","to":"6-4C","ln":394},{"t":"label","id":"6-4C","title":"岸邊","ln":396},{"t":"cg","id":"12","title":"暴風雨中的救生員","ln":398},{"t":"say","k":"n","text":"我站在浪花邊。","id":"9vqq5n","ln":400},{"t":"say","k":"n","text":"雨打在我臉上，風把我的衣服吹得獵獵作響。脖子上的哨子在胸前晃。","id":"1dclb7z","ln":402},{"t":"say","k":"n","text":"二十年了。","id":"i9qbm9","ln":404},{"t":"say","k":"n","text":"十二歲那年，我站在這片沙灘上，看著爸爸的船消失在暴風雨裡。我什麼都做不了。","id":"12u9pu9","ln":406},{"t":"say","k":"n","text":"從那天起，我每天都在這片沙灘上。吹哨子、叮嚀遊客、跳進海裡把人拉回來。我發誓再也不讓海帶走任何人。","id":"o5cgxw","ln":408},{"t":"say","k":"n","text":"現在，海要帶走她了。","id":"nifj4f","ln":410},{"t":"choice","title":"選擇⑩","options":[{"key":"A","text":"衝進海裡","to":"6-5A"},{"key":"B","text":"留在岸上，目送她","to":"6-5B"}],"ln":412},{"t":"label","id":"6-5A","title":"衝進海裡","ln":416},{"t":"if","cond":[[{"s":"心動","op":">=","v":8},{"f":"坦白","neg":false},{"s":"採息","op":"==","v":0}]],"to":"E1","ln":418},{"t":"if","cond":[[{"s":"採息","op":">=","v":2}]],"to":"E3","ln":419},{"t":"jump","to":"E2-dive","ln":420},{"t":"label","id":"6-5B","title":"留在岸上","ln":422},{"t":"if","cond":[[{"f":"拒收海螺","neg":false}]],"to":"E2-throw","ln":424},{"t":"jump","to":"E2-watch","ln":425}]},{"key":"07_結局","name":"07_結局.md","route":"main","num":7,"title":"結局","ops":[{"t":"title","text":"結局","card":true,"ln":1},{"t":"label","id":"E1","title":"珍珠之淚","ln":5},{"t":"cgEnd","ln":7},{"t":"form","list":[{"c":"裴柱現","f":"人魚"}],"ln":8},{"t":"bg","name":"暴風雨的海・黎明前","ln":9},{"t":"bgm","name":"暴風雨","ln":10},{"t":"say","k":"n","text":"我衝進海裡。","id":"15is5pt","ln":12},{"t":"say","k":"n","text":"浪打在我身上，像一堵牆。我被打退了一步，又往前衝。海水灌進我的嘴巴、鼻子，鹹得發苦。","id":"1akmaw4","ln":14},{"t":"say","k":"i","text":"（……我是救生員。）","id":"zp1y44","ln":16},{"t":"say","k":"n","text":"我游。用盡全身的力氣游。穿過一道浪，又一道浪。","id":"mmugox","ln":18},{"t":"say","k":"n","text":"她就在前面。","id":"nh81x6","ln":20},{"t":"say","k":"n","text":"她的尾巴已經化掉一半了。白色的泡沫在她身邊一圈一圈地散開，像一件正在融化的白紗。","id":"jrr6e","ln":22},{"t":"show","list":[{"c":"裴柱現","e":"驚慌"}],"ln":24},{"t":"say","k":"d","who":"裴柱現","text":"「承完！妳回去！妳會死的！」","ln":26,"id":"1kpghoi"},{"t":"say","k":"n","text":"我抓住她了。","id":"1xsinzn","ln":28},{"t":"say","k":"n","text":"我從背後抱住她，就像第一次在海裡抱住她的時候那樣。","id":"ju7flg","ln":30},{"t":"say","k":"d","who":"孫承完","text":"「放鬆。我抓住妳了。」","ln":32,"id":"1ucgdw8"},{"t":"say","k":"d","who":"裴柱現","text":"「笨蛋……妳這個笨蛋……」","ln":34,"expr":"難過","id":"rm7igc"},{"t":"say","k":"n","text":"她在我懷裡發抖。她的身體好輕，輕得像隨時會變成泡沫，從我的手臂之間流走。","id":"ke9no0","ln":36},{"t":"say","k":"n","text":"我該怎麼辦？","id":"1qvrqhp","ln":38},{"t":"say","k":"n","text":"我不會魔法。我沒有貝刃。我唯一有的，只有——","id":"18x7bxb","ln":40},{"t":"say","k":"i","text":"（……奶奶。）","id":"yaszw3","ln":42},{"t":"say","k":"i","text":"（奶奶說，第二段是唱給真的在聽的人的。）","id":"phor2q","ln":44},{"t":"say","k":"i","text":"（等到潮水回來時——）","id":"is4jgw","ln":46},{"t":"say","k":"i","text":"（我走進海裡——）","id":"ad2z2e","ln":48},{"t":"say","k":"n","text":"我抱緊她。在暴風雨的正中央，在翻滾的海水裡，我張開嘴。","id":"v8ecdi","ln":50},{"t":"bgm","name":"營火之歌","ln":52},{"t":"say","k":"d","who":"孫承完","text":"「♪ 月亮落進海裡頭——潮水把歌帶著走——」","ln":54,"id":"1h215f3"},{"t":"say","k":"n","text":"浪打過來。我嗆了一口水，繼續唱。","id":"6k4aev","ln":56},{"t":"say","k":"d","who":"孫承完","text":"「♪ 海裡的姑娘別哭泣——我的歌，給妳留——」","ln":58,"id":"177i82l"},{"t":"say","k":"n","text":"她不抖了。","id":"l29js1","ln":60},{"t":"say","k":"d","who":"孫承完","text":"「♪ 船兒出海莫回頭——浪花替我牽妳手——」","ln":62,"id":"bvlbhq"},{"t":"say","k":"n","text":"我感覺到了。海在發光。","id":"15ywqzl","ln":64},{"t":"say","k":"n","text":"跟春潮祭那天一樣，淡藍色的光從很深很深的地方浮上來，一圈一圈，像在呼吸。整片海灣都亮了。","id":"1nvcw2c","ln":66},{"t":"say","k":"d","who":"孫承完","text":"「♪ 等到潮水回來時——」","ln":68,"id":"abmk4r"},{"t":"say","k":"d","who":"孫承完","text":"「♪ 我走進海裡——換妳唱——」","ln":70,"id":"nzul2a"},{"t":"say","k":"n","text":"泡沫停住了。","id":"ty7u1e","ln":72},{"t":"say","k":"n","text":"然後，它們開始往回流。","id":"1kxseu8","ln":74},{"t":"say","k":"n","text":"那些白色的、細細的泡沫，一顆一顆地飄回來，貼回她的尾巴上，變回鱗片、變回鰭。深藍的、淺藍的、銀的，在發光的海水裡，比任何時候都還要亮。","id":"z32yq7","ln":76},{"t":"say","k":"n","text":"暴風雨的雲層，裂開了一道縫。","id":"j7pdte","ln":78},{"t":"say","k":"n","text":"太陽出來了。","id":"itnilu","ln":80},{"t":"bgm","name":"結局曲","ln":82},{"t":"bg","name":"黎明的海","ln":83},{"t":"say","k":"n","text":"金色的光鋪在海面上，從海平線一直鋪到我們身邊。","id":"j21udx","ln":85},{"t":"say","k":"n","text":"姐姐在我懷裡轉過身來，看著我。","id":"hdpxoj","ln":87},{"t":"say","k":"n","text":"她的眼眶紅了。","id":"a80f5r","ln":89},{"t":"say","k":"n","text":"然後，有什麼東西，從她的眼角滑了下來。","id":"1oeacd9","ln":91},{"t":"cg","id":"13","title":"珍珠之淚","ln":93},{"t":"say","k":"n","text":"一滴眼淚。","id":"xuf8ex","ln":95},{"t":"say","k":"n","text":"它從她的眼角滑出來，滑過那顆痣，滑過她的臉頰，在落進海裡之前，在晨光裡凝成了一顆小小的、圓圓的珍珠。","id":"rn5dk2","ln":97},{"t":"say","k":"n","text":"又一滴。又一滴。","id":"1j1r05j","ln":99},{"t":"say","k":"n","text":"珍珠一顆一顆地落下來，落在我的手心裡，溫溫的。","id":"1np4zqz","ln":101},{"t":"say","k":"d","who":"裴柱現","text":"「……我在哭？」","ln":103,"expr":"哭","id":"1kk3q02"},{"t":"say","k":"d","who":"孫承完","text":"「嗯。」","ln":105,"expr":"笑","id":"dhodpt"},{"t":"say","k":"d","who":"裴柱現","text":"「我在哭……承完，我在哭……」","ln":107,"expr":"哭","id":"y7oksc"},{"t":"say","k":"n","text":"她一邊哭一邊笑，笑得那麼唐突，卻又那麼美。上岸以來第一次的眼淚，像是要把所有沒哭出來的份一次哭完。","id":"g8f3wq","ln":109},{"t":"say","k":"n","text":"我抱著她，在發光的海裡，一起哭、一起笑。","id":"q1g0n7","ln":111},{"t":"say","k":"n","text":"然後，她張開了嘴。","id":"3kvppy","ln":113},{"t":"say","k":"d","who":"裴柱現","text":"「♪ 月亮……落進海裡頭——」","ln":115,"id":"1ur42uv"},{"t":"say","k":"n","text":"她在唱歌。","id":"d5kfmj","ln":117},{"t":"say","k":"n","text":"走音了。走得很嚴重。節拍也不對，有一個字還唱錯了。","id":"4r21b","ln":119},{"t":"say","k":"n","text":"可是那是歌。有歌詞、有旋律、有感情的，真正的歌。","id":"d4okbs","ln":121},{"t":"say","k":"d","who":"裴柱現","text":"「♪ 潮水……把歌帶著走——」","ln":123,"id":"1bxxyk4"},{"t":"say","k":"n","text":"「我走進海裡，換妳唱。」","id":"f58mn6","ln":125},{"t":"say","k":"n","text":"原來是這個意思。","id":"b575sj","ln":127},{"t":"cgEnd","ln":129},{"t":"label","id":"E1-2","title":"潮約","ln":131},{"t":"bg","name":"礁石海岸・清晨","ln":133},{"t":"bgm","name":"結局曲","ln":134},{"t":"say","k":"n","text":"我們回到礁石邊的時候，澪還在那裡。","id":"drrbkc","ln":136},{"t":"show","list":[{"c":"澪","e":"普通"},{"c":"珊婆","e":"普通"}],"ln":138},{"t":"say","k":"n","text":"她看著我們。看著姐姐完好的尾巴，看著我手心裡的珍珠。她的表情很複雜，像是有什麼東西在她心裡碎掉了，又有什麼東西長了出來。","id":"ohauuo","ln":140},{"t":"say","k":"n","text":"寄居蟹蹲在礁石上，沒有說話。","id":"1hcuj8n","ln":142},{"t":"say","k":"d","who":"珊婆","text":"「……三百年了。」","ln":144,"id":"zmztu7"},{"t":"say","k":"n","text":"牠的聲音在發抖。","id":"14guv70","ln":146},{"t":"say","k":"d","who":"珊婆","text":"「三百年來，第一次有人類走進海裡唱歌。」","ln":148,"id":"q6zwkq"},{"t":"say","k":"d","who":"珊婆","text":"「潮約，回來了。」","ln":150,"id":"1x2dsnu"},{"t":"say","k":"n","text":"澪轉過頭來，看著我。","id":"88fgf8","ln":152},{"t":"say","k":"d","who":"澪","text":"「……孫承完。」","ln":154,"id":"a53x66"},{"t":"say","k":"n","text":"她第一次叫了我的名字。","id":"16cnm9x","ln":156},{"t":"say","k":"d","who":"澪","text":"「好好照顧我妹妹。」","ln":158,"id":"12esjy1"},{"t":"say","k":"n","text":"她沉進海裡，銀色的尾巴在晨光裡一閃，消失了。","id":"dvntcp","ln":160},{"t":"hide","list":["澪"],"ln":162},{"t":"say","k":"n","text":"珊婆告訴我們，潮約恢復之後，姐姐不會再變成泡沫了。她可以在陸地上生活，也可以隨時回到海裡。碰到海水，就變回尾巴；回到岸上，就變回雙腿。","id":"4f1wjq","ln":164},{"t":"say","k":"d","who":"珊婆","text":"「只有一個條件。」","ln":166,"expr":"吐槽","id":"17qkv8t"},{"t":"say","k":"d","who":"珊婆","text":"「要有人一直為她唱歌。」","ln":168,"id":"klw86k"},{"t":"say","k":"d","who":"孫承完","text":"「那我唱一輩子。」","ln":170,"id":"myn272"},{"t":"say","k":"d","who":"珊婆","text":"「人類的一輩子很短。」","ln":172,"id":"20krhc"},{"t":"say","k":"d","who":"孫承完","text":"「那就唱到很長。」","ln":174,"expr":"笑","id":"qbbb6e"},{"t":"label","id":"E1-3","title":"海蝕洞","ln":176},{"t":"hide","all":true,"ln":178},{"t":"bg","name":"海蝕洞・夜","ln":179},{"t":"bgm","name":"夜","ln":180},{"t":"se","names":["海浪"],"ln":181},{"t":"say","k":"n","text":"燈塔北邊有一個海蝕洞，只有退潮的時候才進得去。","id":"7vb9e3","ln":183},{"t":"say","k":"n","text":"那天晚上，我們躲在裡面。洞口外面是平靜下來的海，月光從洞頂的裂縫灑下來，落在洞底那一池淺淺的海水上。","id":"47mtnd","ln":185},{"t":"say","k":"n","text":"姐姐的尾巴泡在水池裡，輕輕擺動。我坐在她旁邊的岩石上，腳也泡在水裡。","id":"19qwkvj","ln":187},{"t":"show","list":[{"c":"裴柱現","e":"害羞"}],"ln":189},{"t":"say","k":"d","who":"裴柱現","text":"「承完。」","ln":191,"id":"1734nw8"},{"t":"say","k":"d","who":"孫承完","text":"「嗯？」","ln":193,"id":"wfgma4"},{"t":"say","k":"d","who":"裴柱現","text":"「……妳要摸摸看嗎？」","ln":195,"id":"sysu17"},{"t":"say","k":"n","text":"她把尾巴從水裡抬起來一點點。","id":"1ik54z2","ln":197},{"t":"say","k":"d","who":"裴柱現","text":"「人魚的尾巴，從來沒有讓人類碰過。」","ln":199,"id":"l7tuzx"},{"t":"say","k":"n","text":"我伸出手，很輕很輕地放在她的鱗片上。","id":"hv9scc","ln":201},{"t":"say","k":"n","text":"涼涼的、滑滑的，像打磨過的貝殼。每一片都有一點點弧度，在我的手指底下微微地起伏，像在呼吸。","id":"qzf70o","ln":203},{"t":"say","k":"n","text":"我順著那些鱗片，一路摸到她的尾鰭。薄薄的、像紗一樣，在月光底下透著光。","id":"5z4fgq","ln":205},{"t":"say","k":"n","text":"我低下頭，吻了一下她的尾鰭。","id":"1w2xvja","ln":207},{"t":"say","k":"n","text":"她整條尾巴抖了一下，濺起一片水花。","id":"1nnbb4f","ln":209},{"t":"say","k":"d","who":"裴柱現","text":"「……妳每次都這樣。」","ln":211,"expr":"害羞","id":"z6qdd3"},{"t":"say","k":"d","who":"孫承完","text":"「怎樣？」","ln":213,"id":"lns610"},{"t":"say","k":"d","who":"裴柱現","text":"「親那些我自己都覺得很奇怪的地方。」","ln":215,"id":"sh1ekt"},{"t":"say","k":"d","who":"孫承完","text":"「因為一點都不奇怪啊。」","ln":217,"expr":"笑","id":"1wbrf0z"},{"t":"say","k":"n","text":"她看著我，看了很久。然後她靠過來，吻了我。","id":"560oqa","ln":219},{"t":"say","k":"n","text":"這一次，她的嘴唇不是涼的。","id":"lkfhk7","ln":221},{"t":"say","k":"n","text":"是溫的。跟我一樣溫。","id":"1nxyfon","ln":223},{"t":"say","k":"n","text":"我們靠在岩壁上，她的頭枕在我的肩膀上，尾巴在水池裡慢慢地擺。月光一點一點地移動，從水池移到岩壁，又從岩壁移到我們交握的手上。","id":"2vukgu","ln":225},{"t":"say","k":"d","who":"裴柱現","text":"「人魚和人類，沒有辦法一起變老。」","ln":227,"id":"q4zue7"},{"t":"say","k":"d","who":"孫承完","text":"「那妳等我一下，我慢慢老。」","ln":229,"id":"11hgb2p"},{"t":"say","k":"d","who":"孫承完","text":"「我們在中間等對方。」","ln":231,"id":"wc4ce9"},{"t":"say","k":"n","text":"她笑了。笑著笑著，眼角又掉了一顆珍珠，落進水池裡，叮的一聲。","id":"1cvnxyv","ln":233},{"t":"say","k":"d","who":"裴柱現","text":"「承完。」","ln":235,"id":"17x3gz5"},{"t":"say","k":"d","who":"裴柱現","text":"「我昨天許的願望，實現了。」","ln":237,"id":"pdrav1"},{"t":"say","k":"d","who":"孫承完","text":"「妳許了什麼？」","ln":239,"id":"7lzem3"},{"t":"say","k":"d","who":"裴柱現","text":"「說出來就不靈了。」","ln":241,"id":"1k6zqs9"},{"t":"say","k":"d","who":"孫承完","text":"「已經實現了，說出來也沒關係吧。」","ln":243,"id":"1tfzfyl"},{"t":"say","k":"n","text":"她把臉埋進我的肩膀，悶悶地說：","id":"1eq4xsy","ln":245},{"t":"say","k":"d","who":"裴柱現","text":"「……明年，還能聽妳唱生日快樂歌。」","ln":247,"expr":"害羞","id":"1xocnhw"},{"t":"say","k":"n","text":"海浪很輕很輕地拍著洞口。","id":"165tvc5","ln":249},{"t":"say","k":"n","text":"我們就這樣，一直靠在一起，一直到天亮。","id":"7pgzlw","ln":251},{"t":"trans","kind":"out","ln":253},{"t":"label","id":"E1-4","title":"一年後","ln":255},{"t":"hide","all":true,"ln":257},{"t":"form","list":[{"c":"裴柱現","f":null}],"ln":258},{"t":"bg","name":"白鹽灣沙灘・夜","ln":259},{"t":"trans","kind":"in","ln":260},{"t":"bgm","name":"營火之歌","ln":261},{"t":"se","names":["營火","海浪"],"ln":262},{"t":"say","k":"n","text":"一年後，三月二十九日。","id":"nbt47n","ln":264},{"t":"say","k":"n","text":"沙灘上又生起了營火。","id":"7ugut0","ln":266},{"t":"show","list":[{"c":"康","e":"大笑"},{"c":"阿英","e":"普通"}],"ln":268},{"t":"say","k":"n","text":"康捧著一個貝殼形狀的蛋糕跑過來，丸子頭一跳一跳。蛋糕的右下角少了一塊，邊緣很整齊。","id":"1o6nvv6","ln":270},{"t":"say","k":"d","who":"阿英","text":"「康。」","ln":272,"id":"1gwpzdx"},{"t":"say","k":"d","who":"康","text":"「試吃！是試吃！」","ln":274,"expr":"慌張","id":"1ooaktq"},{"t":"say","k":"n","text":"阿英嘆了一口氣，然後很自然地把手從下方托住康的手，幫她一起放下蛋糕。","id":"1plhzal","ln":276},{"t":"say","k":"n","text":"康整個人僵住了。蛋糕差點就掉在沙上。","id":"nwykj8","ln":278},{"t":"say","k":"d","who":"康","text":"「……阿、阿英？」","ln":280,"id":"1iw1ovk"},{"t":"say","k":"d","who":"阿英","text":"「拿穩。」","ln":282,"id":"v876f2"},{"t":"say","k":"n","text":"康紅著臉，一動也不敢動，之後傻笑了一整個晚上。","id":"rhfhvp","ln":284},{"t":"show","list":[{"c":"裴柱現","e":"笑"}],"ln":286},{"t":"say","k":"n","text":"姐姐坐在我旁邊，穿著白色的洋裝，沒有穿鞋的腳放在濕濕的沙上。浪花打上來，她的腳背閃了一下湛藍色的光，又退下去。她一點都不在意了。","id":"15hhqny","ln":288},{"t":"say","k":"n","text":"蛋糕上插著三十五根蠟燭，加一根小小的。","id":"rwsybe","ln":290},{"t":"say","k":"d","who":"孫承完","text":"「所以，姐姐今年三百五十一歲？」","ln":292,"id":"1nmk02c"},{"t":"say","k":"d","who":"裴柱現","text":"「閉嘴。」","ln":294,"expr":"生氣","id":"1p42l26"},{"t":"say","k":"d","who":"裴柱現","text":"「三十五點一。」","ln":296,"expr":"得意","id":"843snn"},{"t":"say","k":"n","text":"大家笑成一團。","id":"1tyvxxn","ln":298},{"t":"say","k":"n","text":"我唱了生日快樂歌。姐姐閉上眼睛許願，吹熄了蠟燭。","id":"1kickra","ln":300},{"t":"say","k":"n","text":"然後，她從口袋裡拿出一條項鍊，掛在我的脖子上。","id":"cmupfc","ln":302},{"t":"cg","id":"16","title":"一年後的生日","ln":304},{"t":"say","k":"n","text":"鍊子的末端，是一顆小小的珍珠。","id":"63vur5","ln":306},{"t":"say","k":"d","who":"裴柱現","text":"「這是我的第一顆眼淚。」","ln":308,"id":"umnlew"},{"t":"say","k":"d","who":"裴柱現","text":"「去年，在海裡。妳唱歌的時候。」","ln":310,"id":"kozvkt"},{"t":"say","k":"n","text":"我握著那顆珍珠。溫溫的，像她現在的手。","id":"1h3467l","ln":312},{"t":"say","k":"d","who":"裴柱現","text":"「承完。」","ln":314,"id":"17n3va6"},{"t":"say","k":"d","who":"孫承完","text":"「嗯？」","ln":316,"id":"x9ffd1"},{"t":"say","k":"d","who":"裴柱現","text":"「換我唱。」","ln":318,"id":"er3n1g"},{"t":"say","k":"n","text":"她清了清喉嚨，對著海，對著全世界，唱起了那首歌。","id":"by5nzf","ln":320},{"t":"say","k":"n","text":"還是有點走音。可是比去年好多了。","id":"ofuv8o","ln":322},{"t":"say","k":"d","who":"裴柱現","text":"「♪ 月亮落進海裡頭——潮水把歌帶著走——」","ln":324,"id":"c1og5k"},{"t":"say","k":"d","who":"裴柱現","text":"「♪ 海裡的姑娘別哭泣——我的歌，給妳留——」","ln":326,"id":"k680do"},{"t":"say","k":"n","text":"海面上，淡藍色的光，一圈一圈地亮了起來。","id":"1wi6hus","ln":328},{"t":"ending","code":"伴侶","name":"珍珠之淚","ln":330},{"t":"label","id":"E2-dive","title":"回去","ln":332},{"t":"cgEnd","ln":334},{"t":"form","list":[{"c":"裴柱現","f":"人魚"}],"ln":335},{"t":"bg","name":"暴風雨的海・黎明前","ln":336},{"t":"bgm","name":"暴風雨","ln":337},{"t":"say","k":"n","text":"我衝進海裡。","id":"14otcmw","ln":339},{"t":"say","k":"n","text":"浪打在我身上，像一堵牆。我穿過一道浪，又一道浪，終於游到了她旁邊。","id":"1kal5m2","ln":341},{"t":"show","list":[{"c":"裴柱現","e":"驚慌"}],"ln":343},{"t":"say","k":"d","who":"裴柱現","text":"「承完！妳在幹嘛！」","ln":345,"id":"1mypnmt"},{"t":"say","k":"d","who":"孫承完","text":"「救妳啊！」","ln":347,"id":"1az0xxl"},{"t":"say","k":"d","who":"裴柱現","text":"「笨蛋！妳是救生員，不是人魚！」","ln":349,"id":"1piybyv"},{"t":"say","k":"n","text":"她用尾巴一推，一道浪把我往岸的方向送回去好幾公尺。","id":"gpn307","ln":351},{"t":"say","k":"n","text":"她舉起掛在胸前的海螺，貼在嘴唇上。","id":"q5xojc","ln":353},{"t":"say","k":"n","text":"海螺亮了起來。很淡、很溫暖的光，像燈塔的光。那道光流進她的嘴裡，流過她的喉嚨，在她的胸口亮了一下，然後慢慢地暗下去。","id":"12j4xo6","ln":355},{"t":"say","k":"n","text":"那是我的歌。","id":"18dzoz6","ln":357},{"t":"say","k":"d","who":"裴柱現","text":"「……收到了。」","ln":359,"expr":"笑","id":"f8tbrf"},{"t":"say","k":"n","text":"她又推了一道浪過來。這一次，把我一路送回了淺灘。","id":"v9s6i8","ln":361},{"t":"jump","to":"E2","ln":363},{"t":"label","id":"E2-throw","title":"接住","ln":365},{"t":"cgEnd","ln":367},{"t":"form","list":[{"c":"裴柱現","f":"人魚"}],"ln":368},{"t":"bg","name":"暴風雨的海・黎明前","ln":369},{"t":"bgm","name":"暴風雨","ln":370},{"t":"say","k":"n","text":"我沒有衝進海裡。","id":"1beefwu","ln":372},{"t":"say","k":"n","text":"我把脖子上的海螺扯下來，握在手裡，退後兩步，然後用盡全身的力氣，把它往海裡丟。","id":"j6k6tc","ln":374},{"t":"say","k":"d","who":"孫承完","text":"「姐姐——！接住——！」","ln":376,"id":"f7f4gs"},{"t":"say","k":"n","text":"海螺劃過暴風雨，在灰白色的天空裡畫出一道弧線。","id":"29i4ff","ln":378},{"t":"say","k":"n","text":"她伸出手。","id":"183zskh","ln":380},{"t":"say","k":"n","text":"接住了。","id":"78291b","ln":382},{"t":"show","list":[{"c":"裴柱現","e":"驚慌"}],"ln":384},{"t":"say","k":"n","text":"她看著手上的海螺，又看著岸上的我。","id":"1f5tjep","ln":386},{"t":"say","k":"d","who":"孫承完","text":"「妳不要，我偏要給！」","ln":388,"id":"12gcglf"},{"t":"say","k":"d","who":"孫承完","text":"「我是救生員！我不准海再帶走任何人！」","ln":390,"id":"yax8jr"},{"t":"say","k":"n","text":"她看了我很久很久。","id":"de1tw8","ln":392},{"t":"say","k":"n","text":"然後，她把海螺貼在嘴唇上。","id":"1qxhv9c","ln":394},{"t":"say","k":"n","text":"海螺亮了起來。那道光流進她的身體裡，泡沫停住了，那些已經化掉的鰭，一點一點地長了回來。","id":"1xegrgl","ln":396},{"t":"say","k":"n","text":"她活下來了。","id":"65jkxy","ln":398},{"t":"say","k":"n","text":"可是海沒有發光。暴風雨也沒有停。","id":"b08dz0","ln":400},{"t":"say","k":"n","text":"那只是夠她活下去的歌。剛剛好夠。","id":"1109bpy","ln":402},{"t":"jump","to":"E2","ln":404},{"t":"label","id":"E2-watch","title":"目送","ln":406},{"t":"cgEnd","ln":408},{"t":"form","list":[{"c":"裴柱現","f":"人魚"}],"ln":409},{"t":"bg","name":"暴風雨的海・黎明前","ln":410},{"t":"bgm","name":"暴風雨","ln":411},{"t":"say","k":"n","text":"我沒有衝進海裡。","id":"1b4eu7v","ln":413},{"t":"say","k":"n","text":"我站在岸邊，看著她在浪裡越漂越遠。","id":"g45arz","ln":415},{"t":"if","cond":[[{"s":"採息","op":">=","v":2}]],"to":"E2-watch-b","ln":417},{"t":"say","k":"n","text":"她在很遠很遠的浪尖上，回過頭來看我。","id":"slctlz","ln":419},{"t":"say","k":"n","text":"然後，她舉起掛在胸前的海螺，貼在嘴唇上。","id":"1e8mde4","ln":421},{"t":"say","k":"n","text":"海螺亮了起來。很淡、很溫暖的光，像燈塔的光，在暴風雨裡亮了一下，又暗下去。","id":"cnvd78","ln":423},{"t":"say","k":"n","text":"那是我的歌。","id":"18403a7","ln":425},{"t":"say","k":"n","text":"她收下了。","id":"yucsql","ln":427},{"t":"jump","to":"E2","ln":429},{"t":"label","id":"E2-watch-b","title":"海螺","ln":431},{"t":"say","k":"n","text":"她在很遠很遠的浪尖上，回過頭來看我。","id":"svcfay","ln":433},{"t":"say","k":"n","text":"她不需要海螺。她需要的東西，早就從我身上拿走了。","id":"1oqaenk","ln":435},{"t":"say","k":"n","text":"我低頭，看見礁石上那個她留下的海螺。我把它撿起來，緊緊握在手裡。","id":"1u59st0","ln":437},{"t":"say","k":"n","text":"我答應過阿英，不下海。","id":"1d09udi","ln":439},{"t":"say","k":"n","text":"我答應過她，不下海。","id":"2tolyt","ln":441},{"t":"say","k":"n","text":"我第一次，守住了這種約定。","id":"1qu7jzd","ln":443},{"t":"jump","to":"E2","ln":445},{"t":"label","id":"E2","title":"明年見","ln":447},{"t":"bg","name":"黎明的海","ln":449},{"t":"bgm","name":"結局曲","ln":450},{"t":"say","k":"n","text":"天亮了。","id":"3wnecc","ln":452},{"t":"say","k":"n","text":"暴風雨慢慢地過去，雲層後面透出了淡淡的金色。","id":"1qnl238","ln":454},{"t":"say","k":"n","text":"姐姐浮在淺灘外面的海裡，只露出肩膀以上。就跟我生日那天晚上，第一次看見她的時候一樣。","id":"auwq0a","ln":456},{"t":"show","list":[{"c":"裴柱現","e":"普通"}],"ln":458},{"t":"say","k":"n","text":"我們隔著一段海水，看著彼此。","id":"1brtxu0","ln":460},{"t":"say","k":"d","who":"裴柱現","text":"「我要回家了。」","ln":462,"id":"18d8vhr"},{"t":"say","k":"d","who":"孫承完","text":"「……嗯。」","ln":464,"id":"11zowyh"},{"t":"say","k":"d","who":"裴柱現","text":"「貝貝國很遠。很深。」","ln":466,"id":"32ws1z"},{"t":"say","k":"d","who":"孫承完","text":"「嗯。」","ln":468,"id":"cnpkmw"},{"t":"say","k":"n","text":"我們沉默了很久。浪一下一下地拍過來，舔過我的腳背。","id":"vy840w","ln":470},{"t":"say","k":"n","text":"然後我說：","id":"1k4daig","ln":472},{"t":"say","k":"d","who":"孫承完","text":"「姐姐。」","ln":474,"expr":"笑","id":"12ds446"},{"t":"say","k":"d","who":"孫承完","text":"「明年見。」","ln":476,"id":"1insr8z"},{"t":"say","k":"n","text":"她愣了一下。","id":"1bqrahs","ln":478},{"t":"say","k":"n","text":"然後她笑了。是那種張開嘴、笑出聲音、像小孩子一樣的笑。","id":"5m9v66","ln":480},{"t":"say","k":"d","who":"裴柱現","text":"「……嗯。明年見，承完。」","ln":482,"expr":"笑","id":"1lz5x3w"},{"t":"say","k":"n","text":"她沉進了海裡。","id":"haw3h5","ln":484},{"t":"say","k":"n","text":"湛藍色的尾巴在晨光裡一閃，就不見了。","id":"gkxndn","ln":486},{"t":"hide","all":true,"ln":488},{"t":"label","id":"E2-2","title":"海螺","ln":490},{"t":"bg","name":"白鹽灣沙灘・夜","ln":492},{"t":"bgm","name":"營火之歌","ln":493},{"t":"se","names":["營火","海浪"],"ln":494},{"t":"say","k":"n","text":"一年後，二月二十一日。","id":"1s39d9r","ln":496},{"t":"say","k":"n","text":"我三十三歲了。","id":"1e6j1mn","ln":498},{"t":"say","k":"n","text":"沙灘上又生起了營火。康捧著一個救生圈形狀的蛋糕跑過來，右下角少了一塊。阿英提著一桶冰鎮啤酒，坐在我旁邊。","id":"dd2tln","ln":500},{"t":"show","list":[{"c":"康","e":"大笑"},{"c":"阿英","e":"普通"}],"ln":502},{"t":"say","k":"d","who":"康","text":"「承完，許願！」","ln":504,"id":"1veimmm"},{"t":"say","k":"n","text":"我閉上眼睛。","id":"m7g9hy","ln":506},{"t":"say","k":"i","text":"（希望今年，海也不要帶走任何人。）","id":"18iya34","ln":508},{"t":"say","k":"i","text":"（還有——）","id":"19f6ojk","ln":510},{"t":"say","k":"n","text":"我沒有把第二個願望想完。因為浪打上來了，有什麼東西碰到了我的腳。","id":"1e7uaag","ln":512},{"t":"say","k":"n","text":"我低下頭。","id":"1qzybm2","ln":514},{"t":"say","k":"n","text":"一個海螺。白色的，帶著淡淡的粉紅色，被浪花推到我的腳邊，停住了。","id":"2s4yma","ln":516},{"t":"say","k":"n","text":"我把它撿起來，貼在耳朵上。","id":"1ejnh05","ln":518},{"t":"cg","id":"14","title":"海螺","ln":520},{"t":"say","k":"n","text":"一開始，只有海浪的聲音。","id":"nxe592","ln":522},{"t":"say","k":"n","text":"然後，我聽見了。","id":"m75v0i","ln":524},{"t":"say","k":"n","text":"很笨拙、很走音的哼唱。斷斷續續的，好像唱的人很緊張，一直在換氣。","id":"1n11ov","ln":526},{"t":"say","k":"n","text":"然後，有了歌詞。","id":"1rw2f0k","ln":528},{"t":"say","k":"d","who":"？？？","text":"「♪ 月亮……落進海裡頭——」","ln":530,"id":"12ejdlf"},{"t":"say","k":"d","who":"？？？","text":"「♪ 潮水……把歌……帶著走——」","ln":532,"id":"1d4b118"},{"t":"say","k":"n","text":"走音走得好嚴重。有一個字還唱錯了。","id":"sw5omq","ln":534},{"t":"say","k":"n","text":"可是那是歌。","id":"1eiu0u5","ln":536},{"t":"say","k":"n","text":"人魚不會唱歌。她說過的。","id":"12usqdp","ln":538},{"t":"say","k":"n","text":"她學會了。","id":"lacrkb","ln":540},{"t":"say","k":"n","text":"我抱著那個海螺，在營火旁邊，笑著笑著就哭了。","id":"8netny","ln":542},{"t":"say","k":"n","text":"康慌張地把一整串烤魷魚塞到我手裡。阿英什麼都沒說，只是把面紙遞過來，然後看向海。","id":"mt1o0h","ln":544},{"t":"say","k":"n","text":"之後的每一年，二月二十一日，沙灘上都會出現一個海螺。","id":"oq88bs","ln":546},{"t":"say","k":"n","text":"每一年，那首歌都唱得比前一年好一點點。","id":"18k9yv6","ln":548},{"t":"say","k":"n","text":"我把它們排在燈塔小屋的窗台上，一個、兩個、三個。","id":"qokc7c","ln":550},{"t":"say","k":"n","text":"窗外，海很安靜。","id":"ekqxhm","ln":552},{"t":"say","k":"n","text":"安靜得像是在聽。","id":"1gp3ckk","ln":554},{"t":"say","k":"d","who":"孫承完","text":"「姐姐。」","ln":556,"id":"123sif7"},{"t":"say","k":"d","who":"孫承完","text":"「明年見。」","ln":558,"id":"1ixscxy"},{"t":"ending","code":"朋友","name":"明年見","ln":560},{"t":"label","id":"E3","title":"海裡的姑娘","ln":562},{"t":"cgEnd","ln":564},{"t":"form","list":[{"c":"裴柱現","f":"人魚"}],"ln":565},{"t":"bg","name":"暴風雨的海・黎明前","ln":566},{"t":"bgm","name":"暴風雨","ln":567},{"t":"say","k":"i","text":"（……對不起，阿英。）","id":"1yqwyhm","ln":569},{"t":"say","k":"n","text":"我衝進海裡。","id":"14ysybv","ln":571},{"t":"say","k":"n","text":"浪打在我身上，像一堵牆。我被打退了一步，又往前衝。","id":"112sh88","ln":573},{"t":"say","k":"n","text":"我的身體好重。","id":"jkuisf","ln":575},{"t":"say","k":"n","text":"手臂像灌了鉛，腿軟得踢不動水。才游了幾公尺，我就喘得像跑了一整天。","id":"rbt7ra","ln":577},{"t":"say","k":"n","text":"可是她就在前面。在浪裡，越漂越遠。","id":"elelj5","ln":579},{"t":"say","k":"i","text":"（我是救生員。）","id":"xutxio","ln":581},{"t":"say","k":"i","text":"（我不准海再帶走任何人。）","id":"1h8eopb","ln":583},{"t":"say","k":"n","text":"我游。用盡全身最後的力氣游。","id":"1o9vbu6","ln":585},{"t":"say","k":"n","text":"她回過頭來，看見了我。","id":"ykeo7i","ln":587},{"t":"show","list":[{"c":"裴柱現","e":"驚慌"}],"ln":589},{"t":"say","k":"d","who":"裴柱現","text":"「承完——！不要——！回去——！」","ln":591,"id":"14nxakg"},{"t":"say","k":"n","text":"她的臉上，是我從沒看過的恐懼。","id":"lat4ts","ln":593},{"t":"say","k":"n","text":"我朝她伸出手。","id":"5o30vv","ln":595},{"t":"say","k":"n","text":"就差一點點。","id":"1dd3tya","ln":597},{"t":"say","k":"n","text":"然後一道浪，從我的頭頂壓了下來。","id":"73lxg4","ln":599},{"t":"trans","kind":"flash","ln":601},{"t":"hide","all":true,"ln":602},{"t":"bg","name":"海中","ln":603},{"t":"bgm","stop":"stop","ln":604},{"t":"se","names":["海浪"],"ln":605},{"t":"say","k":"n","text":"好安靜。","id":"zx18ob","ln":607},{"t":"say","k":"n","text":"暴風雨的聲音不見了。浪的聲音也不見了。","id":"1kwk7qq","ln":609},{"t":"say","k":"n","text":"我在往下沉。","id":"1mz2rgc","ln":611},{"t":"say","k":"n","text":"海水是深藍色的，越往下越暗。頭頂上那片灰白色的光，越來越小、越來越遠。","id":"1jidi0w","ln":613},{"t":"say","k":"n","text":"我的腿不會動了。手也不會動了。","id":"6qhn2v","ln":615},{"t":"say","k":"i","text":"（……原來是這樣啊。）","id":"n5wpwv","ln":617},{"t":"say","k":"i","text":"（爸爸那天，也是這樣嗎？）","id":"5qpwnm","ln":619},{"t":"say","k":"n","text":"一道光從上面衝下來。","id":"21c9u9","ln":621},{"t":"say","k":"n","text":"湛藍色的。閃著銀光的。","id":"9lpud6","ln":623},{"t":"say","k":"n","text":"是她。","id":"1imhq4z","ln":625},{"t":"say","k":"n","text":"她游得好快，快得像一道閃電。她抱住我，把我往上拉。可是我好重，重得像整片海都壓在我身上。","id":"1dbhil9","ln":627},{"t":"say","k":"n","text":"她捧著我的臉，把嘴唇貼上來。","id":"9wntl1","ln":629},{"t":"say","k":"n","text":"她在吹氣。拼命地吹。","id":"kpf0vu","ln":631},{"t":"say","k":"d","who":"裴柱現","text":"「……還給妳……我全部還給妳……」","ln":633,"id":"mqz286"},{"t":"say","k":"n","text":"可是什麼都沒有回來。","id":"1cenkqt","ln":635},{"t":"say","k":"n","text":"人魚只能拿走。不能還回去。","id":"c7cd7o","ln":637},{"t":"say","k":"n","text":"她在哭。我知道她在哭，可是她沒有眼淚。她的臉皺成一團，嘴巴張著，卻一滴眼淚都沒有。","id":"16k7bd9","ln":639},{"t":"say","k":"n","text":"然後，我聽見了。","id":"lx69bj","ln":641},{"t":"say","k":"n","text":"歌聲。","id":"1fr99lx","ln":643},{"t":"say","k":"n","text":"不是那個沒有旋律的哼唱。是真正的歌。有歌詞、有旋律，走音走得好嚴重。","id":"1o9qeo3","ln":645},{"t":"say","k":"d","who":"裴柱現","text":"「♪ 月亮……落進海裡頭——」","ln":647,"id":"1v13oju"},{"t":"say","k":"i","text":"（……啊。）","id":"85wnn1","ln":649},{"t":"say","k":"d","who":"裴柱現","text":"「♪ 潮水……把歌帶著走——」","ln":651,"id":"1crwrn1"},{"t":"say","k":"i","text":"（她學會唱歌了。）","id":"ls9rdc","ln":653},{"t":"say","k":"n","text":"我好想笑。可是我已經沒有力氣了。","id":"dep576","ln":655},{"t":"say","k":"i","text":"（姐姐。）","id":"166a7hn","ln":657},{"t":"say","k":"i","text":"（海裡的姑娘，別哭泣。）","id":"89juxp","ln":659},{"t":"say","k":"i","text":"（我的歌——）","id":"si5ctc","ln":661},{"t":"say","k":"i","text":"（給妳留。）","id":"1rkutl9","ln":663},{"t":"trans","kind":"out","ln":665},{"t":"say","k":"n","text":"……","id":"1t6mbsv","ln":667},{"t":"bg","name":"全黑","ln":669},{"t":"bgm","name":"結局曲","ln":670},{"t":"say","k":"n","text":"那年春天，白鹽灣的救生員沒有回來。","id":"ymb9bf","ln":672},{"t":"say","k":"n","text":"人們在沙灘上找到她的時候，她的臉上帶著笑，好像做了這輩子最好的夢。","id":"g7ssbc","ln":674},{"t":"say","k":"n","text":"她的手裡，握著一片湛藍色的鱗。","id":"1cds3nw","ln":676},{"t":"ending","code":"BAD","name":"她把歌留給了我","ln":678}]},{"key":"人魚篇/00_序_深海的成年禮","name":"00_序_深海的成年禮.md","route":"side","num":0,"title":"人魚篇・序　深海的成年禮","ops":[{"t":"title","text":"人魚篇・序　深海的成年禮","card":true,"ln":1},{"t":"label","id":"Z0-1","title":"王座","ln":3},{"t":"bg","name":"貝貝國・王座廳","ln":5},{"t":"bgm","name":"貝貝國","ln":6},{"t":"form","list":[{"c":"裴柱現","f":"人魚"}],"ln":7},{"t":"say","k":"n","text":"我叫裴柱現。","id":"zrir3l","ln":9},{"t":"say","k":"n","text":"貝貝國的第七公主。再過三十六天，就滿三百五十歲。","id":"5lnnkw","ln":11},{"t":"cg","id":"01","title":"海底王座","ln":13},{"t":"say","k":"n","text":"貝貝國的王座廳在海溝最深的地方。這裡沒有陽光，只有珊瑚自己發出的光，一叢一叢，藍的、白的，把整座大廳照得像一個安靜的夢。","id":"29z0m5","ln":15},{"t":"say","k":"n","text":"母后坐在珊瑚王座上，看著我。","id":"8ndh38","ln":17},{"t":"say","k":"d","who":"潮后","text":"「柱現。」","ln":19,"id":"4jssne"},{"t":"say","k":"d","who":"裴柱現","text":"「是，母后。」","ln":21,"id":"1995idu"},{"t":"say","k":"d","who":"潮后","text":"「成年潮之前，帶一口人類的歌息回來。」","ln":23,"id":"tay25r"},{"t":"say","k":"n","text":"她說得很平靜。就像在吩咐我去礁石邊摘一顆海葡萄。","id":"1t0ruqw","ln":25},{"t":"say","k":"d","who":"潮后","text":"「陸果而已。挑一顆熟的，摘下來。」","ln":27,"id":"197g472"},{"t":"cgEnd","ln":29},{"t":"show","list":[{"c":"潮后","e":"普通"},{"c":"澪","e":"普通"}],"ln":30},{"t":"say","k":"n","text":"二姊游到我身邊，銀色的尾巴在我身邊繞了一圈。","id":"1imeixa","ln":32},{"t":"say","k":"d","who":"澪","text":"「別挑會唱歌的。」","ln":34,"id":"1vzr79d"},{"t":"say","k":"d","who":"裴柱現","text":"「為什麼？會唱歌的歌息不是比較多嗎？」","ln":36,"id":"5u3vgg"},{"t":"say","k":"d","who":"澪","text":"「會唱歌的人類最危險。」","ln":38,"expr":"冷笑","id":"126r0ek"},{"t":"say","k":"n","text":"她沒有解釋。她從來不解釋。","id":"1978yua","ln":40},{"t":"say","k":"n","text":"那時候我以為，她只是在嚇我。","id":"1dxbd7g","ln":42},{"t":"label","id":"Z0-2","title":"交易","ln":44},{"t":"hide","all":true,"ln":46},{"t":"bg","name":"海巫的洞窟","ln":47},{"t":"bgm","name":"夜","ln":48},{"t":"say","k":"n","text":"海巫住在王國邊緣的一個黑色洞窟裡。","id":"1t7s9sg","ln":50},{"t":"say","k":"n","text":"大家都說她很老很老，老到記得人類還會對著海唱歌的年代。大家都說她很怪，因為她從來不採息，卻一直沒有變成泡沫。","id":"dy4pzc","ln":52},{"t":"show","list":[{"c":"珊婆","e":"普通"}],"ln":54},{"t":"say","k":"d","who":"珊婆","text":"「上岸要雙腿，雙腿要拿東西換。」","ln":56,"id":"q0eull"},{"t":"say","k":"d","who":"珊婆","text":"「妳要拿什麼換？」","ln":58,"id":"wm71hm"},{"t":"say","k":"d","who":"裴柱現","text":"「聲音？故事裡都是拿聲音換的。」","ln":60,"id":"1d1jxos"},{"t":"say","k":"d","who":"珊婆","text":"「笨。妳沒了聲音，要怎麼哼誘音？要怎麼採息？」","ln":62,"expr":"吐槽","id":"n8ca24"},{"t":"say","k":"d","who":"裴柱現","text":"「……那要什麼？」","ln":64,"id":"u0znfn"},{"t":"say","k":"n","text":"珊婆看了我很久。","id":"oen7w1","ln":66},{"t":"say","k":"d","who":"珊婆","text":"「眼淚。」","ln":68,"id":"4wyjrn"},{"t":"say","k":"n","text":"我差點笑出來。","id":"3vagfq","ln":70},{"t":"say","k":"d","who":"裴柱現","text":"「我又不會哭。三百四十九年，我一次都沒哭過。」","ln":72,"id":"1xpqm8m"},{"t":"say","k":"d","who":"珊婆","text":"「那是因為妳還沒遇過值得哭的事。」","ln":74,"id":"1708daq"},{"t":"say","k":"n","text":"她伸出一隻手，按在我的眼睛上。冰冰涼涼的。","id":"8ogr72","ln":76},{"t":"say","k":"n","text":"然後，有什麼東西從我的眼睛深處被抽走了。很輕很輕，像一顆珍珠從貝殼裡滑出來。","id":"1iaw5oo","ln":78},{"t":"say","k":"d","who":"珊婆","text":"「成交。」","ln":80,"id":"1l2148d"},{"t":"say","k":"d","who":"珊婆","text":"「上岸之後，碰到淡水沒事，碰到海水會長鱗。成年潮天亮之前，帶不回歌息，妳就會變成泡沫。」","ln":82,"id":"oc5ome"},{"t":"say","k":"d","who":"裴柱現","text":"「我知道。」","ln":84,"id":"1f5xslr"},{"t":"say","k":"d","who":"珊婆","text":"「妳不知道。」","ln":86,"expr":"吐槽","id":"hotb8p"},{"t":"say","k":"n","text":"她嘆了一口氣，身體開始縮小，縮小，最後變成了一隻背著粉紅色螺殼的寄居蟹，爬上了我的肩膀。","id":"1n473py","ln":88},{"t":"say","k":"d","who":"裴柱現","text":"「……妳要跟我一起去？」","ln":90,"id":"u3p9hv"},{"t":"say","k":"d","who":"珊婆","text":"「我要親眼看看。」","ln":92,"id":"1ur4jbr"},{"t":"say","k":"d","who":"珊婆","text":"「看妳這個笨公主，會不會跟我一樣。」","ln":94,"id":"1lb0m6y"},{"t":"label","id":"Z0-3","title":"歌","ln":96},{"t":"hide","all":true,"ln":98},{"t":"bg","name":"白鹽灣海面・夜","ln":99},{"t":"bgm","stop":"stop","ln":100},{"t":"se","names":["海浪","營火"],"ln":101},{"t":"say","k":"n","text":"二月二十一日的晚上，我第一次浮上海面。","id":"1kr5zwh","ln":103},{"t":"say","k":"n","text":"月亮好亮。比珊瑚的光亮好多。","id":"115x10z","ln":105},{"t":"say","k":"n","text":"岸邊有一堆火。火旁邊坐著幾個人類，在吃東西、在笑。有一個圓臉的人類一直在吃，有一個綁著高馬尾的人類一直在罵那個圓臉的。","id":"18m600z","ln":107},{"t":"say","k":"i","text":"（……就從這幾顆裡面挑吧。）","id":"ty31gb","ln":109},{"t":"say","k":"n","text":"我游近了一點。","id":"1j3mbho","ln":111},{"t":"say","k":"n","text":"然後，其中一個人類拿起了一個木頭做的東西，撥了一下。","id":"5qxxdg","ln":113},{"t":"bgm","name":"營火之歌","ln":115},{"t":"say","k":"d","who":"孫承完","text":"「♪ 月亮落進海裡頭——」","ln":117,"id":"qremf7"},{"t":"say","k":"n","text":"我停住了。","id":"1uz5qvg","ln":119},{"t":"say","k":"d","who":"孫承完","text":"「♪ 潮水把歌帶著走——」","ln":121,"id":"wouky8"},{"t":"say","k":"n","text":"那是什麼？","id":"5n14lx","ln":123},{"t":"say","k":"n","text":"不是誘音。不是海流的聲音，也不是鯨魚的聲音。","id":"1pjz0zm","ln":125},{"t":"say","k":"n","text":"那個聲音裡面有東西。我說不出那是什麼，可是它鑽進我的耳朵、我的胸口，在裡面輕輕地、輕輕地敲。","id":"idch6l","ln":127},{"t":"say","k":"d","who":"孫承完","text":"「♪ 海裡的姑娘別哭泣——」","ln":129,"id":"l7fow3"},{"t":"say","k":"n","text":"我伸手摸了摸自己的眼睛。","id":"1391s7u","ln":131},{"t":"say","k":"n","text":"乾的。眼淚已經給海巫了。","id":"64nmkd","ln":133},{"t":"say","k":"n","text":"可是那裡好酸。","id":"1w1grad","ln":135},{"t":"say","k":"d","who":"孫承完","text":"「♪ 我的歌，給妳留——」","ln":137,"id":"cx13ic"},{"t":"say","k":"i","text":"（……給我？）","id":"bogjyc","ln":139},{"t":"say","k":"i","text":"（她在唱給我聽？）","id":"1oheyd","ln":141},{"t":"say","k":"n","text":"她的歌停了。","id":"1i834qn","ln":143},{"t":"say","k":"n","text":"她看見我了。","id":"1vygyiq","ln":145},{"t":"say","k":"n","text":"她站起來，丟下那個木頭做的東西，朝海邊跑過來，跑進浪裡，對著我大喊：","id":"qrjump","ln":147},{"t":"say","k":"d","who":"孫承完","text":"「喂——！妳還好嗎——！」","ln":149,"id":"1p95cd"},{"t":"say","k":"n","text":"我愣住了。","id":"1ys1wdv","ln":151},{"t":"say","k":"n","text":"她以為我要溺水了。","id":"zz9gou","ln":153},{"t":"say","k":"n","text":"三百四十九年來，第一次有誰，怕我死掉。","id":"10wqqc0","ln":155},{"t":"say","k":"n","text":"我沉進水裡，游得遠遠的。心臟跳得好快，快得像要從胸口跳出去。","id":"wws3h1","ln":157},{"t":"say","k":"n","text":"肩膀上的寄居蟹，用鉗子敲了敲我的耳朵。","id":"1nt98d1","ln":159},{"t":"say","k":"d","who":"珊婆","text":"「我不是叫妳別挑會唱歌的嗎。」","ln":161,"expr":"吐槽","id":"fxzqdi"},{"t":"say","k":"d","who":"裴柱現","text":"「那是二姊說的。」","ln":163,"id":"1b6yd8s"},{"t":"say","k":"n","text":"我浮在很遠很遠的海面上，看著岸邊那個還站在浪裡、一直往這裡看的人類。","id":"1e6f4hi","ln":165},{"t":"say","k":"d","who":"裴柱現","text":"「……找到了。」","ln":167,"id":"1npbmu8"},{"t":"chend","text":"人魚篇・序　完","ln":169}]}],"labels":{"1-1":[0,7],"1-2":[0,39],"1-3":[0,92],"1-4":[0,122],"1-5A":[0,181],"1-5B":[0,218],"1-6":[0,234],"2-1":[1,1],"2-1A":[1,13],"2-1B":[1,25],"2-2":[1,47],"2-3":[1,120],"2-3A":[1,142],"2-3B":[1,168],"2-4":[1,187],"2-4A":[1,204],"2-4B":[1,244],"2-5":[1,280],"3-1":[2,1],"3-2":[2,46],"3-2A":[2,70],"3-2B":[2,86],"3-3":[2,106],"3-3A":[2,145],"3-3B":[2,153],"3-4":[2,166],"3-4A":[2,183],"3-4B":[2,201],"3-5A":[2,229],"3-5B":[2,250],"3-6":[2,288],"4-1":[3,1],"4-1B":[3,25],"4-2":[3,38],"4-3":[3,71],"4-3A":[3,82],"4-3B":[3,106],"4-4":[3,116],"4-5":[3,145],"4-5A":[3,164],"4-5B":[3,181],"4-6":[3,197],"4-6A":[3,204],"4-6B":[3,277],"4-7":[3,341],"5-0":[4,1],"5-1A":[4,10],"5-1A-1":[4,59],"5-1A-2":[4,74],"5-1B":[4,89],"5-1B-1":[4,121],"5-1B-2":[4,138],"5-1B-3":[4,158],"5-2":[4,175],"5-2A":[4,204],"5-2B":[4,217],"5-2C":[4,229],"5-2D":[4,242],"5-3":[4,254],"5-3A":[4,259],"5-3B":[4,271],"5-4":[4,283],"5-5":[4,328],"6-1":[5,1],"6-1B":[5,37],"6-2":[5,53],"6-3":[5,88],"6-3A":[5,118],"6-3B":[5,143],"6-3C":[5,157],"6-4":[5,178],"6-4A":[5,193],"6-4B":[5,200],"6-4C":[5,205],"6-5A":[5,214],"6-5B":[5,218],"E1":[6,1],"E1-2":[6,66],"E1-3":[6,89],"E1-4":[6,130],"E2-dive":[6,171],"E2-throw":[6,189],"E2-watch":[6,211],"E2-watch-b":[6,225],"E2":[6,233],"E2-2":[6,255],"E3":[6,292],"Z0-1":[7,1],"Z0-2":[7,23],"Z0-3":[7,50]},"cgs":[{"id":"01","title":"海底王座"},{"id":"02","title":"營火邊的歌聲"},{"id":"03","title":"沙灘救援"},{"id":"04","title":"姐姐"},{"id":"05","title":"腳踏車特訓"},{"id":"06","title":"雨夜之吻"},{"id":"07","title":"春潮祭舞台"},{"id":"08","title":"手臂上的鱗片"},{"id":"09","title":"燈塔之夜"},{"id":"10","title":"月光下的魚尾"},{"id":"11","title":"貝刃"},{"id":"12","title":"暴風雨中的救生員"},{"id":"13","title":"珍珠之淚"},{"id":"14","title":"海螺"},{"id":"16","title":"一年後的生日"}],"assets":{"bg":{},"sprites":{"女性剪影_普通":"女性剪影_普通.png","潮后_普通":"潮后_普通.png","男性剪影_普通":"男性剪影_普通.png","老闆_普通":"老闆_普通.png","裴柱現_人魚_哭":"裴柱現_人魚_哭.png","裴柱現_人魚_害羞":"裴柱現_人魚_害羞.png","裴柱現_人魚_得意":"裴柱現_人魚_得意.png","裴柱現_人魚_恍惚":"裴柱現_人魚_恍惚.png","裴柱現_人魚_普通":"裴柱現_人魚_普通.png","裴柱現_人魚_生氣":"裴柱現_人魚_生氣.png","裴柱現_人魚_笑":"裴柱現_人魚_笑.png","裴柱現_人魚_難過":"裴柱現_人魚_難過.png","裴柱現_人魚_驚慌":"裴柱現_人魚_驚慌.png","裴柱現_人魚_魅惑":"裴柱現_人魚_魅惑.png","裴柱現_哭":"裴柱現_哭.png","裴柱現_害羞":"裴柱現_害羞.png","裴柱現_得意":"裴柱現_得意.png","裴柱現_恍惚":"裴柱現_恍惚.png","裴柱現_普通":"裴柱現_普通.png","裴柱現_生氣":"裴柱現_生氣.png","裴柱現_笑":"裴柱現_笑.png","裴柱現_難過":"裴柱現_難過.png","裴柱現_驚慌":"裴柱現_驚慌.png","裴柱現_魅惑":"裴柱現_魅惑.png","陳伯_普通":"陳伯_普通.png"},"face":{"孫承完_害羞":"孫承完_害羞.png","孫承完_普通":"孫承完_普通.png","孫承完_笑":"孫承完_笑.png","孫承完_認真":"孫承完_認真.png","孫承完_難過":"孫承完_難過.png","孫承完_驚訝":"孫承完_驚訝.png"},"cg":{},"bgm":{},"se":{"breath":"breath.mp3","long-kiss":"long-kiss.mp3","short-kiss":"short-kiss.mp3","刷和弦":"刷和弦.mp3","撥和弦":"撥和弦.mp3"},"ui":{}}};
